/* 令和5年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r05.committeeSessions.push(...[{"id":"r05-20231010-4","meetingId":"r05-c-settlement","date":"2023年10月10日","dateIso":"2023-10-10","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時３４分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を162件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"澤田委員","kind":"質問","question":"皆様、おはようあります。本日もどうぞよろしくお願いいたします。３６７ページ、防災普及教育費、普及啓発経費、３５５ページ、しながわ水族館運営費についてお伺いいたします。３６７ページの普及啓発経費です。防災普及教育費、普及啓発経費として、３５２万３,４６２円が計上されていますが、普及啓発としてどのような取組を行っていらっしゃるのでしょうか。お聞かせください。","respondent":"平原防災課長","answer":"普及啓発経費につきまして、お答えいたします。防災課では、防災に関する普及教育として、しながわ防災学校、しながわ防災体験館、防災フェアなどの取組を行っているところです。","voiceIndex":6,"id":"exchange-001"},{"speaker":"澤田委員","kind":"質問","question":"一方で、品川区には多くの高層マンションが建設されておりますが、町会・自治会への参加率は低いとのお声もお聞きしております。区としても、先ほど課長がおっしゃっていたように、区内の高層マンションを対象にマンション防災アドバイザーを派遣されていると思いますけれども、現在行われているマンション防災アドバイザーの成果や課題をお示しください。","respondent":"平原防災課長","answer":"課題ですが、防災に関心のあるマンションにつきましては取組が進んでいるところですけれども、１名のアドバイザーで実施しているということもございまして、多数のマンションをカバーするまでには至っていないという状況にあります。","voiceIndex":8,"id":"exchange-002","title":"町会・自治会支援"},{"speaker":"澤田委員","kind":"質問","question":"今現在、防災アドバイザーの方がお１人しかいらっしゃらない中、多くの需要があると思うのですが、大変すばらしい取組である反面、多くのマンションをたったお１人で回られるのは大変だと思います。防災訓練が週末の土日に行われることも多いことを考えますと、１年間で回れるマンションの数は限られてしまうのではないでしょうか。","respondent":"平原防災課長","answer":"対象マンションにつきましても、これまで進めておりました１０階以上のマンション、高層マンションというふうに扱っておりましたけれども、そちらから、３階以上かつ１５戸以上のマンションまで拡大することを考えてございまして。","voiceIndex":10,"id":"exchange-003"},{"speaker":"澤田委員","kind":"質問","question":"３階以上のマンションに変わったということで、より多くのマンションが対象になったと思いますので、マンションでの防災訓練を望む多くの区民の方々のニーズにお応えいただけるよう、マンション防災アドバイザーのより一層の拡充のための体制の整備をお願いいたします。続きまして、３５５ページ、しながわ水族館運営費についてお伺いいたします。現在の進捗状況をお聞かせください。","respondent":"高梨公園課長","answer":"今年度に入りまして、７月より事業者公募の受付を開始いたしまして、これまで事業者からの提案の説明やヒアリングなどを実施してきたところです。","voiceIndex":12,"id":"exchange-004"},{"speaker":"澤田委員","kind":"提案","question":"そこでお伺いしたいのは、今までも多くの委員が一般質問や委員会で、リニューアルした際の夜間営業を提案されてきたと思いますが、子どもだけでなく、大人がデートなどでも訪れられるように、改めて私からも夜間営業を要望いたします。実現に際して、課題や配慮すべき内容について、現在、区としてはどのようにお考えでしょうか。お聞かせください。","respondent":"高梨公園課長","answer":"大井競馬場など周辺の施設とのコラボレーション・連携なども、これから決定する事業者と共に検討を進めてまいりたいと考えています。","voiceIndex":14,"id":"exchange-005"},{"speaker":"澤田委員","kind":"意見","question":"リニューアルすることが決まっているのですけれども、まず、そこまでも運営していて大事な時間だと思いますので、リニューアルが決まっていることを逆手に取って、この後、水族館の工事予定が決まり、閉館期間が決まりましたら、ＳＮＳなどで、今のしながわ水族館を見られるのは、一時閉館までの、あと例えば３００日というような形でリニューアルの前後を楽しむことをアピールすることや。","respondent":"高梨公園課長","answer":"ホームページやＳＮＳをはじめ、様々な媒体でしながわ水族館のリニューアルについて区民の皆様に知っていただき、参加していただけるよう、積極的に取り組んでまいりたいと考えています。","voiceIndex":16,"id":"exchange-006"},{"speaker":"ゆきた委員","kind":"質問","question":"私からは２点、お伺いいたします。３６５ページの感震ブレーカー普及経費、また３３７ページの無電柱化推進事業について、それぞれお伺いしてまいります。初めに、感震ブレーカー普及経費から質問いたします。品川区では、平成２８年度から不燃化特区地域での補助制度が推進されていると思われますが、今年度の助成実績、また今年度までの累計の助成実績について、お聞きできればと思います。","respondent":"羽鳥防災体制整備担当課長","answer":"令和４年度までの実績が確定しているものですが、令和４年度に関しましては４９件の補助をさせていただいて、累計で５５４件になります。今年度は、今、事業を進めているところですけれども、１０件程度、申請が来ていると聞いております。","voiceIndex":20,"id":"exchange-007"},{"speaker":"ゆきた委員","kind":"確認","question":"令和４年度までの累計が、たしか４３０件前後だったか、４７０件前後だったかと思いますが、令和４年に４９件、あと今年度までで５５４件ということで、着実に推進が進んでいるということを確認させていただきました。東京都の事業ですが、品川区として、この事業との連携や、この事業に合わせた取組などがあれば、ぜひ教えていただければと思います。","respondent":"羽鳥防災体制整備担当課長","answer":"は感震ブレーカーの実績についてですけれども、もう一度ご説明しますと、令和４年度までで、累計で５５４件の申請を頂いております。令和４年度単年度で４９件という数字になっております。","voiceIndex":22,"id":"exchange-008"},{"speaker":"ゆきた委員","kind":"質問","question":"中でも品川区は感震ブレーカーに対して手厚い助成をされているので、例えば企画として、ケーブルテレビ品川で取り上げるなど、東京都の事業で無償配布される感震ブレーカーを後押しするのに併せて、より一層の啓発運動をしていくチャンス、契機になるのではと思いますが、区のお考えをお聞きできればと思います。","respondent":"羽鳥防災体制整備担当課長","answer":"委員がおっしゃられたとおり、やはり感震ブレーカーの有効性というところの認知度が、まだまだ高まっていないのかというところもありますので、今回の東京都の事業とも併せまして、区も今後、東京都と連携して、ぜひ感震ブレーカーのＰＲを強化してまいりたいと考えております。","voiceIndex":24,"id":"exchange-009"},{"speaker":"ゆきた委員","kind":"質問","question":"無電柱化推進事業について質問いたします。無電柱化推進事業は、令和２年に策定された品川区無電柱化推進事業に基づき、防災性向上のため、第一次緊急輸送道路の競馬場通り、広域避難場所周辺の文庫の森から補助第２６号線の区間を優先的に整備・推進されていると認識しています。この２路線での今後のスケジュール、完成の時期、課題などをお聞きできればと思います。","respondent":"森道路課長","answer":"今現在、２路線で無電柱化の計画実施を進めておるところですけれども、競馬場通りにつきましては令和１１年度の完成を目指して進めております。文庫の森から補助第２６号線につきましては令和８年度という形です。","voiceIndex":26,"id":"exchange-010"},{"speaker":"ゆきた委員","kind":"提案","question":"無電柱化促進事業について、私の前任の、たけうち忍元区議会議員が昨年の一般質問で提案された内容ではありますが、現在、区が道路の空洞調査を委託している事業者では、地下埋設状況を３Ｄデータ化によって可視化し、他自治体での活用も進み、予算削減と工期の短縮につながっていると、たけうち忍元区議会議員が質疑されていましたが、その後の進捗状況について。","respondent":"森道路課長","answer":"ですので、今ご提案いただきました３Ｄデータというよりは、今、既存のデータをしっかりと確認していくというところと、それから、今の３Ｄデータにつきましては、今後の技術的な状況をしっかりと注視していきたいと考えております。","voiceIndex":28,"id":"exchange-011"},{"speaker":"山本委員","kind":"質問","question":"本日もよろしくお願いいたします。私からは、３３１ページ、駅周辺等放置自転車対策事業、３５５ページの、Ｐａｒｋ－ＰＦＩ導入に向けた調査・検討、時間次第で３４９ページの広町地区整備検討について伺います。３３１ページの駅周辺等放置自転車対策事業について伺います。空き情報は、大井町駅など区内１５駅にある駐輪場の空き台数がリアルタイムで分かるというものです。","respondent":"工藤交通安全担当課長","answer":"１つは、Ｓｕｉｃａなどの交通系ＩＣカードを使ったもの、もう一つは、ＰａｙＰａｙなどのＱＲコードを使ったものとなります。利用率ですが、交通系ＩＣカードは７０％、ＱＲコードが５％といった状況です。","voiceIndex":32,"id":"exchange-012"},{"speaker":"山本委員","kind":"確認","question":"ウェブサイトは７か月で累計１万２,０００回ということですから、１か月で約１,７１０回、１日で大体５７回。それなりに利用されているという印象です。例えば五反田駅には、３か所に当日利用の駐輪場がありますが、向かうときに空き情報を確認しておけば、安心して効率的に利用できます。ウェブサイト上でも探しやすい、目につきやすい工夫をお願いできませんでしょうか。区のお考えをお伺いいたします。","respondent":"工藤交通安全担当課長","answer":"こういった情報があるということを広く知ってもらうことが大事でありますので、委員から頂いたご提案を含め、情報掲載の方法については、どんな形がいいのか検討してまいりたいと考えています。","voiceIndex":36,"id":"exchange-013"},{"speaker":"山本委員","kind":"提案","question":"ぜひ進めていただきたいと思います。それから、さらに幾つかご提案申し上げます。区民にとって日常的に使っているスマホ上から情報を簡単に引き出すことができる、アプリで展開するというのはいかがでしょうか。区民にとって、様々な情報を取り出しやすくする、とても大事な視点であると考えます。せっかくのデータですので、併せて有効活用の検討を要望いたします。ご意見をお聞かせください。","respondent":"工藤交通安全担当課長","answer":"アプリの展開につきましては、こちらは全庁的に関係するものとなってまいりますので、関係部署と連携しながら研究してまいりたいと考えています。データ活用につきましては、今後の駐輪場運営のよい資料となると考えていますので、積極的に活用を図ってまいりたいと思います。","voiceIndex":38,"id":"exchange-014"},{"speaker":"山本委員","kind":"提案","question":"せっかくいいツールなので、ぜひ区民の皆様にもっと使っていただけるよう、分かりやすい情報展開の工夫と、データの有効活用をお願いします。次に、３５５ページのＰａｒｋ－ＰＦＩ導入に向けた調査・検討についてお伺いいたします。品川区でも、民間事業者の知恵と工夫を活かした公園整備を進めていただきたいと考えております。足元の進捗状況、今後の見通しについてお教えください。","respondent":"高梨公園課長","answer":"Ｐａｒｋ－ＰＦＩの導入につきましては、本年の６月ですが、公募対象とする公園を東品川海上公園として設定いたしまして、現在はこれから行う予定の公募に向けまして、公募指針の作成に向けた準備を行っているところです。","voiceIndex":40,"id":"exchange-015"},{"speaker":"山本委員","kind":"質問","question":"これからまさに公募していくというところで、重要なポイントになってくると理解しております。この公園では、年間を通して様々なイベントをやっています。先週末も秋の運河花火まつりがあり、私も伺いましたが、多くの区内外の方が訪れており、とてもにぎわっておりました。このようなイベント運営に係る関係者や近隣の方との協議はされていらっしゃいますでしょうか。","respondent":"高梨公園課長","answer":"Ｐａｒｋ－ＰＦＩの導入に際しましては、これら魅力あるイベントとしっかり連携できるよう、地域と融合できる事業者を選定することが重要であると考えています。現在、地域の各団体とは、本事業の指針策定に向けて協議を開始しています。","voiceIndex":42,"id":"exchange-016"},{"speaker":"山本委員","kind":"質問・要望","question":"指針をつくって事業者公募をするわけですが、公募内容が重要だと考えております。品川区が条件として求める重要なものは何でしょうか。それから具体案になりますが、防災機能の強化、非常用トイレの拡充などを、公園施設整備の一つとして求めることはいかがでしょうか。先日のお祭りではトイレの混雑がありました。やはりイベントではトイレが課題となります。区のお考えをお聞かせください。","respondent":"高梨公園課長","answer":"ご提案のありました防災機能の強化についてですが、東品川海上公園が広域避難場所に指定されていることから、本事業を行う中で、防災機能の充実についての提案というところは、公募を行う上で優位となる評価項目になり得るという認識です。","voiceIndex":44,"id":"exchange-017"},{"speaker":"山本委員","kind":"提案","question":"おっしゃっていただいているように、地元の方々とよく連携して、そして水辺のよさが、さらによくなるよう、そして民間事業者のよい提案や工夫を引き出して、利用者にとってプラスとなり、特徴のある公園づくりを望みます。初めてのＰａｒｋ－ＰＦＩ制度の活用ということで、この経験を蓄積し、今後の公園整備などの中で活かしていただくことを併せて要望いたします。","respondent":"高梨公園課長","answer":"様々な場面でご利用いただいていると認識していますが、例えば犬が立ち入れる公園や施設別の類型など、まだまだ区民の皆様のニーズに合った形に改良の余地があると考えているところです。","voiceIndex":46,"id":"exchange-018"},{"speaker":"山本委員","kind":"提案","question":"いろいろとご展開いただいているですが、さらに、やはり区民の皆様に分かりやすくご案内していただきたいというところがございまして、私から何点かご提案を申し上げます。公園だけを一覧できる地図をトップページに示すのはいかがでしょうか。そのほかにも、おっしゃっていただきましたが、どんな遊具があるのか、球技で遊べるのかどうか、各公園別に見やすく示す。区として、お考えをお伺いいたします。","respondent":"高梨公園課長","answer":"区としても現状に甘んじることなく、よりよい、より見やすいホームページの作成というところで努めてまいりたいと考えています。","voiceIndex":48,"id":"exchange-019"},{"speaker":"山本委員","kind":"質問・要望","question":"ぜひお願いします。中長期的にはアプリのご検討などもしていただきたいというところで、やはりいい公園がたくさんありますので、たくさん利用してもらうために、ユーザーフレンドリー、利用者目線で分かりやすく示していくということをご検討いただきたいです。広町地区整備検討については、時間も限られておりますので、またの機会でお話しさせていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-020"},{"speaker":"安藤委員","kind":"質問","question":"３４５ページ、空港環境経費、３４８ページ、都市開発費から、品川駅南地域周辺地区、武蔵小山駅周辺地区、大崎駅西口地区の開発について伺います。羽田新ルートですけれども、１点伺いたいのですが、先月２２日の午後１０時半頃、ターキッシュエアラインズの離陸便が既定のルートを外れ、都心、品川区も通過し、東京タワー等の上空を飛行しました。伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"トルコ航空機の航路逸脱の件ですが、ご紹介いただいたように、事案の発生が９月２２日。翌日には区に第１報が届いたところです。","voiceIndex":52,"id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"正面から国に中止を求めるべきだと、改めて求めたいと思います。もう終わっている事業なわけですが、このうち事業が認可され、事業が終わり、竣工して戻ってきた方は、それぞれの地区で何人なのか、改めて伺いたいというのが１つと、竣工して結構、時間がたつのですが、再開発組合がまだ解散していないようなのですけれども、それはどんな理由なのか伺いたいと思います。","respondent":"中道都市開発課長","answer":"再開発組合が解散していないですが、今現在、最終的な資金の収め方といったところ、あとマンション、またテナントといったところを運営していくに当たりまして、やはり維持管理、実際に物事が動いていく中で修繕したいところが出てきていますので。","voiceIndex":54,"id":"exchange-022"},{"speaker":"安藤委員","kind":"質問","question":"伺うのですけれども、非公表だと言っているということですけれども、区はつかんでいるけれども答弁しない、公開しないというのか、それとも、そもそもつかんでいないということなのでしょうか。区内でも山ほど他にも再開発がされているわけですが、ほかの第一種市街地再開発事業についても権利関係はどうなのか、どれぐらいの人が戻ってきているのか等々のつかみについて伺いたいと思います。","respondent":"中道都市開発課長","answer":"区では情報を把握しています。定期的に組合と情報交換等をしています。ですので、そういったことは区はきちんと把握はしておりますが、組合のほうで、そういった情報は非公表です。ほかの地区におかれましても、区でそういった管理というのは徹底しています。","voiceIndex":56,"id":"exchange-023"},{"speaker":"安藤委員","kind":"質問","question":"把握しているけれども議会に出さないというのは、とんでもないと私は思いますけれども。パルム駅前地区には１０１億円、武蔵小山駅前通り地区には７４億円の開発補助金投入です。これだけのお金を使って、公共事業だと称して、まちづくりだと言っているのに、そのまちづくりが適正だったかどうかを検討するのに、そこのところを出さずして、どうやって検討するのですか。伺いたいと思います。","respondent":"中道都市開発課長","answer":"老朽化した建物、またインフラの整備といったことで、都市の魅力を向上させる、またはその地域の経済を活性化させるといったことも目的です。区民の方が地域で話合いを行われて、そうした中で進んでいる再開発事業ですので、区としては今後も支援していきたいと考えています。","voiceIndex":58,"id":"exchange-024"},{"speaker":"安藤委員","kind":"質問","question":"全然答えていないと思うのですけれども、では品川区は、従前に住んでいた方がどれだけマンションに戻ってきたか、住み続けられたかというのは、もう関係ないということなのですか。そこはまちづくりの成否にとって何も関係ない。だから品川区議会に出さないということなのでしょうか。","respondent":"中道都市開発課長","answer":"ですので、区議会には、情報の共有化というのは、きちんと区は行っていくつもりです。一方で、先ほどもお話ししましたが、再開発ですけれども、人々の快適性や、訪れる方を増やすといったことも効果の一つですので、総合的なまちづくりというところで進めているです。","voiceIndex":60,"id":"exchange-025"},{"speaker":"安藤委員","kind":"質問","question":"総合的なという中に、権利者がどれだけ住み続けられたか。住み続けたい住まいの権利を奪われている方が、たくさんいるわけですよね。そういう方がどれぐらいいるかというのも、総合的に検討という名の下に明かさないというのは、ひどいのではないですか。あまりに偏っていると思うのですけれども、もう一度お願いします。","respondent":"中道都市開発課長","answer":"都市再開発法第１４条にも、３分の２以上の権利者・借地権者といった形で、その合意の下に進めていくです。一方で、区としましては、もちろん３分の２をクリアしたから、まちづくりを進めるというものではございません。","voiceIndex":62,"id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"最低限、そこの情報も出さないで、どうやってチェックするのでしょうか。もう一つは、準備組合の運営についてです。組合に入っているのです。伺いますけれども、組合員からのこうした質問に答えないということはあり得ないと思うのですが、今後回答は来るということでよろしいのでしょうか。そして、区としても、早く回答を出してくださいと準備組合に促していただきたいのですが、いかがでしょうか。","respondent":"中道都市開発課長","answer":"今、準備組合に情報開示がですが、まずは区としましては、そこの中身をしっかりと把握したいと思います。それに対して、出せる情報、出せない情報というのは、基本的にはやはり準備組合で判断していただくというものになります。","voiceIndex":64,"id":"exchange-027"},{"speaker":"安藤委員","kind":"質問・要望","question":"当然、これは、準備組合が準備組合員から求められているものですから。再開発企業かもしれません。ですから、必ずこれは回答させるように、中身を把握していただいて、指導をお願いしたいと思います。ですから、私はさきの一般質問で、現況の地区内の借地権者数について伺いました。伺いますけれども、権利関係の確認を要する方が複数名いるとはどういうことなのでしょうか。伺いたいと思います。","respondent":"中道都市開発課長","answer":"再開発事業ですが、事業者は、やはり地域の方々、準備組合または組合です。借地権者におかれましては民民の契約ということもありますので、区としては、区が自ら、そこの数を把握するということはございません。","voiceIndex":66,"id":"exchange-028"},{"speaker":"安藤委員","kind":"質問・要望","question":"道路の場所が変わっています。都営住宅は、言うまでもなく、品川区に住み続けたいと願う、住宅に困窮する高齢者の方々をはじめ、もう住まいは人権ですから、この住まいを保障する大事な役割を担っています。伺いますけれども、高規格オフィス、高規格住宅とは何なのでしょうか。右上に「バス車庫等」とありまして、都営アパートという記述はありませんが、この「等」に含まれているのか、伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"今、委員からお問合せのありました資料がどのようなものかというのは、手元にないのですけれども、恐らく、協議会が作成した、準備組合の加入促進に向けた地権者向け説明資料だと思いますが、そちらには確かに「都営住宅」という文字はないのですけれども、基本的には当然。","voiceIndex":68,"id":"exchange-029"},{"speaker":"安藤委員","kind":"確認","question":"はっきりと残すと言わないのです。「残るよ」というやじもありましたけれども、肝腎の行政からないのです。ですから、私はそこをはっきり伺いたいのですが、では残すということでよろしいですか。そこを確認させてください。そして区は、仮にこの地域に都営住宅がない内容の開発計画でも容認・支援するという立場なのでしょうか。伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"今後、協議内容におきましては、区には適宜報告があるかと思いますが、区としましては、全体を考えて良好な住環境を整備するよう、協議会には求めているものです。","voiceIndex":70,"id":"exchange-030"},{"speaker":"筒井委員","kind":"提案","question":"そこで、カフェレストランなど飲食施設ということで、施設というのは方向的には、それで決定の方向なのでしょうかということと、資料で提案箇所として挙げられているところが、今現在、「ミッフィーお花のひろば」というところになっておるのですけれども、この提案箇所のままでよろしいのでしょうか。","respondent":"高梨公園課長","answer":"場所につきましても、今、区が考える候補地として、ミッフィーの辺りといったところは、確かに有力な候補地としては考えられているところではありますが、ここも場所を限定することなく、東品川海上公園の中で事業を実施する場所というところで、事業者からの提案を。","voiceIndex":73,"id":"exchange-031"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。なので、安定的に収益を相当程度稼げる施設、それをしっかり運営できる事業者にならないといけないと考えておりますけれども、その点は大丈夫なのでしょうか。そうした事業者・施設に対して、いかがお考えなのでしょうか。","respondent":"高梨公園課長","answer":"当然のことながら、提案する機関におきまして、しっかりと安定して整備・管理を行っていただく事業者を、公募によって選びたいと考えています。","voiceIndex":75,"id":"exchange-032","title":"町会・自治会支援"},{"speaker":"筒井委員","kind":"提案","question":"ぜひよろしくお願い申し上げます。提案箇所もまだ未定ということですけれども、既存の場所にそうした施設をつくられるということなのですけれども、結局、そこに今まであった遊具や木はどうなるのだというお声も一方であります。施設の高さはあまり圧迫感のないようなものにしたほうがいいのではないかという、いろいろなお声がありますけれども、その辺りはいかがお考えでしょうか。","respondent":"高梨公園課長","answer":"施設建設によって、今もおっしゃっていただいている緑が失われるといったことも、あってはならないと考えていますので、仮に施設建設で木を移植しなければいけないようであれば、しっかりと移植の計画が立っているかというような視点で。","voiceIndex":77,"id":"exchange-033"},{"speaker":"筒井委員","kind":"提案","question":"当然、水辺を活かしたということで、目黒川・運河の水質改善はもちろん、東品川海上公園の特に噴水広場や、この提案箇所の辺りというのは照明が非常に暗くて、区民の方、特に女性の方から、夜歩くのが怖いというようなお声が届いております。これは事業者が負担するのかどうか、今後分からないのですけれども、その辺りの環境整備ということもぜひ行っていただきたいのですけれども、いかがお考えでしょうか。","respondent":"高梨公園課長","answer":"今、委員からご案内がありました海上公園の課題につきましては、早急に現地を確認させていただいて、照明やトイレの鏡といったところについては、通常の公園の管理の中で迅速に、業者が決まる前に対応させていただきたいと考えていますので、よろしくお願いします。","voiceIndex":79,"id":"exchange-034"},{"speaker":"筒井委員","kind":"質問・要望","question":"これは結構、前々から私は要望していたところなのですけれども、これを機に、ぜひよろしくお願い申し上げます。続いてマンション管理支援事業で、マンション管理計画認定制度についてお伺いいたします。これはもっともっとメリットをアピールして、各マンション、また各マンションを管理している管理会社に対して周知すべきだと考えているのですけれども、その点、いかがお考えでしょうか。","respondent":"竹田住宅課長","answer":"こちらの認定の申請の手続は若干複雑なところがありますので、管理組合に丁寧にご説明し、また管理組合の意思決定に大きな影響を及ぼす管理会社にも積極的にＰＲしまして、認定件数の増加に努めてまいりたいと考えております。","voiceIndex":81,"id":"exchange-035"},{"speaker":"筒井委員","kind":"質問・要望","question":"それで、ＲＮＰ＋ＷＰガイダンス付きというのは、進入復行点以降、ウェイポイントを参考にしながらパイロットの目視により進入する方式で、要はカーブするときと、それ以降は、パイロットの目視ということで着陸していくということなのですけれども、今後のスケジュールで見ますと、まず２０２３年度、「評価（３ｒｄ）」、「運航者合意形成」の辺りの時期なのかと想定しているのですけれども。","respondent":"鈴木都市計画課長","answer":"区としましては、第５回で示された内容とともに、今現在、国で行っているところが、今紹介いただいた２方式について、曲線で入る方式になるわけですが、これの技術的検証と評価について、今、鋭意、国で行っているというのは再三伺っているところですが。","voiceIndex":83,"id":"exchange-036"},{"speaker":"筒井委員","kind":"質問・要望","question":"そういった状況だということですけれども、目視での着陸ということで、そろそろ運航者、パイロット側との調整・確認が必要で、目印となる建物の確認などといった具体的ルートを基に、いろいろな調整にもうそろそろ入るかと思うのですけれども、品川区はこうした具体的な飛行ルートをぜひ把握していっていただき、今後の国土交通省と区の議論で必要になることですから、分かり次第、速やかに。","respondent":"鈴木都市計画課長","answer":"現在の検討状況、それから、それが品川区にどういう形で落とし込まれていくのかというところも含めて、具体的に早急に国に示していただけるように、これまでも申し入れてきていますが、今後も強くしっかりと申入れをしていきたいです。","voiceIndex":85,"id":"exchange-037","title":"町会・自治会支援"},{"speaker":"せらく委員","kind":"質問・要望","question":"子どもの練習試合の付添いで、８月にオープンしたての、しながわ区民公園の北側ゾーンにありますこどもサッカー場に伺いました。公園の熱中症対策で伺っていきます。公園の設計段階からの暑さ対策、日陰づくりという点をお聞きしたいのですが、夏場は遊具が熱くなってしまうので、遊具の設置には方角が考慮されていると、会議録で確認しました。","respondent":"高梨公園課長","answer":"そういったものを、人がよく集まるであろう箇所に、設計の段階で設置し、日陰をつくるというようなしつらえ、それと、ほとんど現在は、元ある公園を新しく再整備するというような工事が主になってありますが、高木、木の緑陰というものも貴重な日陰ですので。","voiceIndex":88,"id":"exchange-038"},{"speaker":"せらく委員","kind":"質問","question":"日よけに対しての考え方は理解いたしました。直射日光やその日の暑さによりますが、大体５０度から６０度、場合によっては７０度近くまで上がると言われています。それに加えて、走ったりすると摩擦熱が発生します。このようなご意見は、これまで区に届いていますでしょうか。解決策として周知していることがありましたらお知らせください。","respondent":"高梨公園課長","answer":"は水分補給と、夏の気温が高いときには無理をなさらないでというようなところを、公園管理事務所等を通じて注意喚起していますが、やはりサッカー場における芝の選定につきましては、様々、利用者の方々とお話合いをしながら、天然芝よりもやはり人工芝がいいというご要望で。","voiceIndex":90,"id":"exchange-039"},{"speaker":"せらく委員","kind":"質問","question":"現在、区民公園へのアクセス方法は、京浜急行の立会川駅と大森海岸駅から各徒歩５分、もしくは大井町駅から、しながわ水族館行きの無料送迎バスが出ていて、この無料送迎バスを利用して区民公園にいらっしゃる方も多いのではないかと思っているのですが、しながわ水族館のリニューアルも計画していて、リニューアル工事中、一時閉鎖したときの無料送迎バスの運行については。","respondent":"高梨公園課長","answer":"区民公園へのアクセスに関しましては、特に水族館に関しましては、大井町から無料で結ばれるルートは非常に重要なルートであると区は認識していますので、基本的には今後、リニューアル後も継続することを前提に考えてまいりたいと思ってあります。","voiceIndex":92,"id":"exchange-040"},{"speaker":"せらく委員","kind":"意見","question":"まだリニューアルの基本計画もこれからだと思いますが、区民の皆様のニーズに応えていただきまして、リニューアル後、来場者の増加も見込まれると思いますので、場合によっては増便など、状況に合わせてご対応をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":94,"id":"exchange-041"},{"speaker":"横山委員","kind":"質問・要望","question":"私からは、３６５ページ、防災関係組織経費、３６７ページ、応急活動対策費についてお伺いいたします。私は、２０１７年７月と２０２０年９月の一般質問で、災害対応力を強化するため、女性、要配慮者や子育て経験者など、経験をお持ちの方々のご意見をダイレクトに反映していただきたいことや、防災会議における女性委員についてお伺いいたしました。","respondent":"平原防災課長","answer":"一方で、防災会議委員につきましては、いわゆる防災関係機関の充て職ですので、区単独では直ちに達成というところは難しいと認識しておりますが、一方で、防災を考える上で女性視点というのは極めて重要だと考えていますので、他自治体の取組などを参考に。","voiceIndex":96,"id":"exchange-042"},{"speaker":"横山委員","kind":"質問・要望","question":"進んでいるということで、早期に１５％、今後は令和７年度に３０％を目指していくということで、区ができることはしっかりやっていただいているということが確認できたのでよかったと考えています。次に、行政評価シートの５７７ページにあります災害時応急物資確保費についてお伺いいたします。","respondent":"羽鳥防災体制整備担当課長","answer":"物資の輸送と管理についてご質問いただきました。集中と分散の再編成ですけれども、現状、区内５か所の大型倉庫を集中倉庫といたしまして、人力では輸送が困難な大型の物資など、パレット積みで備蓄しています。","voiceIndex":98,"id":"exchange-043"},{"speaker":"横山委員","kind":"確認","question":"様々準備していただいているということが確認できましたので、よかったと安心しております。引き続き、様々整備していただく部分というのもあるかと思いますので、進めていただけたらと考えています。国重点訓練、都道府県主導訓練、そして実動・図上訓練、図上訓練というのと実動訓練、３種類あるようなのですけれども、それぞれ簡単にどういった訓練なのかをご説明ください。","respondent":"伊藤災害対策担当課長","answer":"図上訓練につきましては、こちらは実際には動くことはございませんが、図面や地図などを使用しまして、災害対策本部等におきましてメンバーが集まりまして、どのように災害が発生した場合に活動するか検討する会議です。","voiceIndex":100,"id":"exchange-044"},{"speaker":"横山委員","kind":"確認","question":"訓練の想定について、武力攻撃予測事態と緊急対処事態の想定というのがあるかと思うのですけれども、それぞれどういった内容が想定されているのか簡潔に教えてください。今年度は、弾道ミサイルを想定した住民避難訓練が３６の県と市で実施される予定となっていますが、国と都と区との住民避難訓練の現状と、国と地方公共団体の共同訓練や住民避難訓練の重要性について、区のご見解をお伺いいたします。","respondent":"伊藤災害対策担当課長","answer":"しかしながら、年に２回ですけれども、自衛隊、消防、警察と、情報連絡会という形で情報共有を図っておりまして、どのようなことが我々は地域住民に対してできるのか、どのように対応していくべきなのかということを検討してございまして、今後の国民保護についても。","voiceIndex":102,"id":"exchange-045"},{"speaker":"横山委員","kind":"意見","question":"万一の有事に備えて国民保護計画が現実に運用できますように、国や都の最新情報を注視しながら、随時見直しをお願いしたいと思います。平時において地道に築いてきた顔の見える関係や信頼関係を、長期的には防災協定等の締結に限らず、双方の強みを活かして協力体制の強化へとつなげてください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":104,"id":"exchange-046"},{"speaker":"まつざわ委員","kind":"質問","question":"私からは、決算書３４５ページ、都市防災まちづくり事業費の中から用地取得費と、３６５ページの防災関係組織経費の全般について質問します。都市防災まちづくり事業費、用地取得費、５００万円余は、木密解消のための土地取得だと思いますが、この５００万円余という数字がどの土地を取得した経費なのかお示しください。","respondent":"小川木密整備推進課長","answer":"令和４年度の用地取得の内容ですが、令和４年度は、用地の取得に係ります土地の測量委託、また物件調査、鑑定評価委託を計上させていただいているのと、あとは豊町五丁目ののんき通りにおける道路拡幅用地、約１.６平米の取得費といった内容になってあります。","voiceIndex":106,"id":"exchange-047"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"そうですね。防災公園の用地。前にもお話ししました、人と人との話合いの中なので、ぜひ丁寧に進めていただきたいと思っています。消防団の倉庫を保持していない分団というのが、私の荏原消防団の管轄は、３分団、そして４分団あります。権限は東京都にあるから、消防団と品川区の関係というのは、どうしても弱くなってしまうのです。はその辺の区の考え方からお示しください。","respondent":"伊藤災害対策担当課長","answer":"消防団と区の関係につきまして１つの例を挙げしますと、現在実施している各地区での総合防災訓練におきましては、事前の説明会から、その地域の分団長にご参加いただきまして、区側と防災区民組織の皆様と、連携を取っていただいているような状況です。","voiceIndex":108,"id":"exchange-048"},{"speaker":"まつざわ委員","kind":"質問","question":"そうですね。地域防災計画にあって、訓練の中で私たちも一緒にやっているというのは実際に分かっております。例えばこういった計画の中に、消防団の倉庫を盛り込んでいくとか、例えば中延も再開発のまちづくりというのが起こり始めています。消防団というのは区民の命を守るために活動しているのですから、どうしたらできるかというのを考えていくのが重要であると考えています。ご見解をお聞かせください。","respondent":"伊藤災害対策担当課長","answer":"本件につきまして、防災課だけで考えられる問題ではないと考えますので、情報を共有化しまして、今後、検討させていただきたいと存じます。","voiceIndex":110,"id":"exchange-049"},{"speaker":"まつざわ委員","kind":"提案","question":"消防団も、また住民の方も、団の倉庫というのは早急な対応を求めていますので、しっかりと品川区から、一生懸命やっていただいておりますが、それ以上に頑張ってやっていただきたいというのが本心です。私の分団でも経験しました。例えば区で所有する公有地活用、旧荏原第四中学校、また新庁舎といった中に、訓練場所を確保していただくなどの対応を求めますが、ご見解をお聞かせください。","respondent":"伊藤災害対策担当課長","answer":"現在、各地区で実施されております防災訓練におきましても、最後には消防団に見事な放水をやっていただいているということで、訓練の重要性・必要性が重々把握できております。","voiceIndex":112,"id":"exchange-050"},{"speaker":"まつざわ委員","kind":"意見","question":"消防団の話は最後にしますけれども、通常の火災活動では、消防団というのは消防本部の指揮下に入ります。これは大規模災害では、団として指揮命令系統を持てるようにするなど、例えば通常火災と大規模災害の違いを検討していかなければならないかと思っています。要は、消防団が大規模災害においてはどう動いていくのかということです。ぜひご見解をお聞かせください。","respondent":"伊藤災害対策担当課長","answer":"貴重なお話をありがとうございました。大規模災害時に消防団が指揮命令系統を持つことにつきまして、いろいろ有効な点、また難しい点があると思いますが、こちらにつきましても、国や東京都の動向を注視して、情報収集に努めてまいります。","voiceIndex":114,"id":"exchange-051"},{"speaker":"まつざわ委員","kind":"質問","question":"防災学校についてお聞きします。防災士の資格取得に助成金をつけるべきだと質問しました。これは本当にすばらしいので、例えばこの防災学校の講習を修了したら、区で認めた資格を発行するのはどうでしょうか。品川区版の防災士です。助成金がつかないなら、こういった資格を利用して、ふだんは防災をリード、指導して、有事の際、判断ができる人材を育てていくべきと考えますが、ご見解をお願いします。","respondent":"平原防災課長","answer":"今後、周知に努めてまいるほか、様々なコースを充実させていただきたいと考えています。","voiceIndex":116,"id":"exchange-052"},{"speaker":"新妻委員","kind":"質問","question":"私からは、３３７ページ、橋梁維持管理費、３３９ページ、舟運活性化、３５３ページ、公園・児童遊園整備費から伺ってまいります。最初に、ペデストリアンデッキがいつ設置されたのか、そしてこのデッキの改修計画というのが、どれくらいの規模となって、いつぐらいなのかということをお伺いいたします。","respondent":"森道路課長","answer":"橋梁の形式や材料によって様々ですけれども、５０年や７０年といったスパンで、区としては考えているところで、今年度も点検をしておりますけれども、橋梁の長寿命化修繕計画を基に、しっかりと改修を進めていくです。","voiceIndex":119,"id":"exchange-053"},{"speaker":"新妻委員","kind":"質問","question":"３５年ぐらい、７０年という計画があるということが分かりました。このデッキから１階に降りるには、階段の利用と、ヤマダ電機の店舗内、また、きゅりあんのエレベーターがあります。このエレベーターの利用時間をそれぞれお伺いいたします。","respondent":"森道路課長","answer":"既存のエレベーターですけれども、きゅりあんのエレベーター、西友側に降りるところにつきましては、朝の８時３０分から２５時まで、もう一つの、きゅりあんの中にありますエレベーターにつきましては、８時３０分から２１時３０分までと確認しております。","voiceIndex":121,"id":"exchange-054"},{"speaker":"新妻委員","kind":"質問・要望","question":"私としては、ここは高齢の方も使われます。バス停もあります。現在使えるエレベーターがあることから、中央改札を出てすぐ右手のところに、下に降りる、タクシー乗り場に向かう階段がありますが、そこにしっかりと、エレベーターのここが使えます、利用時間は何時から何時までですと、分かりやすい表示の看板を改めて設置していただきたいと思いますが、見解を伺います。","respondent":"森道路課長","answer":"そちらに案内するというご提案をいただきまして、そちらの管理者と、しっかりと、どういった課題があるのかということは調整する必要があると思いますけれども、区といたしましても、少し看板まで離れているところもありますので。","voiceIndex":123,"id":"exchange-055"},{"speaker":"新妻委員","kind":"質問・要望","question":"早くドッグランが実現できますように、これは今後しっかりと検討を進めていただきたいと思います。現在、品川区の犬の登録数というのは、本年９月１日現在で１万３,９４７頭、今年度の事務事業概要では１万３,６２１頭の登録ということを確認いたしました。しっかり共存できる体制を品川区にお願いしたいと思うのですが、水飲み場や犬のトイレの設置についての見解をお伺いいたします。","respondent":"高梨公園課長","answer":"今のところ、犬が立ち入ることができる２０か所の公園において再整備が行われていないところで実現していないのですが、これから、しながわ花海道であったり西大井広場公園であったりということで、犬が入れる公園で再整備を予定している公園が増えてまいりますので。","voiceIndex":125,"id":"exchange-056"},{"speaker":"新妻委員","kind":"質問・要望","question":"地域のお声を聞いていただきながら、犬との共存ということをしっかりと、品川区としても推進していただきたいと思います。最後に舟運活性化についてお伺いいたします。この要因は何か、伺います。今後、満足度５０％ということを品川区が掲げられておりますけれども、この目標達成に向けての取組をお伺いいたします。","respondent":"北原河川下水道課長","answer":"水質の悪化の件についてですが、目黒川は降雨の際には下水道の水が出てしまうということで、それが臭気の原因になっていると認識しています。","voiceIndex":127,"id":"exchange-057"},{"speaker":"新妻委員","kind":"質問・要望","question":"この土日も、水辺の大きなイベントがありました。やはり水辺を求めて来る方というのは多く、品川区民の方にもいらっしゃって、屋形船の体験乗船も八潮地域で行いましたけれども、大変好評であります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":129,"id":"exchange-058"},{"speaker":"おぎの委員","kind":"質問","question":"本日は、３６５ページの防災費のところで防災相互協定について、３４３ページ、景観まちづくり推進事業についてお聞きします。先ほど横山委員から、防災協定におきましては、被災時区内物資の輸送・備蓄について、民間の事業者について、もう既に質問が出ましたので、私からは続けて、さらにほかの自治体との災害時の協定についてお聞かせください。","respondent":"平原防災課長","answer":"様々な形です。それから、協定の実効性ですけれども、全ての協定というところには残念ながらなっておりませんけれども、一部の災害時相互応援協定では、年１回訓練を行うなどして、連絡体制の確認あるいは災害時の実際の動きなどの確認を行っているところです。","voiceIndex":131,"id":"exchange-059"},{"speaker":"おぎの委員","kind":"質問","question":"様々な経緯・枠組みにおきまして協定が進んでいたということが分かりました。区外の状況ですと、やはり距離的にも随時知ることができませんので、定期的な情報共有、また共に進める防災訓練などの活動、非常に心強いと思います。今後、ほかの自治体から打診があった場合は、さらに協定先を増やすということは予定していらっしゃいますでしょうか。","respondent":"平原防災課長","answer":"他自治体から、品川区とそのような形でというふうになりましたら、実際に話合いを進めながら、どういったことができるのか、相互にどのようなメリットがあるのかといったことを検証しながら、最終的には協定という形までいければと考えているところです。","voiceIndex":133,"id":"exchange-060"},{"speaker":"おぎの委員","kind":"提案","question":"景観まちづくり推進事業についてお聞きします。例えば旧東海道品川宿地区の店舗の建て替えには、宿場町の雰囲気と調和したデザインや色彩の提案など、なるほどと思いますが、この景観アドバイザーというのはどういった業者の方で、委託料は案件ごとなのか、または品川区トータルでアドバイスをしていただいているのか、委託内容をお聞かせください。","respondent":"鈴木都市計画課長","answer":"委託の費用につきましては、アドバイスを受けた案件ごとではなくて、決算書に記載のとおり、一括して委託しているというような状況です。","voiceIndex":135,"id":"exchange-061"},{"speaker":"おぎの委員","kind":"質問","question":"ただいま、相談の件数の実績はどれぐらいでしょうか。","respondent":"鈴木都市計画課長","answer":"アドバイザーの委託の件数ですが、令和４年度の実績が２２件ございまして、延べ８６人の方にご相談いただいているというような状況です。","voiceIndex":137,"id":"exchange-062"},{"speaker":"おぎの委員","kind":"質問・要望","question":"区民の方々の暮らしのほかに、観光や歴史景観としてのまちづくり事業ということで、ぜひ住民の方とよく話し合って進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":139,"id":"exchange-063"},{"speaker":"ひがし委員","kind":"質問・要望","question":"目標値の設定として、令和４年度は区民要望件数が８００件以下となっておりますが、目標設定の根拠、また今年度の結果として区民からの要望件数は９６６件となっておりますが、この結果は区としてどのように捉えているのでしょうか。最後に交通安全啓発費についてですが、現在、品川区内の音の出る信号機は、午後８時から朝８時までは音が鳴らないようになっているものが多いと伺っております。","respondent":"森道路課長、伊藤災害対策担当課長、工藤交通安全担当課長","answer":"これによって、区民から陳情を頂いておりますけれども、それを早期にこちらで把握できて、すぐに対応が可能と考えておりまして。委員ご案内のとおり、今年５月に実施いたしました避難所開設訓練におきましては、視覚・聴覚障害者の方々に実際に訓練会場に足を運んでいただきました。ですが、都内の一部地域に、アプリの活用を試験的に実施している音響式信号機がありますので、他区の状況を参考にしながら。","voiceIndex":142,"id":"exchange-064"},{"speaker":"ひがし委員","kind":"質問・要望","question":"このようなアプリの利用というものをぜひ進めていただきたい。恐らく東京都で作成したアプリで、アプリ名は変えられないのではないかと思うのですが、せめてページ上のタイトルのところに、「しなみちレポート（アプリ名、My City Report）」にするなどして、一目で分かりやすくするなどの工夫をしてはどうかと思いますが、いかがでしょうか。こちらは要望とします。","respondent":"森道路課長","answer":"ホームページや広報紙への頻度についてですけれども、広報につきましては、より効果的なものを考えていきたいと思いますし、ホームページにつきましては、確かに、しなみちレポートとMy City Reportというのが、なかなかどちらも変えにくいので。","voiceIndex":146,"id":"exchange-065"},{"speaker":"やなぎさわ委員","kind":"質問","question":"「非常に満足度が高い」、「地域振興につながっている」という意見が、利用者で７０％を超えていますし、利用者でない無作為の方でも５０％、シティプロモーションも同じような結果になっておりますし、自由意見の中でも、感謝、お褒め、応援という意見が非常に多いということで、これからも新たなルート、荏原や大崎ルートを早急に運行していただけると考えてよろしいでしょうか。","respondent":"鈴木都市計画課長","answer":"コミュニティバス運行開始に当たりましては、様々、１１の指標や、より効果的な地域の新設などの検討を行って、候補ルート案、３ルートを決定しまして、その中で一番効果が高いとされる大井ルートで、まずは実施したです。","voiceIndex":150,"id":"exchange-066"},{"speaker":"やなぎさわ委員","kind":"質問","question":"その指標の中には、収益、収支率というのも重要な項目になっておりますでしょうか。","respondent":"鈴木都市計画課長","answer":"大井ルートの判断基準につきましては、収支率５０％というところを１つの判断基準にしています。","voiceIndex":152,"id":"exchange-067"},{"speaker":"やなぎさわ委員","kind":"質問","question":"これは１つの公共サービスと位置づけていただければと考えておりまして、例えば明石市です。１５本ルートがある。それで料金が安いのです。１００円ということで、子どもは５０円となっております。コミュニティバスは、やはり気軽に使えるというのが１つ大きなポイントになると思うので、ぜひその辺、収益率にこだわらず利便性を重視してほしいと考えているのですけれども、お考えはいかがでしょうか。","respondent":"鈴木都市計画課長","answer":"昨年度も今年度も予定していますが、沿線住民の方あるいは利用者の方にアンケートを取りながら、来年度しっかり判断をしていきたいですが、まずはこの指標を中心に、様々なアンケートやお声も、頂いた内容を精査しながら総合的に判断していきたいです。","voiceIndex":154,"id":"exchange-068"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"そうですね。なるべく予防させる。そういうときは、介護事業者や介護職員の人が、しっかり働けるような、運営できるような環境を整えてあげるというふうにしていただきたいと考えていますので、要望ですけれども、ぜひそういったことも考えていくなど、これから新たな路線をぜひ前向きに検討、そして早急にできれば、要望が本当に多いので、皆さん助かっている方も多いので、ぜひよろしくお願いいたします。","respondent":"鈴木都市計画課長","answer":"ルートを選定していくに当たって、そうした施設について、できるだけ近くを通るルートを設定するということは、基本的な考え方として持ってありますので、今後、残りの２ルートを実施していくに当たっては、そうした視点もしっかり持ちながら検討を進めていきたいです。","voiceIndex":156,"id":"exchange-069"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"Ｐａｒｋ－ＰＦＩは、一言、要望です。公園というのを考えたときに、ＰＦＩはいいのですけれども、やはり地域の方の憩いの場というものを考えていただきたいので、にぎわいだけではなくて、地域の方が楽しめるということもしっかり考えていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":158,"id":"exchange-070"},{"speaker":"こしば委員","kind":"質問・要望","question":"私からは、３４５ページ、都市防災まちづくり事業費に関連しまして井戸の活用について、同じページの自転車活用推進計画策定検討経費に関連しましてシェアサイクルについて、３５５ページ、おもてなしトイレ整備について、順にお伺いいたします。今年は関東大震災から１００年目に当たりました。今では公助に当てはまると思いますが、当時は誰もが助け合って供給したのが水ではないでしょうか。","respondent":"羽鳥防災体制整備担当課長","answer":"井戸についてのご質問です。区内にどれだけ民間の井戸があるかですが、詳しい数字は把握しておりませんが、５０か所程度ではないかということで認識しているところです。","voiceIndex":160,"id":"exchange-071"},{"speaker":"こしば委員","kind":"質問","question":"今、５０か所という答弁がございました。スイカを冷やした。２つ目は、災害時に近隣の方へ無償で井戸水を提供できること。ほかの自治体も、一定、井戸の活用をされている中で、品川区でもぜひ、震災時の避難生活の安定化に向けまして井戸を活用できるような環境を、特に震災時に協力してもらう井戸に認定し、一定の補助をつけるなど、環境を整えてもらいたいと考えますが、ご見解をお伺いいたします。","respondent":"羽鳥防災体制整備担当課長","answer":"委員ご案内のとおり、品川区内には、都心にいながら路地に手押しポンプ型の井戸があるというところは、品川区ならではの魅力的な風景の一つであると認識しています。","voiceIndex":162,"id":"exchange-072"},{"speaker":"こしば委員","kind":"質問・要望","question":"ただ、私もこの一、二か月、シェアサイクルを利用する中で課題が見えてきたのもまた事実でございまして、それが２つあります。そうすることで、例えば事業者と連携しまして、町会の掲示板、地域センターなどで、場所の貸出しに応じてくれる人、もちろんこれは有償ですが、そういったことを募集するなどすれば、今の１つ目の課題解決にもつながってくると思いますが、ご見解をお伺いしたいと思います。","respondent":"櫻木土木管理課長","answer":"ただ、区としては基本的には普及拡大を進めているところもありますので、頂いたご意見も踏まえながら、事業者と連携して進めていきたいと考えています。","voiceIndex":164,"id":"exchange-073"},{"speaker":"こしば委員","kind":"質問・要望","question":"課題の２つ目です。というのは、全域にというのは、既存の公園、特に品川区を見てみますと、東品川海上公園に２か所、天王洲公園、東品川公園、しながわ区民公園に２か所、鈴ケ森公園、小関橋公園、文庫の森に２か所と認識しております。駅周辺の違法駐輪解消にもつながります周辺の公園に、ぜひサイクルスポットを設置することを検討していただきたいと思いますが、ご見解をお伺いいたします。","respondent":"櫻木土木管理課長","answer":"公有地へのシェアサイクルスポットの設置についてです。基本的に、公有地につきましても、使えるところはできるだけ検討していくような方向で、これまで考えてまいりました。","voiceIndex":166,"id":"exchange-074"},{"speaker":"こしば委員","kind":"質問・要望","question":"普及拡大に努めていただきたいというのもあるのですが、先ほどコミュニティバスの話も出ていたところです。そういったところにも、公園もありますので、山王銀座商店街の辺りがありますので、ぜひそういったことも踏まえて、地域のモビリティの需要を酌んでいただきまして、要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":168,"id":"exchange-075"},{"speaker":"つる委員","kind":"質問・要望","question":"最初に応急物資を伺っていきたいと思います。今、こしば委員からもありました。食べ物については被災地外で買い求めることを勧める」と。今年ですか、東京都の慰霊協会が中心だったかと思うのですが、１００年前の子どもたちが当時の震災をどういうふうに感じたかという、当時の作文や絵を活用して、それをいろいろな区で学ぶという防災教育をやっているところもあると伺いました。","respondent":"羽鳥防災体制整備担当課長","answer":"具体的に確認させていただきながら、活用先がどこなのか、管理体制、コストなど、様々課題があると思いますので、よりよい有効活用の手法について今後検討してまいりたいと思います。","voiceIndex":170,"id":"exchange-076"},{"speaker":"つる委員","kind":"質問","question":"こうした全体界に立った施策展開をお願いしたいと思います。次に行きます。ホームページにもそうした注意があるわけでありますけれども、これが例えば、区民の方がよかれと思って投稿いただいたところが私道であった場合の対応というところでは、対応できないときもありますというエクスキューズが一応あるのですが、私道の場合の対応について現状を、概要を教えてください。","respondent":"森道路課長","answer":"私道について、もし例えばつまずいてしまいそうだなどといった、本当に緊急的に措置が必要なもの、あるいは危ないと思われるところにつきましては、区で現状を確認させていただきまして。","voiceIndex":172,"id":"exchange-077"},{"speaker":"つる委員","kind":"意見","question":"これは、先ほどマラソンの例を挙げさせていただきましたが、そこを日常、公共の用に供していただいているというのが大前提であろうかと思いますけれども、そうした中で、劣化している、また転倒してしまって、けがをしてしまうといったことを未然に防ぐという部分では、当然、私有物でありますから、そこを勝手に行政がやるということは、なかなか難しいわけでありますけれども、ただ。","respondent":"長尾建築課長","answer":"私道整備助成のお尋ねです。私道整備助成の中では、現在、道幅が１.２ｍ以上のものを対象として、２.５ｍ未満の道幅の場合は、私道の所有者の方の自己負担が１割発生する状況です。２.５ｍ以上の道幅の場合は、全額、区が負担して私道を整備している状況です。","voiceIndex":174,"id":"exchange-078"},{"speaker":"つる委員","kind":"提案","question":"いろいろな形があるので、ぜひそこは引き続き、検討いただきたいと思います。今年度最後、根上がり対策。これは、根上がり対策だけれども根下げということで提案して、記憶にある方もいらっしゃるかと思いますが、今、３か年度かけてやっていただいていて、今年度終わりというところで、桜の木であります。それに関連して、今現在、品川区内にある街路樹に対して、桜の本数が何本あるのか教えてください。","respondent":"森道路課長","answer":"現在、街路樹につきましては３,８３３本、桜につきましては、そのうち１,４６７本、３８.２％です。","voiceIndex":176,"id":"exchange-079"},{"speaker":"つる委員","kind":"質問・要望","question":"桜を増やしてほしいという強い思いを実現していただいていると思いますけれども、引き続き、品川区にたくさん交通の利便性があって品川区が選ばれるわけでありますけれども、その各駅から桜が見えるという環境を一日でも早く実現していただきたいと、そこは強くお願いして、桜がまた来年度、一本でも多く植えられていることを願って、質問を終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":178,"id":"exchange-080"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"私からは、３５３ページ、みんなに愛される公園づくり、３３１ページ、交通安全啓発費、そして３６５ページ、防災対策全般についてお伺いします。私が聞きたいのは、たばこを吸える公園というのは今あるのですか。花火をやれる公園は今ありますか。先ほど午前中の答弁の中でも、犬が入れる公園というのが少し出ていましたけれども、犬と遊べる公園があるのですか。交通安全啓発費についてです。","respondent":"高梨公園課長、工藤交通安全担当課長、平原防災課長","answer":"ただ、公共施設としての公園を、皆様の意見を聞いて、全部はかなえられないけれども、皆様の意見をアンケートないしは様々なご意見を伺う中で。これは警察と連携してになりますけれども、実施しています。ざっとのところでいきますと、先ほどの災害対策本部の中で区の応援体制もありますので。","voiceIndex":180,"id":"exchange-081"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"これは要望で終わります。本当に死にます。これは本当に真剣に考えていかなくてはいけないと思いますので、ぜひ区も警察とも連携していただいて、もちろん子どものうちから教えていただくのはそうですけれども、大人が今乗っているので、大人にどうやって対応していくのかというのは、しっかり検討していただきたいと思います。これは要望で終わりますけれども、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":184,"id":"exchange-082"},{"speaker":"鈴木委員","kind":"質問・要望","question":"私からは、３６５ページの住宅確保要配慮者入居促進事業と、それからリニア新幹線について伺いたいと思います。住民が、私たちも本当に求めてきたわけですけれども、説明会を何度どれだけ求めても、ＪＲ東海は説明会も行わずに、５月１１日に工事を再開したわけです。トラブル続きということで、これだけスムーズにいっていないということに対して、区としてどう捉えているかについても伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"これらを踏まえまして、抜本的な対応として、山側に代替ルートを計画し、リニア鉄道を導入することで、時間の短縮効果による利便性の向上と、安定した公共交通網を確保するため、ＪＲ東海が事業者の責任の下、進めている事業です。","voiceIndex":186,"id":"exchange-083"},{"speaker":"鈴木委員","kind":"質問・要望","question":"住民の不安払拭に努めていくということであれば、私はぜひ説明会を求めていただきたいと思うのです。これだけ工事がスムーズにいかなくて、シールドマシンの故障が連続して起こっているという状況なわけです。でも、そこが全く狂ってしまっているわけです。それに対して、どういう状況になっているのかということになっているわけですから、説明会を区として求めていただきたい。いかがでしょうか。","respondent":"大石まちづくり立体化担当課長","answer":"説明会の開催ですが、現状といたしましては、今回の事象に関しまして説明会の開催有無につきましては、ＪＲ東海から報告は受けてございません。区といたしましては、区民の不安の声に対して丁寧に取り組み、不安払拭を図るように引き続き求めてまいります。","voiceIndex":188,"id":"exchange-084"},{"speaker":"鈴木委員","kind":"質問・要望","question":"不安払拭のためにＪＲ東海に求めていくというのは、具体的に区としてはどういうことを行うことで、不安払拭をしてくださいということで求めていくのですか。そのためには、もう説明会。それなので、不安払拭に努めていきたいというのであれば、区からぜひとも説明会を求めていただきたい。そのことについて答えてください。","respondent":"大石まちづくり立体化担当課長","answer":"説明会の開催ですが、ＪＲ東海といたしましては、今回の事象に関しまして、今、委員ご指摘のとおり、ホームページで内容を公表しており、また、ご質問等につきましては工事事務所などで対応し、一件一件、丁寧にお答えしていくと聞いてあります。","voiceIndex":190,"id":"exchange-085"},{"speaker":"鈴木委員","kind":"質問・要望","question":"だから、どうやって不安払拭に努めてくださいとＪＲ東海に求めるのですかということで聞いているのです。もう、ホームページだけでは不安払拭にならないし、個別に電話で聞いても、本当によく分からないです。そのためには、説明会というところを、何で品川区が説明会を求めることができないのか、その点についても伺いたいと思います。説明会をなぜ求められないのかという理由についても伺います。","respondent":"大石まちづくり立体化担当課長","answer":"説明会を求める、求めないという点ですが、区といたしましては、繰り返しになりますが、区民一人一人の声に対して真摯に対応していただく、それが区民の不安払拭につながると考えています。","voiceIndex":192,"id":"exchange-086"},{"speaker":"鈴木委員","kind":"質問・要望","question":"住民に対して誠実に向き合うという姿勢で、ＪＲ東海に向き合っていただきたいということで、区もそういう立場でＪＲ東海に求めていただきたいということで、私はこの間ずっと言い続けてきているので、そういう姿勢で説明会を、ＪＲ東海に誠実に向き合う姿勢に変わっていただくためにも、何か起こったときに誠実に向き合わないということになりかねないわけですから。","respondent":"大石まちづくり立体化担当課長","answer":"住民に対して誠実に向き合ってほしいですが、区といたしましては、先ほども申しましたが、ＪＲ東海は一件一件に対して、工事事務所等を通して誠実にお答えしていくということを聞いておりますので、引き続き、区といたしましては不安払拭の解消に向けて。","voiceIndex":194,"id":"exchange-087"},{"speaker":"鈴木委員","kind":"質問・要望","question":"今まで説明してきたことと、これだけ違っているわけですから、説明させてくださいと言うのが誠実な対応です。そういう対応を、ぜひとも区としても求めていただきたい。説明会をしていただく、ＪＲ東海に説明会を求めるということで、改めて区として求めるということをしていただきたいということで、求めておきたいと思います。安全神話も崩れました。そういう中で、ぜひとも私は中止を求めていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":196,"id":"exchange-088"},{"speaker":"田中委員","kind":"質問・要望","question":"引き続き継続するということで、まちづくりが進められる。あるいは、もっと早く進行しなくてはいけないからという観点から「拡充する」という評価なのだろうと思いますが、今回、特に土木費という関連で行政評価をするに当たりましての、特に「拡充する」、「継続する」がありがちなプロジェクトに対する評価についての、１つの考え方というのでしょうか、切り口、見方をお聞かせいただきたいと思います。","respondent":"吉岡政策推進担当課長","answer":"そういった中では、委員がおっしゃっていたプロジェクトに係るような事業、あるいは計画、あるいは内部事務のようなものを全て行ってきたところですけれども、委員がおっしゃるように、評価というところで、拡充するもの、あるいは継続的に実施するもの、あるいは今回。","voiceIndex":198,"id":"exchange-089"},{"speaker":"田中委員","kind":"質問・要望","question":"そういう観点で、勝島地区の人道橋のことについてお伺いしたいのですが、立会川・勝島地区のまちづくりビジョンに基づきまして人道橋が建設されようとしています。なので、人道橋の目的としては、ほとんどが回遊性を求める橋になってしまうのか。そういう、いわゆる費用対効果という視点からの検証や検討状況はいかがなのでしょうか。お聞かせいただきたいと思います。","respondent":"森道路課長","answer":"勝島人道橋につきましては、道路課で実際の業務を行っておりますので、私からお答えしますけれども、これまで勝島人道橋の、今、委員からご紹介がありました、回遊性や防災性の位置づけであったり、利便性であったり。","voiceIndex":200,"id":"exchange-090"},{"speaker":"田中委員","kind":"質問・要望","question":"地域の方の声も、恐らく２０億円という予算を踏まえた中での要望ではないと私は思っていて、その発表がある前の段階からの要望でありまして、では具体的に２０億円かかるという前提の下での要望なのかどうかというのはしっかり検証すべきですし、事務事業評価としての、新公会計制度に基づいて、複式簿記などという見直しがなされますけれども、私はそういったものをつくる前の段階において、想定でいいので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":202,"id":"exchange-091"},{"speaker":"こんの委員","kind":"質問","question":"私からは、３３１ページ、道路・公園等監察費、３３５ページ、路面等改良費の２点を、順不同ですが、お伺いします。こちらは昭和４０年に暗渠となって、現在の遊歩道となっていると認識しております。この遊歩道ですけれども、舗装修繕計画には遊歩道の計画は見当たらないのですが、遊歩道の維持管理計画というのはどのようになっているのでしょうか。","respondent":"森道路課長","answer":"今ご紹介いただきました品川区の舗装修繕計画につきましては、舗装に大きな影響を与えるのが、大型車がどれぐらい通るかというお話になります。ですので、影響を受けるのが大きな車道ですので、遊歩道については、個々にそれぞれ陳情を頂きながらというふうに考えています。","voiceIndex":204,"id":"exchange-092"},{"speaker":"こんの委員","kind":"質問","question":"遊歩道は個々の陳情に応じてということが分かりました。基本は歩行者優先道路となっておりますけれども、生活道路として自転車も通行させていただいているという現状です。ここを毎日通行されている地域の方々からお声がありまして、事故などが起きてしまってからでは遅いので、早急に、ここの路面改良をお願いしたいという声がありますけれども、いかがでしょうか。","respondent":"森道路課長","answer":"それで、当然、路面の状態でも、少しがたつきがあるというようなことは認識しておりまして、今後、改修が必要な路線の、非常に高い優先度であると、道路課としては考えているところですので、修繕に向けて検討を様々進めていきたいと考えています。","voiceIndex":206,"id":"exchange-093"},{"speaker":"こんの委員","kind":"質問・要望","question":"優先度が高いということを確認させていただきました。ここの遊歩道は、民地の方の玄関先でもあったりして、非常に工事がしにくいところでもあるのかと想像いたします。要望で終わります。次の質問です。それで具体的に、まず、しながわ中央公園、ヘリポートがある公園ですけれども、ここの公園について、まずルールをお聞きしたいのですが、ペットの立入りについてのルールはどうなっていますでしょうか。","respondent":"高梨公園課長","answer":"しながわ中央公園の多目的広場西側部分、ヘリポートがある部分ですが、こちらについて、ペットの立入り、主に犬であろうかと思いますが、舗装されている部分のみ立入りをしていただける、草地の部分についてはご遠慮いただくということで運用させていただいています。","voiceIndex":208,"id":"exchange-094"},{"speaker":"こんの委員","kind":"確認","question":"ルールを確認させていただきました。舗装部分は大丈夫だけれども、いわゆる芝生の部分は立入禁止です。それで、その時間帯ですから、芝生にワンちゃんを放して、いわゆるドッグラン化しているということなのです。いわゆる注意喚起をしていただく方法はないかということで、１つ、看板をということがあったかと思いますけれども、今どのような対応をされているか、現状を教えてください。","respondent":"高梨公園課長","answer":"現在につきましては、一時的には改善したものの、なかなかまた戻ってしまったということですので、一定程度、継続して巡回を増す必要があろうということで、今、委員からは大変なことということでおっしゃっていただきましたけれども。","voiceIndex":210,"id":"exchange-095"},{"speaker":"こんの委員","kind":"質問","question":"夜間早朝、巡回してくださるということで、ありがとうあります。それで、今、課長がおっしゃったように、保育園の園児たちが、昼間ここは芝生の上で遊んだりしている。そうしたときに、ふん尿の問題で、大変衛生上もよくないというお声も頂いております。ですので、大きな看板などを設置していただくというのもあるかと思いますが、いかがでしょうか。","respondent":"高梨公園課長","answer":"ご提案ありがとうあります。看板も含めて検討してまいりますが、昨今、公園への禁止看板が多過ぎるというようなお叱りの声も頂いてありますので、バランスを見ながら効果的な周知・啓発方法に努めてまいりたいと考えています。","voiceIndex":212,"id":"exchange-096"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"３５５ページ、しながわ水族館と、同じページのＰａｒｋ－ＰＦＩについて伺います。しながわ水族館、大変期待しております。近隣の方とどういうふうにしていくかというのは、その時間の問題があるのだろうと考えていますが、私はやはり、ここは２１時ぐらいまでは開けられるようにしてほしいというのが１つのお願い。夏の、月に１回でもいいので、こういうこともぜひ考えてほしいと思っています。","respondent":"高梨公園課長、北原河川下水道課長","answer":"そういったところがどの程度改善していくのかというのも見定めながら、恒久的なドックランの設置の可否については検討してまいりたいと考えています。水辺との連携についてですけれども、我々としましては、さらなる魅力向上のために、今年度から来年度にかけて、仮称ですが水辺利活用推進計画を策定する予定でおりまして、その中で地元の意見も踏まえて検討していきたいと思っています。","voiceIndex":215,"id":"exchange-097"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"３６５ページの災害対策や体制は、もう本当に、災害対策担当部長の下、非常によくやれるようになっていて、多分２３区でも１番と言われるようになってきたのかと思っています。これは、もう私も二十何年間ずっと出ているし、おとといも、私の町会の理事会があって、２０人は大体いけるけれども、「駄目だ。１０人ぐらい増やしてくれ」とか、もう動員だ。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":218,"id":"exchange-098"},{"speaker":"西村委員","kind":"質問・要望","question":"３６４ページ、防災費全般から伺わせていただきたいと思います。は女性と防災について伺ってまいります。これまでも様々議論されてきたと思いますが、今回改めて、区の取組状況を伺ってまいりたいと思います。助産師の専門性を活かした災害協力協定の締結について、改めて、ぜひとも専門的視点を積極的に反映していただきたいと思いますが、今後の検討と区の見解について伺わせてください。","respondent":"平原防災課長","answer":"ただ、委員からお話がございましたとおり、そういった視点がかなり重要だということはこちらも認識しておりますので、今後、その中で話合いを拡大してまいりたいと考えています。","voiceIndex":220,"id":"exchange-099"},{"speaker":"西村委員","kind":"質問","question":"これまでも助産師会からお声があったと思いますので、一歩一歩進めていただいていることをありがたく思います。以前の決算特別委員会で、我が会派のまつざわ委員が、避難所における女性の参画促進について質問をしています。現地で活動している方や地域の会議にも、女性、男性その他、様々な状況にある方がバランスよくいる必要があると思いますけれども、現在の状況と区のお考えをお聞かせください。","respondent":"平原防災課長","answer":"ただ一方で、避難所では、これまでの災害の教訓から、女性の視点というのはかなり重要ですし、女性の視点が入った避難所運営というのは、ほかのところに比べてうまくいくという形の分析結果もあるところですので、区といたしましては。","voiceIndex":222,"id":"exchange-100"},{"speaker":"西村委員","kind":"質問","question":"そういった意味におきましては、事前に伺いましたときに防災課に行かせていただきましたら、女性の職員の方が増えているという実感がありまして、防災課内で防災対策を考える女性のプロジェクトがあるとも伺っておりますので、改めまして取組に関してお聞かせください。","respondent":"平原防災課長","answer":"あるいは、これが私どもはなかなか考えが至らなかったのですけれども、区の職員が災害時に動員するときに、女性職員がどのような形で当たることができるのかといったところも含めて検討いただいておりまして、現在まだ検討が進んでいるところなので。","voiceIndex":224,"id":"exchange-101","title":"町会・自治会支援"},{"speaker":"西村委員","kind":"質問・要望","question":"まさにそのお話を今させていただきたいと思っていたのですが、令和３年なのですけれども、当時の女性活躍担当の丸川珠代大臣が、女性の視点からの防災・復興の取組を促進するための提言というのを取りまとめておりまして、それをまとめたのが、まさに女性職員の方たちだったという資料を拝見しました。","respondent":"平原防災課長","answer":"あるいは、例えば避難所に行くにしたところで、男女バランスをどういうふうに考えるべきなのか等々といったところを含めて、現在、検討を進めているところでございまして、こちらにつきましても、また一定程度、形にできるようになりましたら取り入れてまいりたいと考えています。","voiceIndex":226,"id":"exchange-102"},{"speaker":"西村委員","kind":"提案","question":"やはり、女性の職員の方が増えてくるということは、その分、女性の声も大きくなってくるということだと本当に思いますので、引き続きお願いしたいと思います。少しお話が変わるのですけれども、これも項目がないのですが、もう一つ、違う角度からご提案させていただきたいのが、防災語学ボランティアになります。こちらは、今、何かご検討段階や、これまで検討されたことがありましたらお聞かせください。","respondent":"平原防災課長","answer":"区ではまだ、具体的に区独自で何かそういったところの取組をするというよりは、今は多言語による情報発信というようなところからスタートさせていただいているのですけれども、要配慮者のうち外国人に対してもどのような形で対応が必要かといったところは。","voiceIndex":228,"id":"exchange-103"},{"speaker":"西村委員","kind":"質問・要望","question":"実際に語学ボランティアの方にお話を伺ったのですけれども、地震のない国から来た外国人の方はなかなか実感が湧きづらいと。地域の防災訓練への参加、また災害発生時の災害情報の通訳・翻訳も必要になってくると思います。","respondent":"平原防災課長","answer":"実際に顔の見える関係でやっていただく対応というのはどうしても必要になっていくような場で、どのような形でそういった方々が確保できるのか。これはまず、大本のところの東京都の語学ボランティアを含めて、しっかりと連携しながら進めてまいりたいと考えています。","voiceIndex":230,"id":"exchange-104"},{"speaker":"木村委員","kind":"質問","question":"座ったままで、また今日もよろしくお願いします。私からは、交通安全啓発の中、交通安全運動等からですけれども、先月２１日から３０日までの間、秋の交通安全運動が全国一斉に行われたと思います。外に出ると、いろいろな場所に警察官が立って交通指導に当たっている姿を見かけました。そこでお伺いいたします。区内の自転車での交通事故発生状況と、その特徴についてお伺いいたします。","respondent":"工藤交通安全担当課長","answer":"年代別では６５歳以上の高齢者が全体の２０％を占めるといった状況です。次に、自転車利用者に対する交通安全の周知ですけれども、こちらは先ほどの答弁と重複する形になりますが、非常に重要であると認識しております。","voiceIndex":234,"id":"exchange-105"},{"speaker":"木村委員","kind":"質問","question":"区内の自転車でありましたけれども、最近は自転車利用者のルール・マナー違反が大きな社会問題になっていることを踏まえ、区としてどのような取組を行っているのでしょうか。お聞かせください。","respondent":"工藤交通安全担当課長","answer":"大人に関しましては、令和４年度から実施しました自転車安全利用指導員を、事故の多い交差点、自転車の交通量の多い交差点等に配置しまして、主に自転車の交通ルール違反者に対して直接指導するといった形で幅広く周知を図っているところです。","voiceIndex":236,"id":"exchange-106"},{"speaker":"木村委員","kind":"質問","question":"これをお願いしたいと思っています。次に、交通安全教育からです。子どもから高齢者まで幅広い世代に対し、交通安全の浸透を図っていただいているとは思いますが、さらなる周知をお願いしたいと思っています。伺います。子どもから高齢者まで幅広い層に、どのように交通安全の浸透を図っているのかをお聞きいたします。","respondent":"工藤交通安全担当課長","answer":"交通ルールの周知ということで、先ほどの答弁と少し重複しますが、子どもから大人まで、ご老人も含めて、正しい自転車の乗り方、やはりこの辺をしっかり認識されていない方もまだいらっしゃると思いますので、警察と連携しながら、様々な機会・媒体等を使って。","voiceIndex":238,"id":"exchange-107"},{"speaker":"木村委員","kind":"質問","question":"子どもから高齢者まで幅広い層に、どのように交通安全の浸透を図っているのかをお聞きしましたけれども、また働き盛りの方や子育て世代の方に対する周知はどのように行っているのかをお聞かせください。","respondent":"工藤交通安全担当課長","answer":"社会人につきましては、これも警察と連携しまして、各事業者に対して交通安全教育の開催を呼びかけ、広く周知し、交通安全をしていただくよう努めているところです。","voiceIndex":240,"id":"exchange-108"},{"speaker":"木村委員","kind":"質問","question":"自転車安全利用指導員業務委託からです。近年、自転車を利用される方が多くなったと感じています。通勤・通学に利用される方や、お買物に使われる方、小さなお子さんなどから子育てママ、高齢者の方まで、いろいろと多様に利用されています。そのせいか、車に比べて自転車の運転が非常に危険だと感じることが多々あります。伺います。自転車安全利用指導員の具体的な活動内容をお聞かせください。","respondent":"工藤交通安全担当課長","answer":"自転車安全利用指導員の具体的な活動内容についてご説明いたします。交通事故の半分を占めるのが自転車ということと、自転車利用者のルール・マナーの改善を求める声が大きいといったことから、自転車安全利用指導員を運用しております。","voiceIndex":242,"id":"exchange-109"},{"speaker":"石田（秀）委員","kind":"意見","question":"ここを見てみなよ。各会派に言っているのに、それは駄目でしょう。各会派にお願いしているのに、会派で集まっていないところがあるのに始めるわけにはいかないと思う。そんなのだったら、きちんと理事会で話したほうがいい。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":248,"id":"exchange-110"},{"speaker":"石田（秀）委員","kind":"意見","question":"今、こういう話があって、公明党の話と、しながわ未来もそうだけれども、しっかり申合せで、理事会でも各会派半数という話はしていると思う。それなのに、全体がそろったから、ではみんな私たちが帰るかという話だ。そんな話はない。こんなので、コロナが終わって、こうなって、それで、緩々にして、こんなことになっている。そういう申合せを出しているのだから。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":250,"id":"exchange-111"},{"speaker":"石田（秀）委員","kind":"意見","question":"こういうことばかり繰り返しているのだったら、半数も含めて、もう一度やり変えたほうが、よく考えたほうがいい。委員長の中で、しっかりそれはやっていただかないと、説明も変えていただかないと、これでは半数、みんなそろって過半数だから結構ですという話はないと思う。会派政治をきちんとしっかりやっているのだから。私はそう思うので、終わってからでもいいので、ぜひそれはもう一度やってください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":256,"id":"exchange-112"},{"speaker":"西本委員","kind":"質問","question":"３４９ページの市街地整備事業費の中に入るはずなのですが、この中に大崎駅周辺地区コーディネート業務等委託と五反田駅周辺地区コーディネート業務委託というのがあります。成果があるのですかということ。この「等」というのがよく分からないし、それから、本当にこれは役に立っているのですかということを、まずお聞きしたいと思います。","respondent":"中道都市開発課長","answer":"大崎の委託などですが、こちらにつきましては、コーディネート業務、同じように大崎駅のエリアマネジメントとともに、地域のにぎわいの創出を行っているとか、大崎駅の北口自由通路の検討を今行っているというような状況です。","voiceIndex":258,"id":"exchange-113"},{"speaker":"西本委員","kind":"質問・要望","question":"品川区のまちづくりに対してどういう成果があるのかというのを示していただきたいのです。でも、どこがどういう役割分担になっていて、どういう成果があって、住民たちが納得したまちづくりになっているかというと、住民たちは納得していない部分が多々あると私は感じているのですが、その調整をどうされますか。","respondent":"中道都市開発課長","answer":"各地区でまちづくりを行う中で様々な手法があって、その中で地域で話し合って再開発事業を進めていくという決定をした中で、準備組合をつくっていくと区は認識しております。","voiceIndex":260,"id":"exchange-114"},{"speaker":"西本委員","kind":"質問","question":"では次に、関連して３４５ページのまちづくりマスタープランに入っていきますが、具体的に話しておきたいと思いますので、例えば大井町のＣ地区です。先日、火事も起きました。だから、丸ごと、そこに大きな地域を、大きな再開発ビルを建てたりということではなくて、やはり細分化して、そのパートごとに再開発を進めていくという手法も必要ではないかと思いますが、いかがでしょうか。","respondent":"中道都市開発課長","answer":"特に、ああいった東小路など歴史あるものというのは活かしながら、やはり今後どのようにまちづくりに活かしていくのかといったところを、区としては、また地域の声を聞きながら、まちづくりを支援していきたいと考えています。","voiceIndex":262,"id":"exchange-115"},{"speaker":"西本委員","kind":"質問","question":"ですから、細分化して考えたらいかがでしょうかということを言っているのです。Ｃ地区というのは丸ごとですよね。一体という形で進めようとしています。今までのように丸ごと全部をやるのではなくて、住民の生活を維持しながらというところの視点で、再開発というのを変えていくべきところがあるのではないかと思いますが、お考えをお聞きします。","respondent":"中道都市開発課長","answer":"まちづくりの中で、今現在、やはり安全安心に、今後どうやっていこうかというところを話し合われている状況ですので、細分化していくのか、一体的にしていくのかということも踏まえて、今、お話合いが行われているという状況です。","voiceIndex":264,"id":"exchange-116"},{"speaker":"西本委員","kind":"質問・要望","question":"そういうご答弁は何回も頂いているのです。でも現場の住民たちはそうではないのです。ただ、商店街は商店街の、国の予算、東京都の予算、補助金がないと言われているのですけれども、そうではなくて、やはり地域の活性化のために、今、人気がある場所でありますけれども、そこは、安全を含めて、再開発をするための新たな視点での、国、それから東京都へ助成金をぜひ求めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":266,"id":"exchange-117"},{"speaker":"若林委員","kind":"質問・要望","question":"３６９ページの医療救護体制整備費からは２点ほど、医療資器材の使用期限の指摘が、ある薬局からも以前あったのですが、過去の話ですが、医薬品ではなくて医療資器材のリスト化やダブルチェックの体制がどのようになっているのか、確認させていただきたいと思います。そこで、品川区もこの社会実験に参加した区として、今後のご予定、取組をお聞かせいただきたいと思います。","respondent":"平原防災課長、北原河川下水道課長","answer":"１つが緊急医療救護所、もう一つが学校医療救護所、もう一つが薬剤師会の薬局における、これがローリングストックという形の、この３つがありますが、まず２つ。品川区としては、今後、東京都の動向を注視するとともに、昨年の実験結果、また文化観光課等で実施しているグループイベント等の結果も踏まえまして、今後検討する水辺利活用の計画の中で、関係者の意見を伺いながら。","voiceIndex":268,"id":"exchange-118"},{"speaker":"若林委員","kind":"質問・要望","question":"それから２点目は、そうしますと、先ほどから、いわゆる水辺の利活用の計画ということが、今年度、来年度ということで、ということは、社会実験を経ての本格的な舟運の導入というのは、２年、３年、４年先、どのぐらいを今、見通していらっしゃるのかというのを確認するのと、いや、それはちょっとまだ、まさに計画がこれからですからという答弁になるのであれば、いずれにしても、そんなに遠い話ではないと。","respondent":"平原防災課長、北原河川下水道課長","answer":"医療資器材ですけれども、私どものところで全量、管理簿をつけておりまして、その管理簿に書かれている有効期限を現場で確認しながら保管しています。そのような形で確認作業を進めております。水質の話につきましては、今、委員から頂いた内容も踏まえてですけれども、さらにできる取組がないかというところは、いま一度検討していきたいと考えています。","voiceIndex":271,"id":"exchange-119"},{"speaker":"高橋（し）委員","kind":"提案","question":"１人用ベビーカーでも何とかというレベルです。何らかの対応策をお願いしたいと思います。今回１１月１日からの無人化に伴ってどのような課題が生じるとお考えになるでしょうか。３つ目は同じマスタープランですが、大井町駅周辺のバリアフリーについてです。それも、８時半から１０時までの、ヤマダ電機の開店前までですれば、先ほどのお話、前の質疑にもあった階段を使わなくて済むとご提案いたしました。","respondent":"高梨公園課長、鈴木都市計画課長、森道路課長","answer":"花海道におきましては、通過自転車による陳情が非常に多く区に寄せられておりまして、非常に対応に苦慮している状況です。その際も、区民の不安の声を直接お伝えしたわけですが、ＪＲからは、やはり最近の改札の利用、Ｓｕｉｃａ等が非常に浸透しまして。午前中の答弁でもございましたけれども、３つ、エレベーターがございまして、ヤマダ電機のデジタル館のほうは、やはり１０時からですので、１つ。","voiceIndex":275,"id":"exchange-120"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"これはよろしくお願いします。それからＡＴＭもあるのでオレオレ詐欺。これも要望です。最後に、大井町のところが少し分からなかったのですが、確認も含めて、ヤマダ電機のデジタル館のほうについて協議が進んでいると受け取っていいのでしょうか。もしそういうことが進むということは、都市計画法上、あそこは都市計画でつくられたところなので、それができないのかというところも確認したいと思います。","respondent":"森道路課長","answer":"ヤマダ電機のデジタル館の部分につきましては、具体的な協議まで進めておりませんけれども、まず、稼働時間として１０時からというところがありますので、朝の時間帯も含めて、確認できるきゅりあんを中心に今考えていきたいところです。","voiceIndex":279,"id":"exchange-121"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"大井町のほうですけれども、きゅりあんではなくて東大井や、あと東京品川病院のほうから来る方にとっては、デジタル館のエレベーターを使わせていただくということが悲願なわけです。そこの交渉を、協議を進めていないという状況なので、ぜひお願いしたいと思います。これは強い要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":281,"id":"exchange-122"},{"speaker":"えのした委員","kind":"質問","question":"私からは、３３９ページの水辺利活用事業についてお伺いします。運河や目黒川などの水辺周辺は、品川区にとって重要な資源の一つであり、魅力を向上させ、より一層活用していくことが重要であると考えます。昨年度の取組として、天王洲水辺広場整備について、どのような整備を行ったのか、お知らせください。","respondent":"北原河川下水道課長","answer":"区では、水辺と調和した魅力ある景観の形成、また東品川海上公園のアクセス性の向上等に向け、水辺広場の整備を進めてきており、今回はもともと一般開放されていなかった東品川二丁目の天王洲運河護岸沿いの新東海橋から目黒川水門に至る２００ｍの区間を広場として整備しました。","voiceIndex":283,"id":"exchange-123"},{"speaker":"えのした委員","kind":"質問・要望","question":"今後も機会を捉えて整備を続けていくよう要望します。続きまして、ヒカリの水辺プロジェクトについてお伺いします。私は、アイル橋、ふれあいＫ字橋など、ライトアップされているのを見たことがありますが、ライトアップはどこの橋で、年間どのぐらいの期間で実施しているのか、また、どのような色でライトアップしているのか、実施状況をお知らせください。","respondent":"北原河川下水道課長","answer":"ライトアップにつきましては、鈴懸歩道橋やアイル橋など、目黒川や運河に架かる１３橋で実施しているところです。","voiceIndex":285,"id":"exchange-124"},{"speaker":"えのした委員","kind":"質問","question":"今後は２０２５年デフリンピック東京大会に向けた周知、手話言語条例の制定された月、ホッケー日本代表、ブラインドサッカーの応援等、スポーツイベントと連携したライトアップ、先日も委員から質問があった乳がん検診、ピンクリボン期間などいかがでしょうか。区のお考えをお知らせください。","respondent":"北原河川下水道課長","answer":"ほかにも連携できるものがないかというのも検討してまいります。","voiceIndex":287,"id":"exchange-125"},{"speaker":"えのした委員","kind":"質問","question":"引き続き、充実を図れるようにご検討をお願いいたします。次に、舟運社会実験についてお伺いします。先ほど委員からも質問がありましたが、こちらは令和４年１０月に、品川区は東京都と連携し、らくらく舟旅通勤を実施しています。こちらの事業の概要と成果、またアンケート調査も実施しているとのことですが、その結果についてもお伺いします。","respondent":"北原河川下水道課長","answer":"舟運社会実験ですが、舟運の交通手段としての有効性を検証するために、昨年の１０月から１１月にかけて、朝夕の通勤時間に東京都と連携して実施したものでして、都内では６航路、品川区内では五反田・天王洲間で実施しております。","voiceIndex":289,"id":"exchange-126"},{"speaker":"えのした委員","kind":"質問","question":"アンケート調査、満足度９割ということで、東京都と連携した今回の社会実験に参加した区は品川区だけです。会派では７月に、天王洲運河、京浜運河周辺を、船で視察を行い、個人的には、しながわ運河まつり、天王洲キャナルフェスを視察、先日は水辺議連として、しながわ水辺の観光フェスタのお手伝いをしてきました。今後の取組をお伺いします。","respondent":"北原河川下水道課長","answer":"先ほどからもお伝えしているように、区では令和６年度に向け、新たな推進計画を策定する予定で検討を進めております。","voiceIndex":291,"id":"exchange-127"},{"speaker":"えのした委員","kind":"意見","question":"最後に、水辺利活用は重要だと考えてはおりますが、品川区内でも、私の住んでいる荏原地区など、水辺が地域になかったり、近くにないエリアもあります。実感として、地域の方々の関心や身近さ、親しみが薄いように思います。区のご見解をお知らせください。","respondent":"北原河川下水道課長","answer":"委員のご提案を踏まえて、可能な取組がないか、他の都市などの事例も含めて、関連部署と連携して研究・検討してまいります。","voiceIndex":293,"id":"exchange-128"},{"speaker":"松本委員","kind":"質問","question":"私からは、３３１ページ、駅周辺等放置自転車対策事業、３５９ページ、コンクリートブロック塀等安全化支援事業について伺います。行政評価シートを拝見しまして、区では各駅での１日当たりの放置自転車は減少していると書かれております。その根拠となる調査は毎年１０月に行われているとの記載もあります。例えば、平日なのか土日祝日なのかなど、その辺りをお願いいたします。","respondent":"工藤交通安全担当課長","answer":"放置自転車の調査についてお答えします。こちらは年１回、東京都が実施している調査になります。１０月の平日に行われまして、各駅周辺の１日の放置自転車の台数を調査した数値となります。","voiceIndex":297,"id":"exchange-129"},{"speaker":"松本委員","kind":"質問","question":"そこで、特に昼か夜かというところが結構大事かと私は考えています。お昼の時間帯、夕方の時間帯だと、駅周辺といってもスーパーの周りなどに放置される可能性が高い。この辺りを考えると、夜の時間帯についても、先ほど東京都という話だったのですが、品川区としても夜の時間帯、どういうふうに放置自転車があるのかということは把握されたほうがいいのではないかと思いますが、いかがでしょうか。","respondent":"工藤交通安全担当課長","answer":"平日のおおむね午前１１時頃、駅周辺の放置自転車を調査しているものです。曜日、夜間等によって異なるですので、区としましても、夜間帯の放置自転車の台数については、今後、その必要性を検討しまして、実施に向け、検討してまいりたいと考えております。","voiceIndex":299,"id":"exchange-130"},{"speaker":"松本委員","kind":"確認","question":"分かりました。そういう意味で、ぜひ調査もしていただきつつ、撤去のほうなのですけれども、過去にも撤去についていろいろお話もあったと思いますが、もう一回確認で、撤去の時間帯といいますか、どういうふうに行われているのかを改めて伺えればと思います。","respondent":"工藤交通安全担当課長","answer":"放置自転車の撤去の関係ですけれども、こちらは業者に委託しまして、午前９時から午後７時までの間で、それぞれの駅等、放置自転車の多いところを重点的に回って撤去を行っているというような状況です。","voiceIndex":301,"id":"exchange-131","title":"町会・自治会支援"},{"speaker":"松本委員","kind":"質問・要望","question":"午後７時までということです。この通りというのは、高齢の方もそうですし、あと車椅子の方もやはり通られて、どうしても自転車があることによって、道路幅が狭くなってしまう。このように考えると、ぜひ夜間の放置自転車の撤去、先ほどは午後７時までということで、委託なので難しいところはあると思うのですけれども、夜間についてもご検討いただきたいと思いますが、いかがでしょうか。","respondent":"工藤交通安全担当課長","answer":"委員ご指摘のとおり、夜間、撤去看板の前に自転車をとめている状況もまま見られます。こちらについて、また委託事業者等の時間の延長等ができるかどうかというところを含めまして、安全な道路の確保について引き続き検討してまいりたいと考えています。","voiceIndex":303,"id":"exchange-132"},{"speaker":"松本委員","kind":"質問・要望","question":"１７時ということなので、やはり飲食店、特にアルコールが提供されるお店に行く時間帯だと早い時間に終わってしまうので、できるだけ長く、夜間も委託していただけるようにご要望させていただきまして、次の質問に移りたいと思います。次に、コンクリートブロック塀等安全化支援について伺います。その中で、今、品川区の中で、危険なブロック塀というのはどのくらいあると把握されているのでしょうか。","respondent":"長尾建築課長","answer":"建て替えも含めて、道路沿いの塀というのは一定程度なくなってきているところです。１００kmほどのうち、老朽化している部分の数量については正確には把握していないところなのですけれども、かなりの数量があると認識しております。","voiceIndex":305,"id":"exchange-133"},{"speaker":"松本委員","kind":"質問・要望","question":"他の自治体でも、実際に危険なところを調べて、そのうちの１割ぐらいしかまだ終わっていないという話もあります。最後は要望になってしまいますけれども、今、ポスティングということですが、危険な、特に通学路近くについては、ぜひ戸別もしていただくようにお願いいたしまして終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":307,"id":"exchange-134"},{"speaker":"藤原委員","kind":"質問・要望","question":"３３１ページ、放置自転車についてから、まずお伺いしますが、ここの席に今回座らせていただいて、石田秀男委員、田中委員、鈴木委員、平成１１年初当選させていただいておりまして、そのとき品川区はこういう施策だったのです。それで、今まで要望等もしてきたので、質問しますが、まず西大井駅の、毎回言っていますが、西口改札口開設はどうなっていますか。６００万円というのは今、低所得者ですか。","respondent":"溝口防災まちづくり部長、大串会計管理者、鈴木都市計画課長、工藤交通安全担当課長、北原河川下水道課長、森道路課長、小川木密整備推進課長、中道都市開発課長、大石まちづくり立体化担当課長、高梨公園課長、櫻木土木管理課長、長尾建築課長、竹田住宅課長","answer":"今後、女性職員にも管理職にぜひなっていただいて、男女を併せて、様々な多様なところで、技術といったものも進めていきたいと考えているところです。そういった予算書あるいは決算書の関係を少しでも分かりやすく表記できればといったところで、こういった表記方式に対応しています。私から、自転車と西大井についてお答えしますが、今、部長がご答弁したとおりですが、特に大きな動きとしましては。引き続き、どういった対策が有効かということについては検討してまいりたいと考えております。","voiceIndex":309,"id":"exchange-135"},{"speaker":"のだて委員","kind":"質問・要望","question":"私からは、３６４ページ、防災費について、予防対策の拡充を求めて、３５１ページ、武蔵小山駅周辺地区再開発事業について、中止を求めて伺います。防災です。自然災害を止めることはできませんが、被害を防ぐことはできます。そのための予防対策を続けて、取組を進めていただきたいと思います。防災対策に予防策をしっかりと位置づけていただきたいと思いますが、いかがでしょうか。","respondent":"平原防災課長","answer":"今般、地域防災計画の見直しも進めておりますが、そういったところもさらに取組を強化する方向で現在検討を進めているところです。","voiceIndex":324,"id":"exchange-136"},{"speaker":"のだて委員","kind":"質問・要望","question":"その前に、やはり予防策として被害を軽減していくということが公助に求められると思いますので、そこはしっかりと位置づけていただきたいと思いますが、伺います。続けて伺っていきたいと思いますが、具体的に聞きたいのですけれども、都の被害想定が出され、区内でも、これまでの想定から大きく被害が減るというものでした。住宅の耐震化・不燃化をさらに促進していくのに向けて、その課題は何か、伺います。","respondent":"長尾建築課長、小川木密整備推進課長","answer":"そういった事業周知のところが、やはり１つ、課題であると認識しております。不燃化に関しましては、戸別訪問を行いながら、今年度はＰＲ動画を作成いたしまして、今月からケーブルテレビ品川、また区公式のＹｏｕＴｕｂｅチャンネルで放映を開始しておりまして、様々なＳＮＳ媒体等を活用しながら、今後。","voiceIndex":326,"id":"exchange-137"},{"speaker":"のだて委員","kind":"質問・要望","question":"周知が課題ということで、ぜひそれは周知していっていただきたいと思うのですけれども、やはり都の被害想定の中でも、耐震化が１００％になれば、現状から全壊棟数を６割減らせると示していますので、ぜひ、そこを目指していただきたいと思いますけれども、いかがでしょうか。不燃化のところです。","respondent":"長尾建築課長、小川木密整備推進課長","answer":"そういった建物につきましては、やはり耐震性能も低い状況が傾向としてはありますので、引き続き、耐震化支援事業を、周知も含めてしっかりとやっていきたいと考えております。この調査を踏まえて、来年度以降、この２町丁目に対して拡大を検討してまいりたいと考えています。","voiceIndex":329,"id":"exchange-138"},{"speaker":"のだて委員","kind":"質問・要望","question":"不燃化特区のところは、２町丁目に拡大を検討しているということで、それもさらに広げていっていただいて、耐震化も１００％を目指していっていただきたいと、これは求めておきたいと思います。こうした状況になっている課題を、区としてどう考えているのか伺います。区での実態です。なかなか全体を把握するのは難しいと思うのですが、区がどう考えているのか伺いたいと思います。","respondent":"竹田住宅課長、平原防災課長","answer":"この制度そのものを根本的に今後、見直しというか検討していきたいと考えております。家具の転倒防止を行っている家庭の割合ですが、大変申し訳ございません。こちらの器具は何分、様々なところで販売しているものですので、どういったところから購入してどのぐらいといったことにつきましては、数字は持ってございません。","voiceIndex":332,"id":"exchange-139"},{"speaker":"のだて委員","kind":"質問","question":"なかなか全体を把握するのは難しいとは思うのですが、今、区の家具転倒防止器具の取付助成はなかなか利用されないという状況でありますので、申請いただいた方がなぜしていただいたのかということなども調査していただいて、利用しやすい仕組みにしていくことが必要だと考えますが、どのように見直し、検討されていくのか、伺います。","respondent":"竹田住宅課長","answer":"この制度を利用された方からヒアリング等しまして、さらにこちらの制度のスキーム等について、今後しっかり検討していきたいと考えています。","voiceIndex":335,"id":"exchange-140"},{"speaker":"のだて委員","kind":"質問・要望","question":"高齢者・障害者等対象では、令和４年では予算額２０件に対しての実績が０件となっています。これは、やはりコンセントに差し込むだけで住宅全体のブレーカーが落ちるというもので、簡単に出火防止ができるものですので、ぜひ進めていただきたいと思いますが、なかなか進まない課題はどのように考えていらっしゃるのか、どう進めていこうと考えているのか伺いたいと思います。","respondent":"羽鳥防災体制整備担当課長","answer":"今、東京都でも、木密地域を対象に無償で配布しているという取組もありますので、この機会に東京都と連携して、感震ブレーカーの機能周知にも活用して、ＰＲを強化してまいりたいと考えております。","voiceIndex":337,"id":"exchange-141"},{"speaker":"のだて委員","kind":"質問・要望","question":"区の助成対象をぜひ広げていただいて、今、不燃化特区の範囲だけとなっておりますので、そこは対象を広げていただきたいと求めておきたいと思います。次に、武蔵小山の再開発についてです。そうしたら、元いた地権者や既存のお店が何割程度戻ってきたのかということもお答えいただけないか、伺いたいと思います。","respondent":"中道都市開発課長","answer":"権利に関するお問合せです。戻ってきた方というところにつきましては、個人情報等の権利の話になりますので、非公表という形で聞いております。お店につきましても、テナントが入ったり出たりというところもありますので、区としてもこの間、度々、確認しています。","voiceIndex":339,"id":"exchange-142"},{"speaker":"のだて委員","kind":"質問","question":"個人情報等で非公表という話なのですけれども、何割が戻ってきたのかというのは個人情報とは関係ないと思うのですが、いかがでしょうか。","respondent":"中道都市開発課長","answer":"もともと権利を持っている方というところもありますので、そうしたところで非公表と聞いてあります。","voiceIndex":341,"id":"exchange-143"},{"speaker":"のだて委員","kind":"質問","question":"権利を持っているからというのは、よく意味が分からなかったのですが、進めしますけれども、この間、再開発で住民が追い出されるということを私たちは指摘させていただきました。これは区として適切だと思っているのか、伺います。","respondent":"中道都市開発課長","answer":"市街地再開発事業の中では、都市再開発法の中で進めている事業というところで、地区内に住み続けることも保障いただいて、地区外へ移転することも選択できる自由の中で、権利者の方々で権利を保障されているという制度です。","voiceIndex":343,"id":"exchange-144"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうした選択があると言いますが、それは選びたくない、今のまま住み続けたいという方がいらっしゃる下でこれを進めるのはやめるべきだと求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":345,"id":"exchange-145"},{"speaker":"吉田委員","kind":"質問・要望","question":"私からは、３４９ページ、市街地整備事業費、それから３６３ページ、空き家等対策事業、それからもし時間があれば、３３５ページか３４１ページになるか、雨水流出抑制費もしくは治水対策推進助成事業から伺います。その前提で質問いたします。再開発ビルや再開発地域の保育環境はどうなのかと思いますが、その地域の方たちがそれを求めている状況では、それは必要な施策だったのかと思います。","respondent":"中道都市開発課長","answer":"市街地再開発事業における公共性です。市街地再開発事業は、区民の方、地域の方が主体となって進めていく、民間が事業者です。一方で補助金等をお支払いするということで、また公共性のあるまちづくりというのも区も目指しています。","voiceIndex":347,"id":"exchange-146"},{"speaker":"吉田委員","kind":"質問","question":"多分、これを聞くと、道路とか空地とか、お答えが来るだろうと思ったので、区民が利用できる公共施設がどれぐらいできたのかという質問にしたのです。数は把握できていないということなのですけれども、例えばここにはこういうものができましたという実績、多分いろいろあるので、実績は一つか二つ、少なくとも把握されているかと思うのですが、教えてください。","respondent":"中道都市開発課長","answer":"大崎地区におかれましては、今、区民利用ができるという観点で言えば、美術館を設置しています。は保育園など、また公園といったものを、再開発に合わせて整備するという地域もあります。大崎でいきますと、デッキなどの整備といったところです。","voiceIndex":349,"id":"exchange-147"},{"speaker":"吉田委員","kind":"質問","question":"備蓄倉庫も、確かにいざというときには区民が利用する施設とも言えますが、私が例に挙げたような図書館や高齢者施設、障害者施設については整備されてこなかったということで理解してよろしいでしょうか。","respondent":"中道都市開発課長","answer":"高齢者施設におかれましては、整備というか、既存にその施設がありましたので、また再開発したときにも設置したという経緯はあります。","voiceIndex":351,"id":"exchange-148"},{"speaker":"吉田委員","kind":"質問・要望","question":"でも、少なくともやはりそういう公共の施設をつくることが、再開発のときには求められているという理解は、それでよろしいですよね。そういうときに、例えば所管の課から、区のいろいろな所管に向けて、今度の再開発にどういう公共的な施設が求められているか、希望を聞くのか、それとも各所管が察知して、再開発があるのだったら、こういう施設をつくってほしいと言うのか。","respondent":"中道都市開発課長","answer":"本当に再開発をするのかしないのかというところでの一定程度の判断の中で、庁内で、まずは再開発をする地域というところで情報共有は図っております。その中で、各所管からご提案を受けた中で、最終的にやはり判断するのは、準備組合もしくは組合というところになってきます。","voiceIndex":353,"id":"exchange-149"},{"speaker":"吉田委員","kind":"質問・要望","question":"ということは、では今度、再開発があるのであれば、その制度を使って、ぜひこういう施設をつくってほしいという要望が、各所管からさぞかし上がっているのではないかと思って伺ったのですが、そういうことはあまりないという理解でよろしいでしょうか。","respondent":"中道都市開発課長","answer":"要望につきましては、各地域におかれまして大なり小なりあるです。一方で、やはり都市開発課で総合的に、まちづくりをどうしていくのかというのは指導・協議しておりますので、またそこに対しては、準備組合、組合といったところで協議して決めていきます。","voiceIndex":355,"id":"exchange-150"},{"speaker":"吉田委員","kind":"質問・要望","question":"地域の主に事業を進める方たちが、いやいや、うちの再開発地域にはそんなものは入れませんというようなことがあれば、またそれはそれで、私たちも別の意見の出し方などがあるかと思うのですが、まずは区としては、再開発に求められている公共性、道路やデッキも大切かもしれませんけれども、そういう公共的な施設、図書館とか障害者施設、高齢者施設などは、ぜひ入れてほしいという要望は出してほしいし。","respondent":"竹田住宅課長","answer":"もう一点は区の住宅課で、空き家対策担当が相談に応じておりますので、３つの窓口が連携しながら、有機的に空き家の改善に努めているところです。","voiceIndex":357,"id":"exchange-151"},{"speaker":"吉田委員","kind":"質問・要望","question":"そうしたら、本当にすぐ見に来てくださったということで、そういう意味では、区が直接そういうことをしてくださったということで、大変、信頼感につながったというか、安心されたと思います。区の直接の相談窓口などということも、ぜひ検討していただきたいと思うのですけれども、いかがでしょうか。それから、後半の質問です。その辺についても、先ほどご答弁がなかったので教えてください。","respondent":"竹田住宅課長","answer":"特に空家等対策特別措置法の改正は、放置すれば特定空家等になるおそれのある管理不全空き家等も指導・勧告の対象とできることになりましたので、こういった法制度を有効に活用しまして、委員ご指摘のような内容につきましても、最大限、実現していきたいと考えております。","voiceIndex":359,"id":"exchange-152"},{"speaker":"吉田委員","kind":"質問・要望","question":"本当に、こういう問題はこれから絶対増えますよね。今回は、枝がこちらに伸びてしまったということで、これも本当に、切らせるに至るまでは結構な手順が必要だというのを、私も説明を受けました。ぜひ区としても、そういう制度を前向きに検討していただきたいと思いますので、これは要望にとどめます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":361,"id":"exchange-153"},{"speaker":"あくつ委員","kind":"質問","question":"私からは、３６７ページ、消防団運営費、３３７ページ、橋梁管理費、そして３３１ページ、交通安全啓発費、区民交通傷害保険について伺ってまいります。その方が運ばれているうちに別の方も倒れるというような状況で、後で伺ってみたところ、式典の最中に最終的に５人の方が体調を悪くされて倒れたということでした。品川区の防災課は、このような状況であったことをご存じかどうか伺います。","respondent":"伊藤災害対策担当課長","answer":"品川消防団消防操法審査会におきまして、そのような事実があったことは把握しております。その後、品川消防団と消防署と連携いたしまして、どのような対応を取ったのか確認をいたしました。","voiceIndex":363,"id":"exchange-154"},{"speaker":"あくつ委員","kind":"提案","question":"詳細なご報告をありがとうあります。確認したら、最近は開催がないようですけれども、例えば、先ほど申し上げた来賓祝辞の一部割愛であったり、来賓客のご招待状の中に、これは仮に、ご挨拶は短くとか、そういう何かお願いを入れるなど改善策を、消防団からではなく区から問題提起していただいて、手を打っていただきたいと思いますが、いかがでしょうか。","respondent":"伊藤災害対策担当課長","answer":"消防団を守る上でという形で、いろいろ消防団に対してご支援を頂きまして、誠にありがとうあります。初めに、品川消防団の今回の５月下旬に消防団消防操法審査会を実施いたしまして、このような事態が発生してしまいました。","voiceIndex":365,"id":"exchange-155"},{"speaker":"あくつ委員","kind":"質問・要望","question":"３３７ページ、橋梁管理費から、青物横丁駅歩道橋バリアフリー化について確認してまいります。１つ目は青物横丁駅前の階段。２つ、品川区に要望です。勉強会は、歩道橋は国の管理、池上通りは都道ですから東京都、交通管理者である警視庁が主導で検討が進んでいるかと推測します。そして、それを勉強会でしっかりと伝えていただきたい、このようにお願いしたいと思いますが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"ただ一方で、非常に用地が困難、土地が限られているというところもございまして、このバリアフリー化の検討を、お話しいただいたように、警視庁、東京都、国、品川区で勉強会を開いているところですが、やはり反対側の階段２つのバリアフリー化については。","voiceIndex":367,"id":"exchange-156"},{"speaker":"あくつ委員","kind":"質問・要望","question":"品川区では、令和５年５月から６月の２か月間、やっているというところで、インターネットの場合、中途加入の場合はいつでもできるということになっていますけれども、このことについて、品川区でも導入をということで要望しましたところ、交通安全担当課長のご答弁では、「港区に確認したところ、今年度から試験的に実施ということで始めたということであって。","respondent":"工藤交通安全担当課長","answer":"先行している区にいろいろお話を聞きますと、様々な課題があるということを伺っております。区といたしましては、他区の状況を引き続き注視しながら、効果の上がる形になるように検討してまいりたいと考えています。","voiceIndex":369,"id":"exchange-157"},{"speaker":"あくつ委員","kind":"質問・要望","question":"４区確認していただいたということで、課題があるということ。一般区民の方で、車などの任意保険でそういうものが附帯で入っていない方について、ＴＳマークという自転車屋でつけるマークというのもあるのですけれども、それを、ではどうすればいいのでしょうかと言われたときに、区民交通傷害保険１,４００円で、年間で１億円以上の保険が掛けられるということがありました。","respondent":"工藤交通安全担当課長","answer":"保険会社が支払った件数・金額につきましては、令和４年度で３９件、前年と比較費プラス１５件になっております。金額につきましては１５２万７,０５６円、前年と比較し１７万９,２２５円マイナスというような状況になってあります。","voiceIndex":371,"id":"exchange-158"},{"speaker":"あくつ委員","kind":"質問","question":"そのうち、自転車の事故に関わる件数と、払われた金額が分かれば教えてください。","respondent":"工藤交通安全担当課長","answer":"自転車に払われた件数につきましては、保険会社から情報提供を受けておりませんので把握してございません。","voiceIndex":373,"id":"exchange-159"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"３５５ページのしながわ水族館リニューアルと、３４５ページのコミュニティバス運行経費について伺います。しながわ水族館のリニューアルについてお伺いします。これは以前も委員会でもお話ししましたが、２０２０年のアンケート結果では、しながわ水族館の最寄り駅はどこでしょうかと聞いたときに、約４０％の方が品川駅と答えた。そもそもリニューアルの目的が、設備が古くなったからというのが１つ目。","respondent":"高梨公園課長","answer":"そのために、やはり民間の水族館と、公立、区立の水族館といったところもありますけれども、品川区にあるしながわ水族館というところで皆様にしっかり認知していただくために、今、そのための広報によって、また品川駅のほうの水族館がという話がありましたが、今。","voiceIndex":377,"id":"exchange-160"},{"speaker":"せりざわ委員","kind":"提案","question":"そうではなくて、隣に置いてあることで、これがキャベツ、これがレタスですと分からせるというのも１つ、手法かと思っていて、水族館と例えば映画館のセットのチケットがあると思うのですけれども、あえて水族館と水族館のペアチケットというか、年間パスポートもこれから検討していくというお話があったと思うのですけれども、民間だから、会社が違うから非常に難しいのかと思うのですが、しながわ水族館と。","respondent":"高梨公園課長","answer":"そこは、なかなか奥までというと危ないというところもありますけれども、子どもたちに水に親しんでいただくということで整備していることもありますので、リニューアルに際して、さらにその砂浜と、あとリニューアルするしながわ水族館の中との連携であったり。","voiceIndex":379,"id":"exchange-161"},{"speaker":"せりざわ委員","kind":"提案","question":"検討という言葉を頂いて、大変ありがたい一方で、区長、副区長が結構厳しい顔をしていますので、難しいのかと思いながら、ぜひ前向きにご検討いただければと思います。これは以前、２０２１年に議会でご提案したことがあるのですが、例えば北には品川駅という陸の玄関があって、例えばそこから海を伝って、屋形船を使って引っ張ってくる。","respondent":"高梨公園課長","answer":"区の中心核である大井町としながわ水族館をつなぐ方策というのは、開館以来、３０年来、バスで結んでまいりましたけれども、引き続き重要なルートであると考えていますので、様々今ご提案いただきましたので、物理的につなぐこともそうなのですけれども、例えば。","voiceIndex":381,"id":"exchange-162"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1540#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":125836,"voices":383}},{"id":"r05-20231016-4","meetingId":"r05-c-settlement","date":"2023年10月16日","dateIso":"2023-10-16","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時３６分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を174件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"○午前１０時００分開会 ただいまより、決算特別委員会を開きます。 それでは、令和４年度品川区一般会計歳入歳出決算","agenda":"○午前１０時００分開会 ただいまより、決算特別委員会を開きます。 それでは、令和４年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"えのした委員","kind":"質問","question":"私からは、３８６ページ、図書館運営費、３９１ページ、学校図書館運営費についてお伺いします。私も子どもの頃から区立図書館を利用させていただいている区民の一人ですが、品川区図書館の前身となる荏川町文庫が大正１２年６月に開設されてから、今年で記念すべき１００周年を迎えました。学校図書館に整備すべき蔵書の標準がありますが、基準や内容、また、品川区内の学校図書館の状況はいかがでしょうか。","respondent":"吉田品川図書館長","answer":"現在、区立小学校、義務教育学校（前期）においては、３７校中３０校が達成され、中学校、義務教育学校（後期）においては、１７校中７校が達成されているところです。ほとんどの小中学校におきまして、標準蔵書数の９０％以上は達成されていることとなっております。","voiceIndex":4,"id":"exchange-001"},{"speaker":"えのした委員","kind":"確認","question":"確認がとれました。これからも子どもたちのために、蔵書数の確保、計画的な蔵書の見直しを含め、学校図書館の拡充をお願いいたします。私が校区教育協働委員を務めている荏原平塚学園では、特に小学生の国語の学力がアップしていると委員会で話題になりました。そこで、実際、小学校、中学校で、本の貸出し数はどのようになっているのか、状況をお知らせください。","respondent":"吉田品川図書館長","answer":"傾向といたしましては、ここ数年、小学校の貸出数は著しく伸びが見られておりまして、令和３年度以降、１００万冊の貸出数を超えております。中学校につきましては、年間４万冊から５万冊と、少し貸出数が伸び悩んでいるところです。","voiceIndex":6,"id":"exchange-002"},{"speaker":"えのした委員","kind":"質問","question":"１００万冊、貸出数はすごいですね。そこで、これからも本への興味が湧き、貸出数が増え、新たな取組を行えるように、職員の充実はされていますでしょうか。先日も学校公開へ行き拝見しましたが、本の紹介やポップ展示がとてもすばらしく、また、職員の方、学校の先生にも話を伺いましたが、やはり資格をお持ちの方、専門性の高い方などのお力が必要だと強く感じました。","respondent":"吉田品川図書館長","answer":"図書館といたしましては、折を見て、これからも未来を担う子どもたちとの本の出会い、学ぶ喜びを与える場として、最も身近な学校図書館の支援を充実していければと考えております。","voiceIndex":8,"id":"exchange-003"},{"speaker":"えのした委員","kind":"質問・要望","question":"引き続き、計画目標としている子どもたちが本等を活用して、自ら主体的に思考し、行動する人に育つためのさらなる取組を要望します。続いて、地区図書館についてお伺いします。令和５年３月３１日に、しながわデジタルアーカイブが公開されました。私も品川区史を少し拝見し、映像は懐かしさを感じましたが、現在まで、どのくらい閲覧されていますでしょうか。内容、今後の取組についてお知らせください。","respondent":"吉田品川図書館長","answer":"その中でも品川区史に関するホームページについては人気の高いところとなります。現在、古い資料につきましては１７資料公開中、今年度新たには１０資料を公開の予定です。今後も総合実施計画に基づきまして、アーカイブの拡充を進めてまいります。","voiceIndex":10,"id":"exchange-004"},{"speaker":"えのした委員","kind":"意見","question":"１０万８,０００件以上、多くの方に閲覧されているとのことで、デジタル化でどこからでも閲覧が可能になり、後世に歴史を伝えていく重要な取組だと考えます。事業概要として、品川区立図書館の地区図書館１０館で指定管理者による運営を行い、地域の商店街や地元企業など、事業連携を図りながら、各館で様々なサービスを展開されていると示されております。主な取組内容および成果をお知らせください。","respondent":"吉田品川図書館長","answer":"先週の土曜日、１４日の日経新聞にも載っていたところではありますけれども、２１歳の６割が本を読まないという文部科学省の調査が現在出ております。１０代に本や図書館に親しんでもらうための対策をとってきたところです。","voiceIndex":12,"id":"exchange-005"},{"speaker":"えのした委員","kind":"確認","question":"本当に読書離れが進んでいるティーンズに向けてのイベントなど、様々な取組をされていることを確認できました。様々な取組、よいと思いますので、これからも続けていただき、拡充を期待しております。施設整備についてなのですが、図書館の新しい、古い、いろいろあると思いますが、授乳室があるところとないところがありましたので、こういったハードの面でも今後の整備をお聞かせ願えますでしょうか。","respondent":"吉田品川図書館長","answer":"図書館においての授乳室は、今、６か所でそろえておるところです。","voiceIndex":14,"id":"exchange-006"},{"speaker":"えのした委員","kind":"質問","question":"学習環境、読書環境が向上するよう期待して、私からの質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-007"},{"speaker":"ゆきた委員","kind":"質問","question":"私からは、２点お伺いいたします。３８９ページの英検チャレンジ事業、３８１ページの市民科・各教科充実経費について、それぞれお伺いいたします。初めに、英検チャレンジ事業について質問いたします。家庭の様々な事情から、私立学校を選択して経済的負担を感じている家庭もあります。このことを踏まえて、今後の区のお考えについてお聞きできればと思います。","respondent":"柏木学務課長","answer":"英検チャレンジ事業のお問合せです。委員からもご紹介ございましたが、品川区では、平成１８年度から、１年生からの英語科を実施するなど、品川区の教育の特色として英語の教育について力を入れてあります。","voiceIndex":18,"id":"exchange-008"},{"speaker":"ゆきた委員","kind":"確認","question":"現在の実情を確認させていただきました。少し次元は異なりますが、まもるっちは、区立学校に通学しているかどうかに関わらず、品川区在住の児童に防犯上の観点から無償貸与されています。区立学校に通学しているかどうかに関わらず、品川区内の子どもや大人たちの学習意欲の向上が、国際都市品川区の子どもたちの将来の発展につながると思われますが、改めて区の今後の方向性をお聞きできればと思います。","respondent":"柏木学務課長","answer":"受験料の支払い方法についても、英検協会とも協議等もする必要はあると感じです。ただ、区民の方からのそういう声は教育委員会もいただいておりますので、今後については、そういう区民の声を参考に考えていきたいと考えています。","voiceIndex":20,"id":"exchange-009"},{"speaker":"ゆきた委員","kind":"確認","question":"３０１ページの市民科・各教科充実経費に関連して、学校における救命教育について質問いたします。先日の私の一般質問の中で、品川区の中学校における救命教育についての今後の展開について質疑させていただきました。瞬時にＡＥＤの場所と道順が確認できるアプリ登録をすることで、社会貢献やボランティアに参加する意義を見いだせていくと思われますが、区のお考えをお聞きできればと思います。","respondent":"丸谷教育総合支援センター長","answer":"ＡＥＤの場所につきましては、各校で把握ができるように、１０月の校長・園長連絡会で、学校保健のポータルサイトの紹介や、ＡＥＤ財団の『命を守る心肺蘇生・ＡＥＤ』教本の紹介をしたところです。","voiceIndex":22,"id":"exchange-010"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"ぜひ無料アプリ、こちらの周知等についても、さらなる前向きな検討をお願いしたいと思います。こちらは、ｔｅａｍ ＡＳＵＫＡ普及啓発チラシと、ＡＥＤや救命処置について学べる冊子『命を守る心肺蘇生・ＡＥＤ』を申込みされた学校に無償配布されるものですが、こちらの公立学校等へさらなる周知等について要望したいと思いますが、区のお考えをお聞きできればと思います。","respondent":"丸谷教育総合支援センター長","answer":"ご案内の無償配布の冊子につきましても、併せて学校のほうに周知を図っていきたいと考えております。","voiceIndex":24,"id":"exchange-011"},{"speaker":"山本委員","kind":"質問","question":"本日もよろしくお願いいたします。私からは、３８５ページの介助員等委託、３７３ページのクラブ・部活動等経費、３８９ページの学校ＩＣＴ活用経費について伺います。３８５ページの介助員等委託について伺います。昨年１２月に文部科学省が発表した調査によると、通常学級に在籍する小中学生の８.８％に学習面や行動面で著しい困難を示す発達障害の可能性があることが示されております。","respondent":"唐澤特別支援教育担当課長","answer":"介助員の配置状況は、こちらも令和４年度の実績として、小学校（前期）課程は１０７人、中学校（後期）課程は５人となっております。支援が必要な児童・生徒は増加しており、今後もニーズがあるものと認識しております。","voiceIndex":28,"id":"exchange-012"},{"speaker":"山本委員","kind":"質問","question":"相応の児童・生徒が利用している、そして増加しているということで理解いたしました。そこで、少し細かくなるのですが、学習支援員、介助員の方々は、週何回、１日当たり何時間ほど働いていらっしゃるのでしょうか。各学校に何名配置されているのでしょうか、教えてください。","respondent":"唐澤特別支援教育担当課長","answer":"学習支援員についてですが、小学校（前期）課程には各校１０時間、中学校（後期）課程には各校４から７時間程度配置しております。週当たりとしましては、小学校（前期）課程では３日程度、中学校（後期）課程は１日程度の配置となっております。","voiceIndex":30,"id":"exchange-013"},{"speaker":"山本委員","kind":"質問・要望","question":"学習支援員は、週１０時間、１日４時間、３時間ぐらいでしょうか。週３回となると、残り２回は学習支援員が不在ということになります。１学校当たり約１６教室あります。そう考えますと、現状、要望がある児童・生徒に対して、十分に応えられていない状況ではないかとの認識ですが、いかがでしょうか。応えられていない場合は、その理由は何なのでしょうか、お教えください。","respondent":"唐澤特別支援教育担当課長","answer":"その際、医師や心理士、専門的な見地の訪問や、その意見を聞きながら、通常学級での支援がどのようにできるのかというところや、介助員、学習支援員の配置、または特別支援教室の利用といった様々な観点から支援を実施しています。","voiceIndex":32,"id":"exchange-014"},{"speaker":"山本委員","kind":"質問・要望","question":"学校からの要望に基づいているということですが、やはり、今お話ししましたように、数日ではなくて、週５回、全部あったほうがやはりいいのではないかというところを感じております。全ての学校一律である必要はないですが、要望する学校には週５回、そして少なくとも各クラス１名を配置できるよう、予算を増やしていただくことを要望いたします。約５億円。大きいです。区の考えをお聞かせください。","respondent":"唐澤特別支援教育担当課長","answer":"小学校では、初めての自閉症・情緒障害特別支援学級となりますので、まずはこの立ち上げを確実に行い、就学人口の推移や、子どもたちのニーズ、特別支援学級の教室などを設置する場所の確保など、総合的に判断しながら今後の状況を検討してまいります。","voiceIndex":34,"id":"exchange-015"},{"speaker":"山本委員","kind":"質問","question":"いろいろ課題があるとは思いますが、ぜひとも前向きにご検討を進めていただけるようお願い申し上げます。次に、３７３ページのクラブ・部活動等経費について伺います。現在進んでいる区立学校の部活動の地域移行に向けた取組について簡潔にお教えください。","respondent":"中谷指導課長","answer":"その成果と課題を整理しまして、次年度の継続実施や、学校の部活動への民間委託の導入などを進めていくことを検討しています。令和７年度までの推進期間の中で、持続可能な活動の在り方を協議会の中で引き続き協議をして模索をしていきたいと考えております。","voiceIndex":36,"id":"exchange-016"},{"speaker":"山本委員","kind":"質問","question":"続いて伺います。現在の区立学校の部活動の地域移行については、先ほどおっしゃいましたとおり、スポーツ庁が公表した方針に基づき、令和５年度から３年間で進める計画と理解しています。そして、それを３年間でやるという方針です。地域スポーツクラブの中には、学校と協議し、主体的に部活動の地域連携、地域移行に取り組みたい意向があるところがあるようですが、区としてのお考えをお聞かせください。","respondent":"中谷指導課長","answer":"ご提案いただいております地域スポーツクラブの方のご意向も踏まえた学校部活動の支援も、そのアプローチの中の１つとして、地域の実態に応じて学校と連携しながら導入をして検証してまいりたいと考えております。","voiceIndex":38,"id":"exchange-017"},{"speaker":"山本委員","kind":"質問・要望","question":"各学校、地域には、様々な状況があると思いますが、ぜひ、子どもたち、学校、地域の現場の声を聞き、子どもたちにとって望ましい持続可能な部活動の体制整備を進めていただけることを要望いたします。そのような考えの下でお尋ねします。タブレットには、チャイルドライン等の子どもから外部団体へのヘルプラインへのリンクが入っておりますが、子どもたちの利用件数が分かればお教えください。","respondent":"丸谷教育総合支援センター長","answer":"正確な利用件数は把握できておりませんけれども、チャイルドラインからは、品川の児童・生徒たちからの利用が増えたという情報はいただいております。","voiceIndex":40,"id":"exchange-018"},{"speaker":"山本委員","kind":"質問・要望","question":"やはり増えていると現状を理解し、また、こちら、正確な数が把握できていないということも分かりました。やはり実態を把握するには、こういったことをより丁寧に理解していく必要があるのではないかと考えます。時間も限られておりますので、この後の部分については、また別の機会で質問、要望します。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-019"},{"speaker":"安藤委員","kind":"質問","question":"令和４年度の委員名簿が公開されておりますが、その名簿で一番上の学識経験者という方になるのでしょうか、伺いたいと思います。令和５年度の委員のメンバーについても伺いますが、構成員については変わりはないのでしょうか、伺います。それと併せて、区長部局のほうにも伺うのですけれども、今回、言わば二度、２回目の調査を行ったいじめ問題調査委員会の委員長はどなたになるのでしょうか、伺います。","respondent":"丸谷教育総合支援センター長、勝亦総務課長","answer":"令和５年度まで、このメンバーに変わりはございませんけれども、先日、学識経験者の斎藤氏につきましては、本人のご事情で退任されるです。新たに法律の専門家を１名追加したところです。この山口弁護士につきましては、企業ですとか行政のコンプライアンスに関わった経験が豊富な方ということでお願いした経緯です。","voiceIndex":44,"id":"exchange-020"},{"speaker":"安藤委員","kind":"質問","question":"すみません、区長部局のほうですが、誰が決めるのかという選出する方を教えてください。","respondent":"勝亦総務課長","answer":"委員会は区長部局で設置していますので、区長で決定しています。","voiceIndex":47,"id":"exchange-021"},{"speaker":"安藤委員","kind":"質問","question":"分かりました。いじめ対策委員会のほうは委員長が代わったということなのですけれども、区教委に伺いたいのですが、このいじめ対策委員会が、先ほど紹介したように、言わば、身内に近いというか、区教委に甘い答申を出したのはなぜなのでしょうか。区教委としての認識を伺います。","respondent":"丸谷教育総合支援センター長","answer":"今ございました区教委に甘いのではないかということですけれども、第三者的な立場で答申を出していただいたものです。こちらとしては、内容につきましても真摯に受け止めるということで、特段、区教委に忖度しているような内容というふうには捉えておりません。","voiceIndex":49,"id":"exchange-022"},{"speaker":"安藤委員","kind":"質問","question":"そういう認識はないようなのですが、先ほど紹介したように、様々、６つの調査内容と調査結果について問題点を指摘しているのですけれども、その問題点を指摘されたということについて、区教委としては、自らが法に基づいて立ち上げたいじめ対策委員会の報告書に対して、問題点を指摘されたということについては、どのように捉えているのでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"今回、いじめ問題調査委員会からいただきました指摘につきましても、品川区いじめ対策委員会のメンバーもご覧いただいていますので、そうしたものを踏まえながら、今後、同じような指摘を受けないように、調査、報告に当たっていただこうというふうに考えております。","voiceIndex":51,"id":"exchange-023"},{"speaker":"安藤委員","kind":"質問","question":"少し答えていないと思うのですが、次に行きます。区長に伺いたいのですけれども、区教委設置のいじめ対策委員会の調査では不十分だと判断されたわけですよね。その理由は何だったのか、改めて伺いたいと思います。先ほども言いましたけれども、調査結果で、いじめ対策委員会の調査の問題点を多数指摘したのです、６つと言いますけれども。それについてはどのように感じておられますでしょうか、伺います。","respondent":"勝亦総務課長","answer":"区長部局で立ち上げましたいじめ問題調査委員会につきましては、主に、諮問させていただきましたけれども、報告の遅れ、それから、重大事態としての認定の遅れがあったというふうに捉えてございまして、そちらについて調査を行っていくということで設置したものです。","voiceIndex":53,"id":"exchange-024"},{"speaker":"安藤委員","kind":"質問","question":"報告の遅れだけではないのです。諮問事項も６つにわたっていますけれども、もう一回伺いたいのですけれども、区長部局が立ち上げたいじめ問題調査委員会の報告書で、いじめ対策委員会の調査が不十分だと問題点が多数指摘されたということについて、区長部局としては、諮問をした区長としては、どのようにその結果を感じているのか、伺いたいと思います。","respondent":"勝亦総務課長","answer":"いじめ対策委員会への調査内容および調査結果につきましては、原因の検証が結果の中では行われていないですとか、事務局の対応について調査が行われていない、それから、調査期間が長い等の指摘がされてあります。","voiceIndex":55,"id":"exchange-025"},{"speaker":"安藤委員","kind":"質問","question":"文教委員会には、５月にも新たに中学校で重大事態がありましたという報告がありました。隠蔽体質を引きずっていると言われても仕方ないのではないかと思うのですけれども、伺いたいと思います。これは私、たまたま発見してしまったもので伺っているのですけれども、これらの重大事態は、重大事態の定義のどこに当たる案件なのか、答えられる範囲で伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"議会への報告につきましては、調査、報告が終了した段階で報告をする予定です。重大事態の内容についてですけれども、こちらも今、調査の段階ですので、調査結果を踏まえて、議会も含めて、ホームページ上にも公表する形で考えております。","voiceIndex":57,"id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"最後、いじめのほうでは、区教委は、今後の対策の１つとして、いじめ防止対策推進基本方針の改定を掲げておりますが、改定のポイントはどこなのか伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"現在の基本方針につきましては、重大事態の対処についての記述が数行という形で、かなり短く書かれておりますので、そういったところをしっかりと学校が、または教育委員会が把握といいますか、対応できるように、ボリュームを増やすような考えです。","voiceIndex":59,"id":"exchange-027"},{"speaker":"安藤委員","kind":"質問","question":"この点については、引き続き、重大な課題なので、質問を続けていきたいと思います。在籍児童生徒に占める不登校の割合は３.２％。前年度は２.６％の人でしたので、さらに増えているということでした。区教委としては、この原因はどこにあると、これは改善が必要だと思うので伺っているのですけれども、どこにあると分析しておられるのか、率直に伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"この増加の原因につきましては、我々、いろいろ検証を進めなければいけないところですけれども、実際のところ、何が原因でここまで増えているのかというところまでは、現状のところ、把握ができておりませんというのが実際のところです。","voiceIndex":61,"id":"exchange-028"},{"speaker":"安藤委員","kind":"質問","question":"対策がすごく重要だと思うのですけれども、私は、一般質問でも、やはり複数のそれぞれのいろいろな立場から子どもを見守る大人の数を増やす必要があるのではないかというふうな立場で質問しまして、川崎市では、不登校の子どもの支援に当たる専任の教員の配置などの例も紹介して、どうですかと伺ったのですが、区教委は、教員定数があるため不登校支援に特化した正規教員の配置は困難ということで。","respondent":"丸谷教育総合支援センター長","answer":"ただ、そうした外から人を配置するということは大切だと考えていますので、例えば学校と家庭の連携事業を推進したりですとか、現在、荏原第五中学校で実施しております校内別室指導支援員の配置等は進めているところです。","voiceIndex":63,"id":"exchange-029"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひ太く、学校、教員の立場で、不登校の児童を支援できる教員の配置をぜひ考えていただきたいと思うのです。東京都の調査研究事業、調査に協力すると支援金がもらえるみたいな、これは申込みがあったというのは、行き届いているとは、私、到底思えないのですが、実際何人ぐらい申込みがあったのでしょうか、伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"令和４年度の実績ですけれども、１６名の申込みがあったところで、学校だけではなくて、フリースクールから案内を行っているというふうにも聞いております。","voiceIndex":65,"id":"exchange-030"},{"speaker":"安藤委員","kind":"質問・要望","question":"まだまだ少ないと思うのです。やはり様々な選択肢を広げていくためにも、そこを選べるようになるためにも、ぜひフリースクール等への支援も、品川区としてもぜひ進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-031"},{"speaker":"筒井委員","kind":"質問・要望","question":"よろしくお願いします。私からは、３７９ページ、いじめ防止対策費、時間があれば、３８７ページ、図書館運営費についてお伺いいたします。令和２年に発生しましたいじめ重大事態に当たるいじめ事案についてお伺いいたします。早期の解決にもなったかと思います。このいじめ加害者の特定というのは、非常に重要な要素だと思うのですけれども、品川区として、いじめ加害者の特定の重要性のご認識を伺います。","respondent":"丸谷教育総合支援センター長","answer":"いじめの行為の加害生徒、加害児童の特定ですけれども、委員のご指摘のとおり、加害者を特定することによって、反省を促したり、今後の再発防止に努めると、また、被害生徒だけではなくて、加害生徒の心のケアもしていくということで、重要なことだというふうな認識です。","voiceIndex":69,"id":"exchange-032"},{"speaker":"筒井委員","kind":"提案","question":"ぜひそうした認識を持って加害者の特定に当たっていただきたいと考えております。それで、特定のために、やはり客観的な証拠を押さえる必要があるかと思います。警察のほうからも、早い段階でカメラの設置を提案されており、そして、被害生徒の保護者の方からもご要望されており、そして、関係した生徒たちも、カメラの設置があればよかったという、この３者からも要望を受けております。","respondent":"森学校施設担当課長","answer":"防犯カメラの状況ということで、外もあるのですけれども、屋内に限りますと、現在、３１校で１５８台、〔１０月１９日に「８６台」と答弁訂正あり〕屋内に向けてカメラがついている状況。３１校は全体の６７.４％です。","voiceIndex":71,"id":"exchange-033"},{"speaker":"筒井委員","kind":"質問","question":"その屋内というのは、具体的にどこの場所なのか、教室なのか、廊下とかもあるのか、その点をお伺いしたいのと、そのカメラの位置は、生徒たちに認識されてしまっているのか、一目でカメラだと分かるような状況で設置されているのか、そうした設置状況についてもお伺いいたします。","respondent":"森学校施設担当課長","answer":"カメラの位置が児童・生徒に分かるかどうかというところですけれども、恐らく隠しているわけではないので、ある程度は認識されているとは思います。教室内にカメラを設置するというふうには聞いてはございません。","voiceIndex":73,"id":"exchange-034"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。設置した場所には一定の抑止効果があって、いじめをする場所はそれによって狭まれていくのですけれど、カメラがない場所で恐らくいじめをやってくるだろうなというふうには考えております。それは本当に、いかにも置きましたよというのではなくて、本当に隠しカメラのような感じで生徒に分からないように置くようなものが必要かと思いますけれども、その点、いかがお考えでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"教室の中に常時つけるということは、プライバシーの観点からもなかなか難しいものだと考えておりますけれども、いじめ事案が続く、継続されるというときにおいては、時限的に条件付にということで、保護者。","voiceIndex":75,"id":"exchange-035"},{"speaker":"筒井委員","kind":"質問","question":"ぜひよろしくお願いします。当然、そもそもいじめをしようと思わせないような教育が必要だと思いますので、その点をよろしくお願い申し上げます。気になったのが、いじめ対策委員会の報告書で、生活指導主任の方の指示に従わなかった教員の方がおりましたけれども、学校組織として大丈夫なのかなと不安になってしまいますけれども、この点、今後そうした学校の体制整備とかはいかがお考えなのでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"学校の中では、学校いじめ対策委員会がいじめの対応を検討し、実施していくということになっておりますので、こうしたところを徹底的に学校へは指示、指導しながら、組織的な対応ができるように働きかけていきたいと考えております。","voiceIndex":77,"id":"exchange-036"},{"speaker":"筒井委員","kind":"質問","question":"ぜひよろしくお願いします。区長は、「子育て・教育で選ばれるしながわ」を重点政策の１番上に掲げておりますので、ぜひ生徒、保護者が安心して学校に行ける体制、組織づくりをよろしくお願い申し上げます。調査報告書にもありますとおり、学校・教育委員会から独立した組織も検討していかなくてはいけないのかなと考えております。その点、最後に、いかがお考えでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"区長部局とも連携して、いじめ対策を進めていきたいと思います。","voiceIndex":79,"id":"exchange-037"},{"speaker":"せらく委員","kind":"提案","question":"３８１ページの習熟度別学習推進経費、３８５ページ、介助員等委託から、一般質問でもご提案させていただいた教員の補助要員について、細かいところをお聞きし質問します。通常学級への支援をという目線から質問をします。この中から、指導助手、学習支援員、介助員、それぞれの役割について確認します。この２つの予算執行率、実際の配置実績はどの程度でしょうか、伺います。","respondent":"中谷指導課長、唐澤特別支援教育担当課長","answer":"チームティーチングで行っておりますので、同僚性を育むとともに、教員が一人で抱え込む負担感を軽減する効果も一定程度あると認識しております。私からは、学習支援員、介助員の役割についてご説明申し上げます。学習支援員については、通常学級において発達障害等のある児童・生徒への学習参加に困難がある場合の支援を行っております。","voiceIndex":82,"id":"exchange-038"},{"speaker":"せらく委員","kind":"質問","question":"指導助手がこの中では最もクラスの全体的な様子を見られるのではないかと思ったのですが、こちらを拡大できれば、見守り体制がより安心できるものになるのではないかと考えるのですが、いかがでしょうか。併せて、指導助手の年間２９時間という時間数についても考え方を教えてください。","respondent":"中谷指導課長","answer":"今後、拡大の方向でということで、全体を通しては、先ほど申し上げたとおり、ニーズが上がってきているということ把握しておりますので、学校からの希望をしっかり把握をして事業を進めてまいりたいと考えています。","voiceIndex":85,"id":"exchange-039"},{"speaker":"せらく委員","kind":"質問・要望","question":"ぜひニーズに応えていただきたいと思います。現在の配置体制をとる中で、児童・生徒やクラスの変化にスタッフが気づいた際、連絡の情報共有などは重要な業務だと思いますが、これらの２つと、学校、担任とのコミュニケーションにおいて、そういった情報共有はされていますでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"今後の方向性ですけれども、多くの人材を学校に、今、配置されているメンバーをしっかりと情報共有も含めて児童・生徒の支援に役立てていきたいというふうに考えております。","voiceIndex":87,"id":"exchange-040"},{"speaker":"せらく委員","kind":"質問","question":"スクールカウンセラーについて質問いたします。当区の学校には、週１回程度、カウンセラーがいらっしゃって相談を受け付けていると思います。現在、５年生と７年生で全員面談を行っていると思いますが、その期間は、カウンセラーの人数を増やして相談体制を準備したほうがいいと思いますが、そういった取組はありますでしょうか。品川区の学校現場でのニーズをどのように考えていますか、伺います。","respondent":"丸谷教育総合支援センター長","answer":"現在、スクールカウンセラーは、各小学校、中学校に１名、年間３８回の配置を行っております。義務教育学校では２名配置を行っているところです。１校当たりの児童・生徒数が２６７人以上の学校には追加配置を希望できて、これは５校で実施をしているところです。","voiceIndex":89,"id":"exchange-041"},{"speaker":"せらく委員","kind":"質問・要望","question":"全員面談を行っている期間は、集団でやっていらっしゃるということで、相談したい方、お問合せがあったときに、なるべくしっかり対応していただきたいと、こちらは要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":91,"id":"exchange-042"},{"speaker":"横山委員","kind":"質問・要望","question":"１点目に、ＩＣＴ活用推進経費についてお伺いいたします。学習者用デジタル教科書についてお伺いいたします。２点目に、教育相談事業費についてお伺いいたします。引き続き研修などを通して保健センターなどとも連携をしながら、子どもに対するグリーフケアの理解を深めていただきたいと思うのですけれども、また、実践を重ねていただきたいということを要望いたしますが、区教委のお考えをお聞かせください。","respondent":"丸谷教育総合支援センター長、中谷指導課長","answer":"ＨＥＡＲＴＳをはじめ保健センターとも連携をして、子どものケアに当たっているところです。８年生や９年生には、授業で行うオンラインのレッスンなど、定期的に英語を使って海外の方と直接交流する機会があるということで、お子さんの英語学習に対するモチベーションの醸成にもつながっていると考えております。","voiceIndex":93,"id":"exchange-043"},{"speaker":"横山委員","kind":"質問・要望","question":"これまでに学んできた単元での課題を振り返りつつ、そうそう、確かにそうだったよねということを児童と確認します。４点目へいきます。いじめ防止対策費についてお伺いいたします。万が一、加害者となってしまった子どもたちがいた場合に、どのようなケアをしていますでしょうか。いじめの加害者が特定できたケース、特定できなかったケース、それぞれについて現状を確認させてください。","respondent":"丸谷教育総合支援センター長","answer":"いじめについてですけれども、加害者となってしまった子どもたちへの対応ですが、単発な指導にとどまることなく、組織的、継続的な指導を行うとしております。","voiceIndex":96,"id":"exchange-044"},{"speaker":"横山委員","kind":"質問・要望","question":"５点目に、教材教具等経費についてお伺いいたします。小学校、中学校、義務教育学校などの監査で指摘を受けた後、学校ではどのような対応をされているのでしょうか。通常時の物品等の管理体制、特に外部団体の私物管理、目的外使用許可の現状と、各学校における基準の有無について、学校現場での現在の状況を確認させてください。","respondent":"宮尾庶務課長","answer":"私からは、学校における物品管理の方法等についてお答えをします。監査での学校に関するご指摘をいただきますと、私どものほうで、校長・園長連絡会等で、いただいた指摘の内容、それから原因がどこにあったか、そして今後の対応策等を校長たちと共有をします。","voiceIndex":98,"id":"exchange-045"},{"speaker":"横山委員","kind":"質問","question":"目的外使用の許可の現状について、簡単に教えていただけますか。","respondent":"宮尾庶務課長","answer":"こちらは、規則には細かく表示はないのですが、各学校、地域との良好な関係づくりに沿ってです。","voiceIndex":100,"id":"exchange-046"},{"speaker":"西村委員","kind":"質問・要望","question":"３８３ページ、不登校児童・生徒支援事業、３８９ページ、学校ＩＣＴ活用経費、３９１ページ、ＩＣＴ支援員経費、項目はありませんが、自由進路学習についても伺えたらと思います。ＧＩＧＡスクール構想から３年がたちまして、子どもたちはどのように変わったのか、端末活用の成果と課題、教育の変化があればお聞かせいただきたいと思います。区のお考えや方向性があればお聞かせください。","respondent":"丸谷教育総合支援センター長、柏木学務課長","answer":"およそ３年前にタブレット端末が各校児童・生徒に１人１台配布されました。私からは、２０２５年度のＮｅｘｔＧＩＧＡ構想ですが、こちらについては、教育ＩＣＴ関連団体から、文部科学省や国のほうに提案されているということは聞いてありますが、まだ国のほうから正式に通知等は来てございませんので。","voiceIndex":103,"id":"exchange-047"},{"speaker":"西村委員","kind":"質問","question":"すみません、ＮｅｘｔＧＩＧＡ構想は、そのようなご答弁になるかなと思っていたのですが、さらなる可能性を、広がりを感じておりますので、お伺いさせていただきました。コロナ禍で、このＧＩＧＡスクール構想が始まりまして、ＩＣＴ活用が子どもたちの日常になってきていることを感じています。昨今の状況を伺えたらと思います。","respondent":"丸谷教育総合支援センター長","answer":"本区のタブレット端末ですけれども、家庭でもＷｉ－Ｆｉ環境がなくても使えるような仕様になっておりまして、家に帰っても学習が個々に応じて進められるような配慮をしているということで、他の自治体に比べてもかなり活用は進んでいるというふうな認識です。","voiceIndex":106,"id":"exchange-048"},{"speaker":"西村委員","kind":"意見","question":"もうすぐ学習発表会があるのですけれども、そういった動画でのフォローでしたり、日頃から２次元コードなどを使って子どもが学習しているのを親としても実感しています。一方で、活用できる先生と、できない先生の課題はいまだ残っていると感じておりますが、どのように対応しておられるのか、課題と今後の取組も併せてお聞かせください。","respondent":"柏木学務課長、丸谷教育総合支援センター長","answer":"ＧＩＧＡスクールのＩＣＴの先生たちの対応ですが、基本的には、研修等を実施しています。昨年度、各校の実践事例を集めまして事例集を作成して配布をして活用を広げているところです。","voiceIndex":108,"id":"exchange-049"},{"speaker":"西村委員","kind":"質問","question":"正に今、それを伺おうかなと思っていたのですが、ＩＣＴ支援員の方々が、それぞれに知見をお持ちだろうと思っておりまして、これだけ長く学校の中で活動していただいていますので、学校によって支援員の方に依頼していることも様々異なってきているのではないかなと考えています。３年がたちまして、導入当初と、ＩＣＴ支援員の方々の業務内容がどのように変わってきているのか伺えればと思います。","respondent":"柏木学務課長","answer":"ＩＣＴ支援員の業務内容の変わっているところですけれども、当初は、本当に機器の使い方とか準備がメインとなってございましたが、今は、そのＩＣＴ機器を活用した授業を行うために、教員と連携しながら、学習活動のめあてや、その狙いに沿った活用提案。","voiceIndex":111,"id":"exchange-050"},{"speaker":"西村委員","kind":"質問","question":"そういったＩＣＴ支援員の方々が持っている改善案を学校側に伝えることも大変重要だなと思っておりました。ある教育者の方がおっしゃっていたのですが、既にもう活用できるＩＣＴはそろっていると。区内の授業状況を伺えればと思います。自由進路学習も全国的に広まっておりますので、自由進路学習について区内で取り入れている事例や、区のお考えがあれば、教えてください。","respondent":"丸谷教育総合支援センター長","answer":"自由進路学習ですけれども、子どもたちが、将来、義務教育を終えて、どのような職業に就いたり、夢を持って羽ばたいていくかというところで、そうした子どもたちの夢や希望というものをしっかり教員が把握しながら推し進めていきたいと思っています。","voiceIndex":113,"id":"exchange-051"},{"speaker":"西村委員","kind":"提案","question":"ぜひ引き続き子どもたち一人一人の資質と能力を育む教育をお願いしたいと思います。最後に、不登校の課題につきまして、歳入でも提案をさせていただきました。ログインで出席確認ができ、家にいることが分かったり、家にいるけれども、メタバースにも入ってこないということが分かるなど、児童生徒の安心安全にもつながると思うのですが、区のお考えをお聞かせください。","respondent":"丸谷教育総合支援センター長","answer":"不登校児童・生徒のお尋ねです。現在、フリースクールに通われているお子さんも出席の扱いにできるよう、学校がしっかりと家庭と連携しながら進めるということが大切だと認識しております。","voiceIndex":115,"id":"exchange-052"},{"speaker":"西村委員","kind":"意見","question":"先んじて申し上げましたフリースクール経営者の方が、まだフリースクールは社会の理解など不十分な部分もあるけれども、とはいえ、全部学校でやっていくとなると難しいことも現実にあるのではないかとおっしゃっていました。ぜひとも連携を前向きにお考えいただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":117,"id":"exchange-053"},{"speaker":"新妻委員","kind":"質問・要望","question":"私からは、３７３ページ、就学事務費、３８３ページ、不登校児童・生徒支援事業、３８９ページ、児童・生徒用タブレット端末等運用について、関連をして伺ってまいります。最初の就学事務費について伺います。英語の教育熱の高まりとともに、日本人でも児童・生徒の入学が増えているインターナショナルスクールについてお伺いいたします。区内のスクールと品川区との連携や関わりについても伺います。","respondent":"柏木学務課長","answer":"区内のインターナショナルスクールと区立の学校との連携等ですが、実績については把握をしてございませんが、多分ないと思われます。インターナショナルスクールの就学の状況ですが、例年３０人から４０人程度がインターナショナルスクールに就学していると把握しています。","voiceIndex":119,"id":"exchange-054"},{"speaker":"新妻委員","kind":"確認","question":"区内でも３０人から４０人、通われている方がいるということが分かりました。先ほど確認をいたしましたインターナショナルスクールの学校法上の位置づけにつきましては、委員長に許可を得ましたので提示をしますが、この学校案内にもしっかりと明記されております。既に学務課長にはご相談をさせていただきました。どこでご相談をお受けいただいているのか、お知らせください。","respondent":"柏木学務課長","answer":"インターナショナルスクールからの小学校、中学校へ入る方法ですが、こちらは、まず、先ほど委員からもございましたとおり、通常の中学校につきましては、小学校の教育課程が修了していることが前提になりますので、インターナショナルスクールの小学部を修了したとしても。","voiceIndex":121,"id":"exchange-055"},{"speaker":"新妻委員","kind":"質問・要望","question":"需要があるというふうに思っております。次に、不登校児童・生徒支援事業、タブレット端末等運用について、関連して伺ってまいります。不登校児童の対応というのは大変重要だと思っておりまして、品川区におきましては、現状は特に小学校の増加があると認識されていると伺いました。この国がまとめたアンケートが、どのように品川区に生かされてくるのか、このアンケートについて少しお伺いしたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"今回、不登校を対象にアンケートを国が行うということですけれども、そちらの結果が示されたところで、本区と、大きく増加の理由等は変わらないと思いますので、そうしたものをしっかりと把握しながら、今後の施策に生かしてまいりたいと考えております。","voiceIndex":123,"id":"exchange-056"},{"speaker":"新妻委員","kind":"質問・要望","question":"子どものことなので、何かちょっとしたきっかけ、また、理由がない場合も不登校になってしまうケースもあるかと思います。いろいろな学びの場ができるわけでありますけれども、ご相談をさせていただきましたが、この学校についての対応がどうなったのか、また、希望される児童・生徒がいた場合には、全ての学校でのＺｏｏｍでの授業、しっかりと進めていただきたいと思いますが、見解を伺います。","respondent":"丸谷教育総合支援センター長","answer":"不登校児童・生徒が、家庭でも授業を受けられる環境づくりは非常に大切だというふうに考えておりますので、今ご指摘いただいたことが全ての学校でないように、しっかりと対応するように学校への指導を進めていきたいと考えております。","voiceIndex":125,"id":"exchange-057"},{"speaker":"おぎの委員","kind":"質問","question":"本日もよろしくお願いいたします。本日は、３８３ページ、３８９ページの英語教育と、それに関連して品川区の教育方針全般、また、３８１ページ、市民科・各教科、時間があれば、３７３ページのクラブ・部活動についてお伺いいたします。最初に、品川区としては、どういった人物を育成したいのか、教育の方針や目標などをお聞かせください。","respondent":"中谷指導課長","answer":"品川教育ルネサンスを未来を切り拓く子どもの育成ということで、子どもたちが粘り強く生き抜く力を養えるようにということで推進しています。","voiceIndex":128,"id":"exchange-058"},{"speaker":"おぎの委員","kind":"質問・要望","question":"３８３ページの品川英語力向上推進プランを見ますと、１年生から６年生の英語科経費と英語力向上推進経費、２項目ありまして、こちら、後半のほうが７年生から９年生の学習かなと思われますが、こちら、双方にあります外国人英語講師学習指導、イングリッシュキャンプ、こちらをどのように行っているのか、また、７年生から９年生のグローバル人材育成塾、こちらの対象や内容をお聞かせください。","respondent":"中谷指導課長","answer":"英語科ですけれども、品川区で、平成１８年度より、１年生から９年生までを対象に実施しております。","voiceIndex":130,"id":"exchange-059"},{"speaker":"おぎの委員","kind":"質問","question":"非常に様々な取組をしているということが分かりました。今のお話の中で、１点、グローバル人材育成塾、こちらは希望者ということになっておりますが、今、生徒の中では何割ぐらいの生徒が希望して参加していますでしょうか。こういった様々な事業は、品川区教育委員会が独自で企画しているのか、または民間の業者に委託しているのかもお聞かせください。","respondent":"中谷指導課長","answer":"今年度、今、後半がスタートしたところなのですけれども、２２４名が参加しているということで、同じ方が継続しているケースもあれば、新たに申込みをされるようなケースもあるかなというふうに思っております。こちらにつきましては、民間に対して委託という形で実施しています。","voiceIndex":132,"id":"exchange-060"},{"speaker":"おぎの委員","kind":"意見","question":"国際化社会に向けての取組といったことで、非常に手厚い英語教育ということが分かりました。私たちの頃は、まだ英語の本を読んだりとか、海外の友達と文通しようとか、そういった企画しかありませんでしたので、今の子どもたちは本当に英語が身近になっているなと感じます。一方で、日本の文化や歴史についての学習はどのようなことを行っているのか、お聞かせください。","respondent":"中谷指導課長","answer":"日本文化についてのご質問ですけれども、昨年度は、学校２０２０レガシー事業としまして、狂言ですとか、能の鑑賞を行うことを通じて、日本伝統文化を理解する取組を行っております。","voiceIndex":134,"id":"exchange-061"},{"speaker":"おぎの委員","kind":"質問","question":"海外に出ますと、留学や海外で何年か仕事をされた経験のある方はご存じだと思いますけれども、物すごく日本のことについて聞かれます。最後に、クラブ・部活動等経費についてお伺いします。３７３ページ、３７５ページ、こちらで、今、外部の指導員の方を随分お願いしているようですが、こちら、外部の指導員の方は、どういった方で、今、何人ぐらいいるのか、現状をお聞かせください。","respondent":"柏木学務課長、丸谷教育総合支援センター長","answer":"クラブの外部の指導員ですが、すみません、どういう方かというところまでは、すぐは分からないのですけれども、年度途中でありますが、今年度の状況でいきますと、約１００人ほど雇用をしている状況です。部活動指導員も配置をしております。","voiceIndex":136,"id":"exchange-062"},{"speaker":"ひがし委員","kind":"確認","question":"本日もよろしくお願いいたします。私からは、３８３ページ、不登校児童・生徒支援事業について、３８１ページ、市民科・各教科充実経費について質問をします。最初に、不登校児童・生徒支援事業についてですが、先ほど、他の委員の質疑で、品川区でも不登校児童が増えているということ、そして、特に小学生児童の不登校が増加しているとの答弁を確認することができました。そこで、お伺いいたします。","respondent":"丸谷教育総合支援センター長","answer":"フリースクール、フリースペースにつきましては、今、連携が求められているものであり、現状としては、なかなか学校も把握できていない部分もありますので、今後広げていきたいと考えております。","voiceIndex":140,"id":"exchange-063"},{"speaker":"ひがし委員","kind":"質問・要望","question":"ぜひ連携というところも強めていただきたいと考えています。一方で、現在、品川区のマイスクールでは、１年生からを対象にしたものがありません。必要としている児童が通えるような整備拡充が必要だと思うのですが、今まで小学校１年生、２年生を対象にしていなかった理由、また、現在の不登校児童の増加による今後の区の方針について、お考えをお聞かせください。","respondent":"丸谷教育総合支援センター長","answer":"マイスクールの対象の学年ですけれども、５年前までは、例えば一、二年生の不登校の児童の数は１０人にも満たないということで、かなり低い数字でございました。昨年度は２０名を超えておりますので、そういった意味で、今後、必要な取組かなというふうに考えております。","voiceIndex":142,"id":"exchange-064"},{"speaker":"ひがし委員","kind":"質問・要望","question":"ぜひ１年生からも対応できるマイスクールの整備、また、定員も、不登校児童が増えているということを含めまして、拡大も前向きに検討いただけるように要望をします。先ほど少し答弁はありましたが、１年生から対応できるマイスクールの整備、定員の拡大ということを、現在、検討している状況があればお聞かせください。","respondent":"丸谷教育総合支援センター長","answer":"保護者に分かりやすいものということで、現在、ガイドブックの作成を検討しておりまして、また、ホームページの充実ということで保護者への周知も図っていきたいと考えております。","voiceIndex":144,"id":"exchange-065"},{"speaker":"ひがし委員","kind":"質問","question":"次の質問に移らせていただきます。続いて、市民科・各教科充実経費に関連して、性教育についてお伺いいたします。今回の決算特別委員会期間中には、幼少期からの性教育、また、大人の性教育についての質問も上がっていたと思います。品川区として、この包括的性教育、生命の安全教育についての必要性について、どのようにお考えでしょうか。現在、どのような形で授業が行われているのか、お聞かせください。","respondent":"丸谷教育総合支援センター長","answer":"生命の安全教育についてですけれども、本年度より全校で教育課程に位置づけをして全学年で実施をしております。必要性といたしましては、国も進めているとおり、本区においても必要なことだというふうに考えております。","voiceIndex":146,"id":"exchange-066"},{"speaker":"ひがし委員","kind":"質問","question":"毎年、各学年ごとで実施されており、生徒たちも積極的に手を挙げて授業に参加している様子が伺えました。そこでお伺いします。品川区公立校の中で、外部講師を招いての授業をしている学校はあるのでしょうか。もし行われている場合は、実施した際の生徒、保護者、教員などから反応はどのようなものだったのでしょうか。分かる範囲でお聞かせください。","respondent":"丸谷教育総合支援センター長","answer":"外部講師を招いての性教育についてですけれども、区立学校においても、例えば浜川中学校で、今年の７月に９年生を対象に「ライフスキル講座」という名称で、産婦人科医を呼んだ講演会を行っております。","voiceIndex":148,"id":"exchange-067"},{"speaker":"ひがし委員","kind":"質問・要望","question":"外部講師の授業を、現在、１校開始しているということで、ぜひ進めていただきたいのですが、教えるために考慮するべきことが多く、現場のハードルが高いとの声もあります。この取組を品川区が後押ししているということが分かるように、ぜひ、がん教育推進事業のように、予算化も検討していただきたいと思いますが、いかがでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"今回、１校が行っておりますけれども、学校のニーズに応じた取組支援ができるように努めてまいりたいと考えております。","voiceIndex":150,"id":"exchange-068"},{"speaker":"やなぎさわ委員","kind":"意見","question":"１０月２日は松本委員のお誕生日でもありまして、決算特別委員会１日目でした。お願いします。ただ、会計年度任用職員だと、原則、３年で雇い止めというようなことになっていると思うのですけれども、やはり質の高い教育、教職員の負担軽減という意味では、非常に大事なポジションである会計年度任用職員、３年で雇い止めになってしまうような状況に今なっているのか、その辺のご認識をお願いします。","respondent":"中谷指導課長","answer":"指導課の会計年度任用職員ですけれども、この２４５名の内訳としましては、教育アドバイザー、スクール・サポート・スタッフ、区費講師、英語専科指導員、代替職員、学校地域コーディネーター、副校長補佐となっておりまして。","voiceIndex":155,"id":"exchange-069"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"例えば、スクール・サポート・スタッフであるとか、学校地域コーディネーターの方とか、特に学校地域コーディネーターの方、やはり元保護者だったり、ＰＴＡの方だったりということで、非常によく地域のことを分かっていらっしゃって、私も一緒に地域活動をしているのですけれども、非常に今、貴重な存在だと思いますので、ぜひ継続的に雇用をしていただいて、さらに地域と学校。","respondent":"宮尾庶務課長","answer":"教育委員会全体の会計年度任用職員に関わることですので、私のほうからお答えをさせていただきたいと思います。会計年度任用職員は、規定に基づいていろいろな職別に勤務条件が定められておりまして、その中に、当然ですが、給与のことも入っております。","voiceIndex":157,"id":"exchange-070"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"３８１ページの市民科なのですけれども、先ほど、ほかの委員、ひがし委員とかも質問がありました性教育に関してです。生徒に正しい知識を、大人からというか、先生からというか、教えることで、いろいろな被害に遭わないようにとかということを進めていくものであって、学校のニーズではないと思うので、ぜひそういったことは積極的に取り組んでいただきたいというふうに思いますが、いかがでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"そういった意味で、全校で取り組んでいることは取り組んでいるのですけれども、外部講師を呼ぶというニーズには応えていきたいという趣旨での答弁でございました。","voiceIndex":159,"id":"exchange-071"},{"speaker":"やなぎさわ委員","kind":"提案","question":"私からの提案なのですけれども、こういった性教育は、なかなか先生と生徒で、まだ今の日本の下地だと、踏み入った話はしにくいというところがあるので、こういうことは外部講師の方に来てやってもらったほうが、日々顔を合わせる先生と生徒だと、少し恥ずかしかったり、いろいろ相談もしにくかったりすると思うので、やはりこういう外部講師の方が来てお話とかがあると、例えば。","respondent":"中谷指導課長","answer":"一貫教育ということで、こちらに掲げさせていただいておるのは、品川区の公立の学校の９年間の教育をどう充実させていくかというものになってあります。","voiceIndex":161,"id":"exchange-072"},{"speaker":"やなぎさわ委員","kind":"質問","question":"分かりました。これ、仮になのですけれども、品川にある私学で何か問題が起きて、例えば、学校教育というか、運営が悪いとか、何かそういったことが起きたときは、品川区としてどういった対応をとられたりとか、窓口は、相談体制はどのようになっていますでしょうか。","respondent":"柏木学務課長","answer":"学校ですけれども、品川区が所管するのは、品川区が設置者になっております品川区立学校となります。それ以外の私立等については、基本は運営する学校法人または東京都になります。","voiceIndex":163,"id":"exchange-073"},{"speaker":"やなぎさわ委員","kind":"質問","question":"実際起きている話なのですけれども、私自身が、品川にあるとある私学の生徒とか保護者の方から相談をいただいていて、学校の運営に対して少し不満があるというか、入学前の話と全然違うような指導が実際に行われているということで、それを東京都の私学行政課に相談しているのですけれども、私学行政課から学校に、そういう苦情がありましたということしか言えないということで、なかなか解決まで進まなくて。","respondent":"柏木学務課長","answer":"保護者、生徒から、品川区立の学校に関わってとか、本人の相談というのは受けられるのですが、私立の学校自体に品川区教育委員会では指導する権限等がございませんので、そういうものは受けられないということになります。","voiceIndex":165,"id":"exchange-074"},{"speaker":"こしば委員","kind":"質問・要望","question":"よろしくお願いします。私からは、３８３ページ、英語科経費、英語力向上推進経費について、３８１ページ、市民科・各教科充実経費に関連して国語教育について、３７７ページ、人権尊重教育推進経費に関連した「Peace of Cake」を使った平和教育についてお伺いいたします。初めに、３８３ページ、英語科経費、推進経費についてお伺いいたします。","respondent":"中谷指導課長","answer":"学級の中で授業を教えるに当たって学級担任がおりまして、その方とチームティーチングということで、指導される外国人の方に入っていただくというようなところになっておりまして、お二方で１つの英語の授業を教えるというようなスタイルになっております。","voiceIndex":169,"id":"exchange-075"},{"speaker":"こしば委員","kind":"質問","question":"このＡＬＴの先生なのですけれども、これまでは委託であったということですが、今回、令和４年度から人材派遣に変更になったと聞いています。一見すると、委託のほうが定着をするのではないか、人材派遣だと、コロコロ変わってしまうのではないかといった、そういった懸念があるのですが、その辺り、どのような経緯で委託から人材派遣に変わられたのか、教えていただければと思います。","respondent":"中谷指導課長","answer":"派遣に変わったことによるメリットが一定程度ございまして、これまでですと、決められた指導内容だけであったものが、例えば、授業外でお子さんの作品に対して採点をしたりですとか、見守るというような直接的な指導をしたりですとか。","voiceIndex":171,"id":"exchange-076"},{"speaker":"こしば委員","kind":"質問","question":"これだけでも、この３０年間にわたります児童・生徒の英語力の向上は歴然としているのだなと分かった次第ですが、行政評価シートなどを読みますと、小学校１年からの英語教育だけではなく、高学年に上がるにつれまして、授業時間が３５時間から７０時間に伸びていき、相当力を入れているということは分かるわけですが、４年生、ちょうど３５時間から７０時間に変わる最後の３５時間の授業を受ける４年生には。","respondent":"中谷指導課長","answer":"イングリッシュキャンプにつきましては、お話しいただいたジュニア・イングリッシュキャンプというものと、ジュニアがとれましたイングリッシュキャンプというものと２つやっておりまして、４年生でやっておるものがジュニア・イングリッシュキャンプ、こちらに関しては。","voiceIndex":173,"id":"exchange-077"},{"speaker":"こしば委員","kind":"質問・要望","question":"例えば、区内在住で、以前、海外に駐在した経験のあるビジネスマンだとか、外国で国交の維持、そして発展を担う外交官、海外で事業を始めた個人事業主など、様々な外国で仕事をしている、また、してきた人から話を聞くことで、またそれが英語力の向上、英語を学ぶというモチベーションの向上にもつながると考えますが、品川区のお考えについてお聞かせいただければと思います。","respondent":"中谷指導課長","answer":"英語教育の成果と、このようなドリームジョブ事業の成果を合わせて見ていきながら、品川区で行っている様々な施策がトータルで学習者であるお子さんを支えていけるように、これからも継続して支援していきたいと考えています。","voiceIndex":175,"id":"exchange-078"},{"speaker":"こしば委員","kind":"質問・要望","question":"この「ことのは」というのは、大和言葉といいますか、古の時代から続く言葉でして、言葉の力、その言葉に魂が載っているような、そういった本来我々が使っています言葉以上のものを感じ取ることができたわけなのですけれども、まず、この品川区のオリジナルの教材「ことのはノート」について、簡単に教えていただければと思います。","respondent":"丸谷教育総合支援センター長","answer":"１年生から６年生までは各１冊ずつ、７年生から９年生で１冊という形で、各児童・生徒に配布をしているものです。","voiceIndex":177,"id":"exchange-079"},{"speaker":"こしば委員","kind":"質問","question":"そういう中で、なかなか文字数の限られた情報では、どうしても一定の読解力がないと、なかなか正確に読み取ることができない。それを国語教育の中で結びつけていることがあるとすれば、どういったものなのか、教えていただければと思います。","respondent":"丸谷教育総合支援センター長","answer":"ＳＮＳの活用につきましては、子どもたちが、やはり発信力、読んだ相手がどう感じ取るかということも想像しながら発信していくということが大切だと考えております。","voiceIndex":179,"id":"exchange-080"},{"speaker":"こしば委員","kind":"質問・要望","question":"ぜひ情報リテラシーの力を養っていただきますよう、そして読解力をぜひ向上していただきたいとお願いをしまして、続きまして、３７７ページ、人権尊重教育推進経費に関連しまして、平和に関する指導についてお伺いいたします。戦争やテロに対する言葉が「平和」だとするならば、もう既に品川区でも平和を求める教育が実践されていることと認識しております。","respondent":"丸谷教育総合支援センター長","answer":"毎年、区立学校の８年生を広島に派遣させていただいて、それを校内で還元するという事業を進めております。平和に関する指導資料を作成して各校に配布しています。そういったものを活用しながら、各校での取組を充実させていきたいと考えております。","voiceIndex":181,"id":"exchange-081"},{"speaker":"つる委員","kind":"質問・要望","question":"３７５ページ、就学支援費、３９５ページ、給食運営費、３８７ページ、図書館運営費、３９１ページ、学校図書館経費について伺っていきます。学校給食の無償化については、今年度、品川区の英断で実施していただいているところでありまして、学用品につきましては、この間、議会からも何度も繰り返し無償化等を求める声が現場の声として上げられているところであります。","respondent":"柏木学務課長","answer":"今年度から無償化に伴って、夏休みの子どもたちの食事の件ですが、特に教育委員会として把握しているところではございませんが、学校から何か子どもたちに異常があるとか、気になるところがあるという声は、特には寄せられてございません。","voiceIndex":184,"id":"exchange-082"},{"speaker":"つる委員","kind":"質問・要望","question":"学用品については、単純な計算でありますけれども、年間５億円強ぐらいなのかというところで、これは全体的な考え方になると思うのですが、過日の質疑、答弁等を確認すると、学用品も含めたさらなる家庭への負担軽減というところでご答弁があったかというふうに記憶しているので、ここについては、しっかりと何からとか、何を、また、どういった方をと、いろいろな角度からの検討があろうかと思いますが。","respondent":"吉田品川図書館長","answer":"そういうものを使いまして、お声かけをするなり、お持ち帰りの際に不便にならないような対応をしているということは聞いているところです。それから、福祉の関係で各地区図書館で取り扱っているものの中で、トートバッグという話が今出てまいりました。","voiceIndex":187,"id":"exchange-083"},{"speaker":"つる委員","kind":"提案","question":"ぜひ検討してください。ちなみに、今日はウォルト・ディズニー・カンパニーの創立１００周年で、ウォルトということで、かつて「美女と野獣」のベルの読書のことでお話ししたことがあるのですが、最後、別のウォルトでウォルト・ホイットマンの言葉で、「僕は、納得のいく結果がでるまでは、挑戦、挑戦、そして挑戦する。私も今まで様々な決算特別委員会の提案をさせていただきました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":189,"id":"exchange-084"},{"speaker":"石田（し）委員","kind":"質問","question":"私からは、今日の何の日はないですが、３７１ページをはじめとする給与費について、同じく３７１ページをはじめとする不用額について、そして３７９ページ、生徒指導対策等経費に関連して不登校について、時間があれば、３７９ページ、ルネサンス推進事業について、それぞれ質問していきます。令和４年度をはじめとし、コロナ禍において、様々不用額が出てきたと思います。よろしくお願いします。","respondent":"中谷指導課長、丸谷教育総合支援センター長、大串会計管理者","answer":"教職調整額による支払いということで、残業代ではないというところになります。確かに数字が上がっているということで、減らす努力もしているところではありますけれども。教育費における不用額、こちらにつきましては９億２,７２９万８,２８０円という形です。","voiceIndex":191,"id":"exchange-085"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"これ、なぜ質問をしたか、私はもともとこの給特法が、そもそも改正をするべきだと思っていて、これをぜひ区教育委員会からも、私からもしっかりと東京都や国に対して働きかけもしますが、品川区としても、品川区教育委員会としても、やはりこういった今の時代に合わないような法律は改正をするべきだということを強く訴えていただきたいなというふうに思います。これは要望で終わります。不登校についてです。","respondent":"丸谷教育総合支援センター長、森学校施設担当課長、米田教育次長","answer":"そういったところをしっかりと支援していきたいというふうに考えます。契約落差であったりとか、大きいのは、国有地の購入についての半額ぐらいが、何億という単位で起こっているということがあります。不用額の考え方ですけれども、これまでコロナ禍において修学旅行が実施できなかった。あるいは、移動教室に行けなかったというようなことがあります。","voiceIndex":195,"id":"exchange-086"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"いろいろ取り組んでいただいているということは分かりました。これは要望で終わります。このジェネレーションギャップをどうやって埋めて、教員が子どもたちに新たな新しい時代に生き抜く力をつけていくということがとても重要になってくるのかなと思うので、これはまた別の機会でやりたいと思いますが、ぜひ心の準備だけしておいていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":199,"id":"exchange-087"},{"speaker":"のだて委員","kind":"質問・要望","question":"私からは、３９１ページの学校図書館経費に関わって、図書館司書の配置拡充を求めて質問をします。私も毎日配置をしていただきたいと思います。こうした要望も含めて、契約更新の際に配置を増やす予定だと審議の中でも説明されていましたが、新しい契約では、配置日数は、これまで同様、２.５日、週１５時間の配置に据え置かれました。なぜこの学校図書館司書の配置を増やさなかったのでしょうか、伺います。","respondent":"吉田品川図書館長","answer":"図書館といたしましては、学校司書の拡大について前向きに検討してきたところです。そのように進めてきたところですが、所管の考え方が所管としてありまして、また、予算となりますと、全体の中で調整をする形になると思います。","voiceIndex":201,"id":"exchange-088"},{"speaker":"のだて委員","kind":"質問","question":"図書館としては検討してきたけれども、予算上、無理だったということだと思いますが、予算上無理だと判断をした理由を伺いたいと思います。","respondent":"吉田品川図書館長","answer":"この辺は繰り返しになってしまうかもしれませんが、所管の思いと、それから、区は当然、所管の思いだけで動いているわけではございませんので、全体の中で必要なところに必要な額というところで。","voiceIndex":203,"id":"exchange-089"},{"speaker":"のだて委員","kind":"質問・要望","question":"なぜ図書館司書の配置を増やさなかったのかということを伺いたいと思います。併せて、今回、拡充されなかったということで、やはり国も図書館の活用ですとか、読書を増やしていこうということで推進をしている下で拡充されなかったということは、教育環境の整備が遅れてしまったと思いますが、いかがでしょうか。","respondent":"遠藤財政課長","answer":"予算がつかなかった理由というところですけれども、予算は、それぞれ優先事項等もありますし、あるいは、費用対効果とか、様々なものがありますので、所管としては、いろいろな形でぜひやりたいという形でいただいているのですけれども、予算上の制約などもあり。","voiceIndex":205,"id":"exchange-090"},{"speaker":"のだて委員","kind":"質問・要望","question":"優先事項などいろいろあって見送ったということですけれども、今回この契約更新の時期が拡充をするチャンスだったわけです。そこで拡充をしていくということがやはり求められていたと思いますけれども、そこをなぜ重視しなかったのか伺いたいと思います。それと、教育環境の整備が遅れてしまったのではないかという質問もしたので、お答えいただきたいと思います。","respondent":"吉田品川図書館長","answer":"教育環境の整備が遅れたかどうかについては、現在も２３区の中で学校司書の配備としては大体真ん中辺、時間数としては、２３区の中で大体中真ん中辺のところの位置を占めておりますので、著しく遅れたというふうには認識しておりません。","voiceIndex":207,"id":"exchange-091"},{"speaker":"のだて委員","kind":"質問","question":"ぜひ財政課からも改めて、なぜ重視をしなかったのかというところを伺いたいと思います。拡充をするために予算をつけなかったのかということです。学校図書館司書が、やはり子どもたちの学び促進をしていくために私は重要だと思うのですけれども、区としては、これを重要だと考えていないのか、伺います。","respondent":"遠藤財政課長、吉田品川図書館長","answer":"大事な事業ということは理解させていただいているところですけれども、やはり先ほど言いました、どうしても予算には限りがありますので、どうしても取捨選別しなければいけない部分がありますので、ご理解いただければと思います。区として重視しなかったのかというところなのですけれども、先ほども申し上げましたけれども、２３区の中で真ん中辺の図書館司書の確保をしています。そういう部分もありまして、重要と考えていないわけではございません。","voiceIndex":210,"id":"exchange-092"},{"speaker":"のだて委員","kind":"質問・要望","question":"重要と考えていないわけではないということだと。配置について、２３区の中で真ん中ぐらいだということですけれども、やはりほかの区では、進んでいるところは週６日配置をしているところとか、週５日配置をしているところもあるというところで、やはりそうした促進をしていくことこそ必要だと私は思います。今の状況では確保できていないというふうに思いますけれども、いかがでしょうか。","respondent":"吉田品川図書館長、丸谷教育総合支援センター長","answer":"学校からの要望では、図書の時間を増やしてほしいという要望をいただくこともあります。それを含めまして、全体、必要なところと、足りていないところもあるとは思います。ただ、現在は、できるところで頑張っているです。昨年度よりも、１か月の貸出しの冊数も、若干ではありますけれども、増加傾向にございまして、着実に学校のほうでは推進を図っているところです。","voiceIndex":213,"id":"exchange-093"},{"speaker":"のだて委員","kind":"質問","question":"やはり１冊読むには１日では終わりませんので、通い続けたという記憶があります。司書がやはり週２.５日しかいないので、そうしたことも今の子どもたちはできないということだと思います。やはり今、図書館が居場所としても注目されていますので、ぜひこうした面からも、週５日、毎日学校図書館司書を配置することが子どもたちの学習をよりよいものにすると思いますが、いかがでしょうか。","respondent":"吉田品川図書館長","answer":"学校司書は確かに２.５日配備ですけれども、それ以外の日は図書館が開いていないということではございません。","voiceIndex":216,"id":"exchange-094"},{"speaker":"のだて委員","kind":"質問","question":"開いていないわけではないと。お昼休みとかは開いているということですか。それはそれでよかったのですけれども、やはり司書を毎日配置することが、子どもたちの学習をよりよいものにすると思いますが、いかがでしょうかということも伺ったので、お答えいただければと思います。","respondent":"吉田品川図書館長","answer":"そういうことを含めまして、図書館司書、ボランティア、地域、それから学校の図書委員等を含めまして、みんなで学校図書館を盛り上げていければと考えています。","voiceIndex":218,"id":"exchange-095"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひみんなで盛り上げていくということはやっていただきたいと思うのですが、司書を配置しない理由にはならないというふうに思いますので、５日はぜひ、毎日いるような形で司書配置をしていただきたいと、これは求めておきたいと思います。ぜひそうしたことを強めていっていただきたいと思うのですが、現在、図書館司書は、職員会議に参加しているのか、伺います。","respondent":"吉田品川図書館長","answer":"現在の図書館司書が職員会議等に参加しているかという件についてのお答えですけれども、今回、図書館司書については委託ですので、委託の社員と学校が直接調整を行うということは、偽装雇用になりますので、そのところは行っていないところです。","voiceIndex":220,"id":"exchange-096"},{"speaker":"のだて委員","kind":"質問・要望","question":"どのような子どもなのかということが分かれば、その子に合った図書を提供できるということにもつながっていきますし、やはりそれが学びを深めることにもなると思います。東京都も直接雇用が今進められておりますけれども、やはり区としても、直接雇用を進めていくことが必要だと思います。区が図書館司書を直接雇用して図書環境の充実を図っていただきたいと思いますが、いかがでしょうか。","respondent":"吉田品川図書館長","answer":"そういう中では、一定レベルの知識、技術を持った専門業者に委託したほうが安定的運用が図れると考えて、現在の形をとっているところです。","voiceIndex":222,"id":"exchange-097"},{"speaker":"のだて委員","kind":"質問・要望","question":"子どもたちのために充実をさせていくというところで進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":224,"id":"exchange-098"},{"speaker":"田中委員","kind":"質問","question":"調査委員会を立ち上げて、その結果としての報告もあったわけですが、これは区長自身の英断であるという一方で、逆に、教育委員会側は何しているのだというような捉え方を私はしますし、ぜひ教育委員会の皆様には、区長にまでわざわざお出ましいただかなくても、自らに自己改善力を発揮していただいて、こういった記者会見は区長からのお話もあったのかもしれませんが、調査委員会の結果報告というか。","respondent":"丸谷教育総合支援センター長","answer":"今回、教育委員会の中での区長への報告ができていなかったこと、そういったことも踏まえまして、記者会見の場をお借りして我々のほうからも説明をしたという流れです。","voiceIndex":226,"id":"exchange-099"},{"speaker":"田中委員","kind":"質問・要望","question":"記者会見は、もちろんあれなのですけれども、そこから先の自己解決能力がどこまで発揮されたのかというところに、私は他人事、他人任せのような、要は、区長任せのようにしか感じとれないのですけれども、そこら辺の受け止め、ぜひ教育長からもお聞かせいただきたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"自己解決ですけれども、対策委員会の報告書の中身を真摯に受け止めておりまして、具体的に、午前中もありましたが、基本方針の改定でありますとか、教育委員会事務局内で改めて法律に基づいたいじめの認識を行うこと、また、学校に対しては。","voiceIndex":228,"id":"exchange-100"},{"speaker":"田中委員","kind":"質問・要望","question":"そういったことで、ぜひ対応していただきたい。ですから、そういった卒業生の方から、自らの体験をまたフィードバックしていただいて一貫教育に生かしていただくとか、あるいは、学校の先生、携わった先生も、毎年のように１３０人から１５０人、転入出が品川区内あるわけですが、その転出された一貫校で携わった先生からも、どうだったかということをぜひヒアリングをしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":230,"id":"exchange-101"},{"speaker":"こんの委員","kind":"質問","question":"私からは、３７５ページ、就学援助費、３７７ページ、会計年度任用職員給与費、３９３ページ、登下校区域防犯カメラ維持管理費、この３点をお伺いしたいと思います。そこで、行政評価にもありましたけれども、認定数や認定率など、実績を踏まえて、今後この事業については、どのようにお考えなのか、方向性をお聞かせください。","respondent":"柏木学務課長","answer":"そういうことを鑑みますと、就学援助に関わらず、保護者が負担する金額については減らす必要があると考えています。","voiceIndex":232,"id":"exchange-102"},{"speaker":"こんの委員","kind":"質問・要望","question":"この教材・教具について、今年の３月の予算特別委員会でもこのことは取り上げさせていただいて、ご家庭の負担軽減の観点から、必ずしも個人持ちの教材・教具でなくても、教材によっては共有できる教具があるのではないかと、私費による学用品の見直し、工夫をしてはどうですかという、こうした質問をさせていただきました。もしあるとしたら、年間どれぐらいあるのか教えていただきたいと思います。","respondent":"柏木学務課長","answer":"ただ、突然滞納になったり、滞納が続くような方については、学校を通じて就学援助の紹介をさせていただいて、就学援助は随時受けておりますので、そこで学務課のほうにご相談いただくというようなことをとってあります。","voiceIndex":234,"id":"exchange-103"},{"speaker":"こんの委員","kind":"意見","question":"冒頭にも申し上げましたとおり、この社会情勢の影響から、家計の負担が大変な中で、教育費は待ったなし、こうした状況を考えると、就学援助を受けている、受けていない、こうしたことに限らず、私費による教材・教具のこの点について援助するなど、負担軽減策を検討してはどうかと思いますが、ご見解をお聞かせください。","respondent":"柏木学務課長","answer":"前回、予算特別委員会でご質問をいただいておりまして、今年度、全校を対象に、保護者が購入しています、教材等の調査を全校に行いました。その調査等を参考に、今後、保護者の負担を軽減する策等について検討をしてまいります。","voiceIndex":236,"id":"exchange-104"},{"speaker":"こんの委員","kind":"質問","question":"ぜひ前向きに検討をお願いしたいと思います。次の質問に参ります。会計年度任用職員給与費の中から代替教員の確保についてお聞きしたいと思います。いわゆる教員不足が社会問題になっております。こうした状況について、区の教育委員会としては、どのようにこの現状を捉えていらっしゃいますでしょうか。品川区の教育現場の実態についてお伺いしたいと思います。","respondent":"中谷指導課長","answer":"ご指摘いただいた管理職の先生がこの対応に大変お忙しくなるという状況は把握しておりまして、例えば、教員のご案内というところで、これまでの名簿を使うというところ以外にも、区のほうでホームページで募集を行うとともに、こちらに直接。","voiceIndex":238,"id":"exchange-105"},{"speaker":"こんの委員","kind":"質問・要望","question":"ここをぜひ区教委のほうでサポートができる体制をとられたらいかがでしょうか。いわゆる学校任せという言い方はあれですけれども、不測の事態が生じた場合は学校で対応する、そうしたことは考えられなくはないですけれども、学校だけで探すのは、さすがにこれ、現状、厳し過ぎますので、どうか区教委のほうでも、こうした体制をとる支援を検討していただきたいのですが、いかがでしょうか。","respondent":"中谷指導課長","answer":"もちろんこちらの使い勝手ですとか効果は検証していかなければならないのですけれども、１つだけの方法に頼らない方法ということで、こちらも組み合わせたりということでやってまいりたいと思います。","voiceIndex":240,"id":"exchange-106"},{"speaker":"こんの委員","kind":"質問","question":"データバンク等々を作ってくださっているという状況が分かりました。学校の先生たちが探す作業のほかにやらなければいけないことはたくさんありますので、その点をいま一度お願いしたいと思いますけれども、いかがでしょうか。","respondent":"中谷指導課長","answer":"副校長がやらなければならない仕事の中でも、少し任せていけるような、コンピュータと向かい合わなければいけないような部分、調査への回答ですとか、そういったことも含めて、もう１人の方にプラスアルファで入っていただいて。","voiceIndex":242,"id":"exchange-107"},{"speaker":"こんの委員","kind":"質問・要望","question":"学校選択制によって通学路は範囲が広いですので、この台数で十分なのでしょうかというのが１つです。年々、ここ３年間で少しずつ微増という照会の協力をしているようですけれども、この照会というご協力の中から、今、四、五台しか設置されていないこの状況について、やはり安全面、子どもたちの防犯という観点から、もう少し設置が必要ではないかと思われますが、現状どのように捉えていますでしょうか。","respondent":"森学校施設担当課長","answer":"その点検の中で、ここの通学路には防犯カメラが有効だということが分かり次第、即対応するような考えでおりますが、今のところ、違う方法で対応をとっているところですけれども、答申が出れば対応していきたい、そのように考えてあります。","voiceIndex":244,"id":"exchange-108"},{"speaker":"こんの委員","kind":"意見","question":"答申が出たところは対応してくださるということですけれども、いわゆる照会の事案等もありますので、そうしたところには防犯カメラがあっての事案の照会ですけれども、そうした事案を見て、積極的に設置をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":246,"id":"exchange-109"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"改めてその方が議員時代に言っていた言葉を思い出しました。改めて、こういうときに、新任の教員の方、それから、何年目かの教員の方、社会人としての素養がある程度求められるのかなと思っています。もう１つ言うと、今、変化が激しい時代だからこそ、教員に求められるのは資質能力を確実に身につけること、これが重要だということで言われています。ここら辺のところを改めて教えていただきたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"いろいろな児童・生徒、保護者への対応についてですけれども、対応がうまくいかないときには、管理職を通して教育委員会のサポート体制ということも含めて、フォローの体制をしっかり整えているところです。","voiceIndex":248,"id":"exchange-110"},{"speaker":"石田（秀）委員","kind":"質問","question":"第一は教育は家庭なのだから。例えば、小学生でも、学校にいるのは１日７時間ぐらいであって、それ以外は、すまいるスクールとかいろいろあるけれども、塾だとか、いろいろなところ、もちろん家庭なのだよ。その中でやれることを、私は品川の教育はよくやられていると思っているので、それぐらいまでしっかり言い切ったほうがいいような気がしてならなくて、改めて、もう一度そこら辺を教えてください。","respondent":"丸谷教育総合支援センター長","answer":"家庭教育の大切さについても、品川が特に力を入れているものだと思いますので、例えば、４月の入学時、校長先生から、家庭の役割、学校で教員の役割ということで、しっかりそこを押さえていくということも、併せて。","voiceIndex":250,"id":"exchange-111"},{"speaker":"石田（秀）委員","kind":"意見","question":"よろしくお願いします。もう１点、これはどうしてもやりたかったので、３８９ページ、部活動支援みたいな形なのだけれども、先日、大相撲の巡業がありました。それは付き人の人でも、幕下以下の取的という人たちも、関取もみんなできている。これぐらいのことはしっかりやったほうがいい。挨拶ぐらいはしっかりやらせるというぐらいは、ぜひお願いしたい。ここら辺のところ、最後、それだけ聞きたい。","respondent":"丸谷教育総合支援センター長","answer":"教員、それから子どもたちが挨拶をするというのは非常に大切だというふうに思います。目配せ、アイコンタクトも非常に大切だと思いますので、そうしたことも充実というか、学校が取り組めるようにしたいと思います。","voiceIndex":252,"id":"exchange-112"},{"speaker":"まつざわ委員","kind":"質問","question":"私からは、３８１ページ、市民科・各教科充実経費、関連して３７６ページの教育指導費について質問します。私たちが日々目にするニュースです。そういった前向きな質問をやっていきたいと考えています。我々大人が見てもそう感じるものですから、子どもたちの心境は計り知れないと思います。教育委員会として、近年増えつつあるネガティブニュースの課題をどう捉えているのか、お示しください。","respondent":"丸谷教育総合支援センター長","answer":"例えば、著名人が命を落としたりですとか、子どもに関する事故、戦争などが起こったりしたときなど、児童・生徒の心に大きな影響を起こすおそれがあるというふうに認識しております。","voiceIndex":255,"id":"exchange-113"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"国は、４月以降、学校の授業などで、基本的にマスク着用を求めないとする通知を各地の教育委員会に出しました。先ほど、石田しんご委員の質問もありました。そういった意味でも、いまだマスクを外せない子ども、マスクを外していても、やはり常にポケットにマスクを隠しているというのですか、忍ばせている子ども、「どうして？そういった子どもたちの声をどう把握しているか、ご見解をお聞かせください。","respondent":"丸谷教育総合支援センター長","answer":"なかなか子どもたちとの対話もできなかった３年間ではありましたので、今後は保護者や子どもたちの意見を取り入れながら、学校教育を進められるというふうに考えております。","voiceIndex":257,"id":"exchange-114"},{"speaker":"まつざわ委員","kind":"質問","question":"ぜひ子どもたちの、一般質問でもさせていただきました。今はそういう声も聞いているという答弁がありましたけれども、やはり何回も聞いていいと思うのです。いじめや不登校、特別な配慮を要する子どもたちの支援と学校が抱える課題も山積みである今、全ての子どもたちが笑顔で元気にたくましく自分の人生を歩んでいけるため、改めまして、教育委員会が考えることとは何でしょうか、お示しください。","respondent":"丸谷教育総合支援センター長","answer":"そのためには、我々大人、教員も、より柔軟な考え方を持つなど、児童・生徒の見本になることが大切だと考えます。教育委員会として、不易を大切にしながら、流行にも柔軟に対応できるよう、市民科等の学習活動の中で実践できればというふうに考えております。","voiceIndex":259,"id":"exchange-115"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"いろいろな話の中でも、１つの手だてとして、私からは、ポジティブ教育というものを少しご紹介したいと思っています。これは福井県がやられています。ソーシャルスキルの教育、ピアサポート活動、レジリエンス教育、大体この３つを柱にして福井県ではやっています。ぜひ品川教育ルネサンスの中にも、このポジティブ教育を推進していただきたいと思いますが、ご見解をお願いします。","respondent":"中谷指導課長","answer":"お話しいただいた、例えば大変なことに直面したときに、自分なりの乗り越え方を養っていくことですとか、周囲との関係性を尊重しながら、よりよい人間関係を自分らしく構築する方法ですとか、こういったことをしっかりやっていくということは。","voiceIndex":261,"id":"exchange-116"},{"speaker":"木村委員","kind":"質問・要望","question":"自席から、また座ったままですみません。私からは、３７３ページの教職員福利厚生費から、教職員健康管理費および安全衛生管理費、また、ＰＴＡ関係費から、ＰＴＡ活動支援、家庭教育学級、家庭教育力向上支援についてお伺いいたします。教職員健康管理費および安全衛生管理費について伺います。それぞれの事業の概要について教えていただきたいと思います。","respondent":"宮尾庶務課長","answer":"教職員健康管理費についてです。こちらは、教職員の健康の保持、それから、ひいては学校教育の円滑な実施、その成果の確保を図る、こういったことを目的といたしまして、健康診断、それからストレスチェックなどを行ったものです。","voiceIndex":264,"id":"exchange-117"},{"speaker":"木村委員","kind":"質問・要望","question":"そのことを考えますと、これからも教職員の皆様には、大事に見守っていただきたいが、子どもたちに対してのお考え、何かアイデアがあればお聞かせいただきたいと思います。","respondent":"宮尾庶務課長","answer":"そういった先生方の、まず健康面、これが何を置いても第一かと思いますので、こういった健康診断ですとか、様々な福利厚生の対策、こういったことも充実させていって、先生方をこのような側面から支えて支援してまいりたいというふうに思っております。","voiceIndex":266,"id":"exchange-118"},{"speaker":"木村委員","kind":"質問・要望","question":"今言われた教職員の皆さんの健康を守るためにも、健康診断の受診状況と、ストレスチェックの概要、実施状況についても教えていただきたいと思います。","respondent":"宮尾庶務課長","answer":"健康診断の受診率につきましては、令和４年度は９９.９％、令和３年度から令和元年度は、それぞれ受診率は１００％となっています。次に、ストレスチェックについてです。こちらは法に基づいて実施をするものです。","voiceIndex":268,"id":"exchange-119"},{"speaker":"木村委員","kind":"意見","question":"先生のストレスは大変なものであろうと考えていますけれども、日々、子どもたちと接していることが原因で、先生方にストレスがたまると考えてもいいということでしょう。そのストレスにより、どのような症状があらわれ、子どもたちにはどのような影響を与えているのか、与えているというのは失礼かもしれませんが、あるのか。そういうことがあればお聞かせください。","respondent":"宮尾庶務課長","answer":"面接というのは、本人のご希望により、産業医と対面形式に加えまして、オンライン形式でも対応できるようにということで選択肢を拡充しています。","voiceIndex":270,"id":"exchange-120"},{"speaker":"木村委員","kind":"質問・要望","question":"先生方のストレスが子どもたちに与える影響は大きいと思いますけれども、十二分にまたチェックをしていただきたいと思います。健康診断の受診率が高い数値になっておりますけれども、何か工夫をされたようなことはあるのでしょうか。これがあれば、お聞かせいただきたいと思います。","respondent":"宮尾庶務課長","answer":"健康診断の受診率につきましては、対象者となっている先生方が受診しやすいように、まず実施時期を学校の夏季休業期間を中心に設定しております。複数の受診場所、受診機会を設定しているということ。","voiceIndex":272,"id":"exchange-121"},{"speaker":"木村委員","kind":"質問・要望","question":"昨今、働き方の健康管理については、より一層の強化が求められていると思います。教育委員会で取り組んでいることがあれば、これからストレス、教職員の方々に対して、何か取り組んでいることがあればお聞かせいただきたいと思います。","respondent":"宮尾庶務課長","answer":"教育委員会では、令和４年、昨年の４月から、長時間労働による健康リスクの高い教職員の方々を、より確実に把握をするために、時間外労働時間数を適切に把握をいたしまして、それを基に校長への情報提供を行っております。","voiceIndex":274,"id":"exchange-122"},{"speaker":"木村委員","kind":"質問・要望","question":"引き続き、教職員の健康維持に努めていただきたいと思います。引き続き、ＰＴＡ関係費から、ＰＴＡ活動支援、家庭教育学級、家庭教育力向上支援についてお聞きいたします。それぞれの事業の概要について、簡単にご説明を願います。","respondent":"宮尾庶務課長","answer":"ＰＴＡの活動支援についてですが、こちらは、ＰＴＡ活動の活性化を図るということを目的といたしまして、研修会、研究発表会、こういった事業をＰＴＡの連合会に委託をして実施をしているものです。","voiceIndex":276,"id":"exchange-123"},{"speaker":"木村委員","kind":"質問・要望","question":"時間がありませんので、ぜひとも未来の大人たちのために、皆さんの力を十二分に発揮できるように頑張っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":278,"id":"exchange-124"},{"speaker":"西本委員","kind":"質問・要望","question":"３７９ページのいじめ防止対策費についてお伺いします。非常に私は疑問があるところが、要は、被害者の親御さん、それから生徒からの要望であった加害者の特定はできていないのですよね。要望はここだったと思うのです。でも、もともと重大事態ではないのかということの疑問を呈した被害者側の要望には、今回、達成されなかったのですよね。教育委員会ですか、区長部局ですか、お答えください。","respondent":"勝亦総務課長","answer":"区長部局におきますいじめ調査委員会の結論につきましては、調査結果がまとまりました段階で、事務局立会いの下、委員長より保護者の方に概要を説明した上で、最終的に報告書をまとめてあります。","voiceIndex":280,"id":"exchange-125"},{"speaker":"西本委員","kind":"質問","question":"ですから、納得されたのですかということです。どうですか。","respondent":"勝亦総務課長","answer":"こちらの内容につきましては、内容、それから公表につきましても、ご了解をいただいております。ただ、今、委員がおっしゃったように、最終的に加害者が見つけられなかったこと、そういった解決ができなかったことについては残念だというコメントはいただいております。","voiceIndex":282,"id":"exchange-126"},{"speaker":"西本委員","kind":"質問","question":"そうなのです。私、親だったら、この結果は納得しませんよ。だって、そうでしょう。自分の子どもが学校に行けなくなってしまった、パニック障害になってしまった、どうしてくれるのだというのは当たり前ではないですか。なので、私は、今のご答弁、本当かなという、もっと深いところで納得いっていないところがあるのではないかというふうに思っております。どういう役割分担をされるつもりですか。","respondent":"丸谷教育総合支援センター長、勝亦総務課長","answer":"品川区いじめ対策委員会の役割ですけれども、区の教育委員会のいじめ対策の施策の推進に当たるための会議体です。重大事態が発生したときに、調査、報告に当たる機関というふうになっております。区長部局のいじめ調査委員会のほうですけれども、こちらはいじめ防止対策推進法で定めております教育委員会の調査に当たりまして、重大事態への対処、それから重大事態と同様の発生を今後防止するために必要があると認めるときは。","voiceIndex":284,"id":"exchange-127"},{"speaker":"西本委員","kind":"質問","question":"今の状況では全然分かりません。なぜこの２つの機関があるのですか。法律は分かります。いじめがあった。だから、学校現場では、いじめ対策委員会が開かれて調査するではないですか。それで、そこで問題があって、その報告を区長に話をして、区長が、これは重大事態だという認識があったときに調査委員会を設置するのは分かります。だけど、今回、常設するのですよ。なぜ常設するのですか。","respondent":"勝亦総務課長","answer":"いじめの調査委員会につきましては、もともとこの法律に基づいて必要なときに開催できるように条例を定めてあります。常設で委員会を設けるという趣旨での補正予算の要求ではございません。","voiceIndex":287,"id":"exchange-128"},{"speaker":"西本委員","kind":"質問","question":"そうですか。私はそうとっていませんでしたけれども。それで、９月１３日の区長記者会見で資料が出ておりました。その中で、調査委員会を設置する目的があります。それから、いじめ情報収集促進チラシの配布、積極的な情報収集と早期発見、これ、ＨＥＡＲＴＳとか教育委員会とかでやっていることではないのですか。これ、なぜ区長部局のいじめ調査委員会がやることなのでしょうか。それをお答えください。","respondent":"勝亦総務課長","answer":"実際に学校現場に入って、学校の状況ですとか、いじめを受けている方、そういった現場に入って支援を行う、そういったものを第三者的に客観的に行っていくというための機関です。","voiceIndex":289,"id":"exchange-129"},{"speaker":"西本委員","kind":"質問","question":"間口を広げる。でも、教育に関することは教育委員会の窓口ではないのですか。一本でやるべきでしょう。だったら、教育委員会の中で不足があるのだったら、そこにしっかりそれができるように付加する必要があるのではないですか。充実させるという形に、私は税金を使ってもらいたいと思うし、子どもたち、それから親たちも、そのほうが迷わずに相談ができるのではないでしょうか。いかがでしょうか。","respondent":"勝亦総務課長、丸谷教育総合支援センター長","answer":"やはり学校には訴えにくいなというようなお声もあるということで、より広く、そして地域の方、いじめを受けている方以外にも、いじめを見た方。ご指摘いただきました教育委員会内部の支援につきましても充実させるように、次年度に向けて計画を進めているところです。","voiceIndex":291,"id":"exchange-130"},{"speaker":"西本委員","kind":"質問","question":"教育は教育委員会が主体であるべきだと思います。そこを中心に進めていくべきでしょう。それがなぜ区長部局が出てくるのですか。私はそれは分かりません。それがあちこちあちこちで分散してしまったら、解決の糸口が見つからないですよ。なので、教育委員会でもっと自信を持って、いじめ対策に対してはしっかりやっていくということを意思表示をしてください。","respondent":"丸谷教育総合支援センター長","answer":"教育委員会で行えること、教育的なアプローチは、我々得意とするところですけれども、我々だけではなし得ない行政的なアプローチも必要だというふうに考えまして、連携を進めていきたいと思います。","voiceIndex":294,"id":"exchange-131"},{"speaker":"若林委員","kind":"質問・要望","question":"さらには、同じ関連になりますか、首長との連携の強化という、ほかにもありますけれども、主にこういった改革が、法の一部改正によって求められたところです。そこで、今月１１日には、初めて公募されました教育委員がご就任されまして、そういったことも含めて、少し確認をさせていただきたいと思います。教育委員会の方は５人いらっしゃいます。","respondent":"宮尾庶務課長","answer":"教育委員会の体制ですが、委員お話のとおり、教育長を筆頭に、４人から成る教育委員から成り立っているところです。それを我々、教育委員会事務局として、日々教育委員会で決まったことなどを実際に実務として我々が行うです。","voiceIndex":298,"id":"exchange-132"},{"speaker":"若林委員","kind":"質問・要望","question":"地行法でも、第２１条ですか、教育委員会の職務権限というところで、１から１９まで大変たくさんな権限があります。教育委員会の視察ですので、５名の教育委員が中心になると思いますけれども、ここに区長部局からの方が一緒に参加するということは可能なのかどうか、こういったところも教えていただきたいと思います。それから、すみません、順番が。","respondent":"宮尾庶務課長、森学校施設担当課長","answer":"区長部局の職員ですけれども、これまでの実績としてはございませんが、相談なり、お声があれば、どういったことができるかというところは検討の余地はあるかなというふうに思っております。基本的に第２校庭はあまり使っておりませんので、今は使用停止にしておりますけれども、それにつきましても、今週中に土をさらってきれいにするという作業を行う予定で、事故等がないように、発見次第、即対応するようにしております。","voiceIndex":300,"id":"exchange-133"},{"speaker":"若林委員","kind":"質問・要望","question":"校庭の釘等においては、今初めて公表されたということで、しっかりと文教委員会等、タイミングもあったかもしれませんけれども、ご報告をしっかりよろしくお願いしたいと思います。大変な作業なのですが、ぜひ教育委員会におかれましても、報告書を作成して、区民、議会と、ぜひ成果を共有させていただきたい。区長部局との連携という意味では、そういった観点でも進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":303,"id":"exchange-134"},{"speaker":"高橋（し）委員","kind":"質問","question":"よろしくお願いします。それから、３８１ページの市民科になるのでしょうか、性教育ですが、先ほど課長から実施したという１校の例がありましたけれども、東京都のほうで性教育に関する講師の補助があると伺っています。品川区では、どのように登校についてお考えでしょうか。これはモデルで５校で、今年１５校、まず来年度、どのような計画でしょうか。その一方で、これは財政のほうになるのでしょうか。","respondent":"丸谷教育総合支援センター長、唐澤特別支援教育担当課長","answer":"令和６年度の都立高校の入試の男女枠の撤廃についての対応ですけれども、先日、東京都の説明会がございまして、進路指導主任会でも区教委から説明を行ったところです。最後に、特別支援教室の１年原則ですけれども、原則１年というところで、また在籍学級での様子を見るという形はありますけれども、必要があれば延長、また、２年目以降のところも校内委員会を踏まえ。","voiceIndex":305,"id":"exchange-135"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"そういった点についても、中学校のほうで、いわゆる中学の進学指導のときに１つ１つ提示していただけるのでしょうか。そうすると、来年度は、今年１５ですから、相当数増やす予定ではないかと思います。これは東京都の関係があるから、なかなか難しいのかもしれませんが、品川区としては、令和６年度に向けて、どのような構想を考えていらっしゃるでしょうか。","respondent":"丸谷教育総合支援センター長、唐澤特別支援教育担当課長","answer":"そうしたことも踏まえまして、進路指導、都立校にするのか、私立校にするのか、そういったことを丁寧に説明と指導をしていくです。発達障害教育支援員について、令和６年度以降という形かと思いますけれども、まず、令和４年度５校は会計年度任用職員、令和５年度１０校は派遣というような形で実施しております。","voiceIndex":308,"id":"exchange-136"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"特別支援の発達障害教育支援員のところで、１つだけ、先ほど、学習支援員や介助員の予算立ては減らさないでいただきたいというふうにお話ししたのですが、その点についてはいかがでしょうか。","respondent":"唐澤特別支援教育担当課長、丸谷教育総合支援センター長","answer":"発達障害教育支援員、学習支援員、介助員を含めまして、その在り方、対象となる児童・生徒もおりますので、そうしたものも整理しながら次年度に向けて検討していきたいと思います。学区域内で不審者情報があった際には、各校それぞれ、学校からそれぞれの学校、全校に周知するように現在行っているところです。","voiceIndex":311,"id":"exchange-137"},{"speaker":"澤田委員","kind":"質問・要望","question":"３９９ページ、第四日野小学校校舎等改築工事、３８５ページ、特別支援学級等運営費、３７９ページ、いじめ防止対策費、３７５ページ、学校給食費、学用品給与費について、順不同でお伺いいたします。３９９ページ、第四日野小学校校舎等改築工事についてお伺いします。区として、この取組について、どのようにお考えでしょうか、お聞かせください。","respondent":"森学校施設担当課長","answer":"児童・生徒が参加できるような、例えば、芽継ぎや継木等、そういうことであったりとか、スクールカラーを決めていただいたり、何かできるような、参加していただけるようなことを様々検討していきながら、区とともに、児童・生徒とともに。","voiceIndex":315,"id":"exchange-138"},{"speaker":"澤田委員","kind":"質問・要望","question":"続きまして、３７５ページ、学校給食費、学用品給与費についてお伺いいたします。給食費の無償化についてお聞きします。私たち会派、そして他の会派からも要望がありました都立特別支援学校への給食費分補助を早急に実現いただき、大変ありがたく思います。そして、国立、私立の特別支援学校のお子さんへも給食費補助を拡充していただきたいのですが、ご見解をお伺いします。","respondent":"柏木学務課長","answer":"教育委員会といたしましては、いただいた内容を踏まえて、国立、私立の特別支援学校の給食費補助について検討をしてまいります。","voiceIndex":317,"id":"exchange-139"},{"speaker":"澤田委員","kind":"質問・要望","question":"先ほど、こんの委員からも質問がありましたが、品川区では、就学支援の一環として、学用品費の援助を行っていますけれども、その助成対象に含まれない世帯の方たちからも、学用品の助成を望む声もお聞きしております。子どもに障害があってもなくても、全ての子どもたちが等しく教育を受けられるように、その助成対象の枠を広げることを要望いたしますが、区としてのご見解をお伺いいたします。","respondent":"柏木学務課長","answer":"先ほどの答弁と繰り返しになる部分はありますが、保護者の負担の軽減については必要であると考えていますので、今後、保護者負担軽減を図る策について検討してまいります。","voiceIndex":319,"id":"exchange-140"},{"speaker":"澤田委員","kind":"質問","question":"ぜひよろしくお願いいたします。続きまして、第２回定例会の一般質問でも、いじめ予防について質問をさせていただきました。今回は、３７９ページ、いじめ防止対策費についてお伺いいたします。そこでお伺いしたいのは、今年度、いじめ防止プログラムの一環として新たに行われた取組などがありましたら、お聞かせください。","respondent":"丸谷教育総合支援センター長","answer":"今年度に入りまして、まず、教育委員会内部の認識を改めるということを行いました。学校へのしっかりとした法に基づいたいじめの認知ができるようにということで、研修会を行っております。","voiceIndex":321,"id":"exchange-141"},{"speaker":"澤田委員","kind":"質問・要望","question":"子どもたちみんなが安心して笑顔で学校生活を送れるように、品川区で子育てをする保護者の方々が不安を抱くことなく子どもたちを送り出せるように、引き続き、いじめを防ぐための子どもたちに向けた予防プログラムの検討を心より要望いたします。","respondent":"丸谷教育総合支援センター長","answer":"教員研修についてですけれども、全教員がいじめについて知るということが大切だというふうに考えまして、９月６日には、品川教育の日として、「いじめに関する事実と具体的な対応」ということで、子どもの発達科学研究所の和久田主席研究員をお招きして研修会を行いました。","voiceIndex":323,"id":"exchange-142"},{"speaker":"澤田委員","kind":"質問","question":"ぜひ推し進めていただければと思います。続きまして、３８５ページ、特別支援学級等運営費についてです。そこでお伺いしたいのは、発達に特性を持つ児童たちの通常学級での支援についてです。これらの質問については、多くの委員の方が質問されていましたけれども、私からも質問します。小学校では、現在、１クラスに３５人が在籍しています。","respondent":"唐澤特別支援教育担当課長","answer":"人材の確保につきましては、委託である学習支援員、介助員につきましては、特定非営利法人ピアサポートに委託し、人材の確保に努めているところです。","voiceIndex":325,"id":"exchange-143"},{"speaker":"澤田委員","kind":"質問","question":"令和４年度のモデル校５校に加え、令和５年度はさらに拡充していらっしゃいますけれども、各学校に発達障害教育支援員は何名配置されているのでしょうか。","respondent":"唐澤特別支援教育担当課長","answer":"発達障害教育支援員の配置の状況につきましては、毎日１人７時間程度配置されています。その内訳につきましては、２名程度でその５日を分けて、各日、１日いるというような形で実施しております。","voiceIndex":327,"id":"exchange-144"},{"speaker":"澤田委員","kind":"質問・要望","question":"人材の確保や予算の確保など、大変難しい部分もあるとは思いますが、未来を担う子どもたちのためにも、まずはモデル校だけでなく、発達障害教育支援員の全校への配置を強く要望するとともに、可能であれば、今２名を交代で毎日１人が必ず入るようにということですけれども、１人では足りないのではないかなということがありまして、ぜひ毎日２名以上配置されることを望んでおりますけれども。","respondent":"唐澤特別支援教育担当課長","answer":"現在、１５校、モデル実施しておるところですが、まずは今、小学校（前期）課程に１５校配置しておりますが、全ての小学校（前期）課程の配置を目指して、成果を振り返りながら拡充について努めていければと考えています。","voiceIndex":329,"id":"exchange-145"},{"speaker":"澤田委員","kind":"質問・要望","question":"介助員や学習支援員の人材確保につきましては、区のホームページで募集しておりますけれども、それ以外にも様々行われている区のイベントなどでチラシを配布したり、ＳＮＳを活用するなどして、子育てを終え、時間にゆとりのある世代の方たちや、大学との連携により教員免許を取得しようとしている大学生に向けて、積極的にアピールしたりして募集することにより。","respondent":"唐澤特別支援教育担当課長","answer":"発達障害教育支援員の拡充を含めまして、介助員、学習支援員、または医療的ケアが必要な看護師の配置なども実施しておりますので、そうした配置については今後も努めていきたいと考えております。","voiceIndex":331,"id":"exchange-146"},{"speaker":"松本委員","kind":"質問・要望","question":"よろしくお願いします。本日は、３７９ページ、いじめ防止対策費、３７５ページ、少し時間が間に合わないかもしれませんが、プール指導員経費について伺います。なので、ここは今日はあくまで事実確認で、総括質疑のほうでまたやらせていただきたいと思いますけれども、そこの部分、誰が権限を持って判断していくのかというところは考えていかないといけないと思っています。","respondent":"丸谷教育総合支援センター長","answer":"今のお話ですけれども、発生時の報告が起案が漏れていて報告できていなかった。そのまま調査に入っていったということでございまして、調査結果がまとまってから、令和５年４月２５日付で書面にて教育長から区長へ報告をしたです。","voiceIndex":335,"id":"exchange-147"},{"speaker":"松本委員","kind":"質問","question":"分かりました。続いて、今回は３月の答申と８月の答申、２つあるわけですけれども、この３月付の教育委員会が諮問されたほうの答申でも、これは再発防止策として、研修の必要性が挙げられている。この３月の答申から半年ぐらいたっているわけですけれども、どのような研修が行われたのか、いつの時点で行われたのか、そして教育委員会を対象とした研修も行われているのか伺います。","respondent":"丸谷教育総合支援センター長","answer":"３月の答申を受けまして、まずは管理職向けの研修を行っております。生活指導主任会での研修ということで、いずれも６月に行っているものです。９月には、全教職員、管理職を含めた教員を対象に、１,０００人を超える教員向けに研修を行っているものです。","voiceIndex":337,"id":"exchange-148"},{"speaker":"松本委員","kind":"確認","question":"当区においてすごく大事ではないかと思いますのが、今回の８月の答申のほうですけれども、まず、確認をしておかないといけないのですが、答申のほうで、この重大事態の発生のタイミングは、遅くとも令和２年６月５日、それまで健康であった被害生徒が、教室で意識を失い倒れ、緊急搬送されたというふうな、この時点だというふうに述べられているのですけれども、これ、教育委員会、現在の認識として。","respondent":"丸谷教育総合支援センター長","answer":"今回の事案については、適応障害と診断された時点、もしくは頻繁に倒れた時点というようなことで認識はしています。","voiceIndex":339,"id":"exchange-149"},{"speaker":"松本委員","kind":"確認","question":"その後、７月２０何日か、３０日ですか、７月の終わりの時点まで全部で合計で３回、救急車で運ばれているのです。この２か月弱の認定がきちんとできるかどうかというのは極めて大事だと考えています。その中で、先ほど、６月にも研修を行って、さらに教育委員会の中で法の確認もしたというふうなお話がありました。でも、やはり法の確認をしても、重大事態かどうかということは認定できないと思っています。","respondent":"丸谷教育総合支援センター長","answer":"基本方針の中にフローチャートを入れるというようなことも含めまして、今後、適切に認定ができるような対応、対策をとってまいりたいというふうに考えております。","voiceIndex":341,"id":"exchange-150"},{"speaker":"松本委員","kind":"質問","question":"フローは認定の基準にはならないと思います。今の時点でも、いじめが発生する可能性があって、基準を明確に答えられないというのは、対応ができないというふうに考えられる可能性もありますので、そこはまた総括質疑で伺いたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":343,"id":"exchange-151"},{"speaker":"須貝委員","kind":"質問","question":"３７６ページ、教育指導費についてお伺いしたいと思います。今現在、先生のなり手が少ない。先生の離職率が高まっている。教員不足によって１人１人の負担が増えることで、子どものコミュニケーションや授業準備といった本来時間を割くべき業務に使える時間が減ります。ここでお聞きします。品川区の公立小・中学校、状況はどうなのでしょうか。品川区の状況を教えてください。","respondent":"中谷指導課長","answer":"教育委員会といたしましては、やはり教員が欠員になってしまうところは直ちに手当てをしなければいけないというふうに捉えておりますので、先ほどもございましたけれども、やはり学校と密な連携をとりながら、しっかり情報交換をしながら、何が今緊急で。","voiceIndex":345,"id":"exchange-152"},{"speaker":"須貝委員","kind":"確認","question":"いじめ撲滅、そういうことをやったり、それから、いじめ根絶宣言、これ、各学校に掲げているではないですか。相当前です。それで、いろいろな方が、不登校はどうなっているのだ、いじめはどうなっているのだと何度も聞いているわけではないですか。そこにこのようなことを出されたら、では、我々は何のためにいるのですか。何のために予算特別委員会、決算特別委員会で皆さんとお話ししているのですか。","respondent":"丸谷教育総合支援センター長","answer":"いじめの認知の力が不足しているのではないかということもうたわれておりまして、何か問題が、子どもたち同士でトラブルが発生したときには、必ず教員が対応しているわけですけれども、それを改めていじめの法律に基づいて認知をしたかどうかと言われると。","voiceIndex":347,"id":"exchange-153"},{"speaker":"須貝委員","kind":"質問・要望","question":"だって、一生懸命やっている、私らは分かる。それは事実です。それで、先ほど、先生が足りないと、そんなに足りなくありませんとおっしゃっていましたけれども、現に教室に出ていない先生のカウントまで入れたら、もっと多いのではないですか。そういうことを考えると、やはり品川区は私は心配だな、これは品川区だけではなくて全国もそうですが、その辺について、どのように品川区ではお考えでしょうか。","respondent":"丸谷教育総合支援センター長、中谷指導課長","answer":"各学校が法に基づいたいじめの認知、それから、早期対応ということで進められるように、いじめの予防教育も含めまして、今、検討と申しますか、準備を進めているところです。教員のメンタルヘルスに関することですけれども、文部科学省のガイドラインで定められていることとしては、１か月当たりの時間外在校時間数、４５時間を超えていくと疾患と業務の関連性が強まるというふうにされておりますので。","voiceIndex":349,"id":"exchange-154"},{"speaker":"須貝委員","kind":"質問","question":"そこでさらに私が問題視しているのは、品川区内の公立小・中学校の教員なのですが、これ、東京都教育委員会で採用し、品川区に配分されていくのですよね。現に、今日までずっとここ１０年間、いじめ、不登校、公立学校離れ、増加している中で、様々な対応をされてきた。だけど、現実に止まらない。これはおかしくないですか。このようなことをやっていていいのでしょうか。ご見解をお聞かせください。","respondent":"中谷指導課長","answer":"東京都の教職員、こちらが多いわけですけれども、この方々には、やはり他地区で経験しているそれぞれの強みを生かして品川で尽力していただくという、こういう２層でやっていきたいというふうに思っております。","voiceIndex":352,"id":"exchange-155"},{"speaker":"須貝委員","kind":"質問・要望","question":"自分のところの教員は自分のところで採用して、面接も全部自分のところできちんとやって、そういう方を、責任を持った職員を、教員を配置させなければいけないのではないでしょうか。そういう気概を持ってほしいと思います。これは私は立派なことだと思いますので、できるなら、そういうふうにやっていっていただきたいと思います。家賃だって、品川区に住めば９万円もするのです。１人で１００万円。","respondent":"中谷指導課長","answer":"若手教員の労働改善というところですけれども、まず、こちらにつきましては、関係課と連携しながら検討を考えていきたいと思っています。若手教員の方がやはり増えているという現状があります。","voiceIndex":354,"id":"exchange-156"},{"speaker":"須貝委員","kind":"質問","question":"東京都から配置されている教員ですけれども、３年たったら品川区を出ていっていいのです。希望を出せば。長くても５年から７年。何にもならない。このようなやり方をいつまでも繰り返していては駄目ではないですか。いい人を採用する、そして育てる、そういう姿勢にならないと、いつまでたっても、教員もそうですけれども、職員も集まらない、このような区でいいのでしょうか、財政、企画課、企画部長。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":356,"id":"exchange-157"},{"speaker":"鈴木委員","kind":"質問・要望","question":"私からは、３７６ページ、教育指導費から、教員の働き方改革について、それから、包括的性教育について伺いたいと思います。だから、国に求めていくという、そのことを自民党、公明党にもぜひお願いしたいなと思います。でも、過酷な実態は改善されていません。病休をとられている方の人数は、小学校、中学校２１名ということですけれども、それぞれ何人なのかも伺いたいと思います。","respondent":"中谷指導課長","answer":"加配ということで、今年度より新規に開始されました産・育休代替の教員の前倒し任用、加配という形が最大４か月前からできる制度ですけれども、これまでに１５名が実績として活用されているというような状況です。","voiceIndex":360,"id":"exchange-158"},{"speaker":"鈴木委員","kind":"質問","question":"超過勤務なのですけれども、これ、１時間当たりということではなくて、１か月当たりということで出していただけると、これに何日を掛ければいいということなのか、それが何日なのか、１か月当たりで時間数を教えていただけたら、イメージが、４５時間を超えているのか、そこら辺のところも分かりますので、１か月当たりということでお聞きしたので、それでお願いしたいと思います。","respondent":"中谷指導課長","answer":"こちらに対する対策ですけれども、まず、４５時間を超えた教員に個別に丁寧に対応していくことや、必要に応じて産業医の面談、また、組織全体として超過勤務を行う教員を減少させることができるような手だてを考案、実施していただくようお願いしています。","voiceIndex":362,"id":"exchange-159"},{"speaker":"鈴木委員","kind":"質問・要望","question":"超過勤務も一定落ち着いているところでも５４時間ということで、本当に深刻な実態がここに表れていると思います。これは区としてできることとして、これからも充実をしていただきたいと思います。この残業代が払われない制度を廃止して、残業代を支給できる仕組みに変えることが必要ではないかと思いますけれども、区の見解を伺いたいと思います。","respondent":"中谷指導課長","answer":"給特法の改正につきましては、国の通知を待っていきたいというふうに思っているところです。こちらを踏まえて、変更が生じた場合には適切に対応してまいりたいと思います。","voiceIndex":364,"id":"exchange-160"},{"speaker":"鈴木委員","kind":"質問・要望","question":"やはりこれは大きな問題の１つだと思うのです。それなので、区としても、給特法の抜本改善、残業代不支給の制度の廃止、それから教員の増員、これを求めていただくことを要望しておきたいと思います。それから、包括的性教育について伺いたいと思います。それを担うのが性教育だと、こういうふうに言っているのですけれども、区教委もこの立場に立つべきだと思うのですが、いかがでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"性に関する教育につきましては、国の学習指導要領で定められた立ち位置で区立学校においても指導しています。生命の安全教育につきましても、国が出している方針に従って、発達段階に応じた指導をしています。","voiceIndex":366,"id":"exchange-161"},{"speaker":"鈴木委員","kind":"質問・要望","question":"この歯止め規定の内容についても、文科省では、各学校で必要であると判断すれば指導することができるとなっているのです。それなので、ぜひ私は、この外部指導の講師の活用を広げていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":368,"id":"exchange-162"},{"speaker":"吉田委員","kind":"質問","question":"私からは、３７３ページ、ＰＴＡ関係費と、３８７ページ、図書館運営費から伺います。最初に、図書館運営費について伺います。お話を伺う中で、品川図書館の４階に行けば、そういうお部屋があって、たくさんありますよということを教えていただいたので訪ねたところ、本当にたくさんの絵本があって、私、針仕事とかがすごく苦手なので、感動いたしました。","respondent":"吉田品川図書館長","answer":"活動自体は、品川区にあるボランティア団体「むつき会」が、昭和４５年辺りから、品川図書館と大崎図書館を拠点に活動なさっているところです。","voiceIndex":370,"id":"exchange-163"},{"speaker":"吉田委員","kind":"質問・要望","question":"貸出しを全国に向けてしておられるということで、その実績など、１年間のことがあったら教えていただきたいと思います。単価の４,０００円なのですけれども、これ、材料費なのでしょうか、製作費も込みなのでしょうか。はっきり言って、これで事業継続に十分なのでしょうか。さっきも言いましたけれども、私は針仕事がとても苦手なので、すばらしいお仕事だと思うのですが、これで十分なのでしょうか。","respondent":"吉田品川図書館長","answer":"貸出先としましては、自治体間の図書館同士のやり取りが、相互貸出しという制度がありまして、この制度によって、ほかの自治体から要求といいますか、貸してほしいというものがあったものについて対応しています。","voiceIndex":372,"id":"exchange-164"},{"speaker":"吉田委員","kind":"質問・要望","question":"それで、さっきの４,０００円というのは十分なのでしょうかということも、お答えになりにくいかもしれません。ぜひ費用の面でも、必要なものであったら支援をしていただきたいと思います。品川図書館の事業として継続を求めたいのですが、その点についても見解を伺いたいと思います。ＰＴＡと学校の関係について、原則的な在り方について確認をさせていただきたいと思います。この点について見解を伺います。","respondent":"吉田品川図書館長、宮尾庶務課長","answer":"２点ご質問いただきました。支援については、４,０００円の費用感のところですが、こちらにつきましては、ほかの例えばデイジー図書作成の委託だとか、この辺とのバランスも兼ね合いまして定まっているものと考えているところです。会員の総意に基づいて自主的に運営される団体ですので、加入に関しては、あくまでも任意でございまして、会員になれば、誰もがご自身の意思で活動に参加ができるものというふうに認識をしております。","voiceIndex":374,"id":"exchange-165"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひ継続していっていただきたいのと、さわる絵本については、十分な支援の上、継続していただきたいと思います。それから、ＰＴＡのほうです。分かりました。今のご答弁を伺うと、その考えでよいですねということと、それからもう１つ、ＰＴＡ会費の徴収について、学校との関わりなどルールがあるようなのですが、そのルールについては、どのようになっているか伺いたいと思います。","respondent":"宮尾庶務課長","answer":"ＰＴＡに加入するかどうかというところですけれども、こちらは任意ですので、強制等をするべき性格のものではないというふうに認識をしています。","voiceIndex":377,"id":"exchange-166"},{"speaker":"吉田委員","kind":"質問","question":"それはそれで、きちんとＰＴＡと学校同士でそういう取決めがあってという、一応独立した団体であれば、簡単であっても、お互いこういう取決めをして、ここの部分については学校が担いますみたいなお約束が、別団体というのであれば、あってしかるべきかなと思ったのですけれども、今のところ、当然のように学校が代わりに徴収しているのではないのかというようなことを伺ったのですけれども。","respondent":"宮尾庶務課長","answer":"特に教育委員会のほうから、会費の徴収方法についての細かな方法等について、何か考えというようなものをお示しをしたということはございませんけれども、もしそういう会費の徴収に当たって、保護者の方が何か疑義をお感じになるようなことがあれば。","voiceIndex":379,"id":"exchange-167"},{"speaker":"吉田委員","kind":"質問・要望","question":"分かりました。さっきも言いましたけれども、大変行動的な方なので、少し疑問に思ったら、きちんと直接おっしゃるでしょうし、こちらにもまたご相談が来ると思います。その点については配慮していただきたいと思いますが、その点については大丈夫というふうにお返事をしてもよいですねということを最後に確認させてください。","respondent":"宮尾庶務課長","answer":"時代の変化、移りようとともに、ＰＴＡ活動のありようというものも柔軟に変えるべきところは変える、しっかりと守っていくところは守っていく、このような考え方で学校とＰＴＡの皆様とが、よりよい関係づくりができるように。","voiceIndex":381,"id":"exchange-168"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私からは、３９９ページ、学校施設建設費、城南第二小学校改築実施設計委託について伺います。先月、９月に地元の方と交通指導員の方からご相談をいただいて、私も朝７時半に現地に伺って、登校の様子を拝見いたしました。スクールゾーン設置の要望は、通常、教育委員会は関与しないで、学校側が直接警察へ相談をするのか、その手順を教えてください。","respondent":"森学校施設担当課長","answer":"もし安全が脅かされるようなことがあれば、学校と教育委員会で連携をとりまして、安全性を高めるために、各関係機関に働きかけをしていきたいと、そのように考えてあります。","voiceIndex":384,"id":"exchange-169"},{"speaker":"あくつ委員","kind":"質問・要望","question":"やはりこれは教育委員会でないと、やはりそういう知恵とか工夫とか、知識というか、情報もないでしょうから、そこのところがやはり必要なのかなと思います。何よりも子どもたちの安全を守るために、保護者、そして学校側の不安に応えるためにも、やはり品川区教育委員会が主導して、警察への働きかけや庁舎横断的な安全対策の強化を行っていただきたいと思いますが、いかがでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"通学路の安全管理についてですけれども、こちらは教育総合支援センターでも定期的に確認をしております。現在の城南第二小学校の現状を見ながら、学校とも連携しながら、必要な関係各所とも連携をしながら、児童の安全確保に努めてまいります。","voiceIndex":386,"id":"exchange-170"},{"speaker":"あくつ委員","kind":"質問・要望","question":"今日、私が質問しましたのは、これはやはり議事録に残したかったのです。ここで聞きますが、学校改築については、教育委員会の庶務課学校施設整備担当が担っておられますが、改築を実際に行う事業者が、仮用地の用地取得を求めていますが、その理由をどうお考えか教えてくださいというのが１つ。これからは、そういう適正な工期とか予算を設定していただけるのかどうか、最初に質問したものと併せて伺います。","respondent":"森学校施設担当課長","answer":"今後もそういうことがないように、土日は休むことができるように、しっかり検討をしていきたい、そのように考えております。","voiceIndex":388,"id":"exchange-171"},{"speaker":"せりざわ委員","kind":"提案","question":"３８９ページ児童・生徒用タブレット端末等運用、それから、教育費全般から教育長の方針についてお伺いしたいと思います。タブレット端末からお伺いしたいと思います。それを受けて、私も２０２０年に本会議で、区の区立学校全体でタブレットを１人１台にできないのかというような提案をしました。自公政権でできました。","respondent":"丸谷教育総合支援センター長","answer":"そういったこともありまして、それぞれの学校の活用については、実践事例集のようなものも作成いたしまして、各校に広めてきたという経緯があります。今回、２０２１年にＧＩＧＡスクール構想の１人１台タブレット、全校に広がるその基礎となったというふうには認識しております。","voiceIndex":391,"id":"exchange-172"},{"speaker":"せりざわ委員","kind":"提案","question":"それの具体的な提案も続けてします。以前、姉妹都市、３つある中で、区長も行かれたオークランドが時差が非常に少なくて、例えばＺｏｏｍを使って英語でのディベートをしたらいかがですかとか、まもるっちを補完する形で、例えばヘルスケアウォッチみたいなものが、今は５,０００円を下回るぐらいで、どれぐらい眠っていますよとか、歩いていますよ、座り過ぎですよということを注意してくれたりします。","respondent":"丸谷教育総合支援センター長","answer":"毎年２校ずつ、２年計画で研究校というものを指定しておりまして、今年度も２校、ＩＣＴも活用しながら教育活動を進めていくということで研究を進めておりますので、そういった研究校については、また周辺の学校にも取組を広げられるような取組を進めていきます。","voiceIndex":393,"id":"exchange-173"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"例えば、読書感想文とか、ＣｈａｔＧＰＴであえて書いてもらって、それに対して、しっかり自分も本を読んで、このＣｈａｔＧＰＴの感想文は、ここがおかしいのではないかとか、僕はこう思うなどというような反論をできるような、もしくは自分でフェイクＡＩを作って、人を傷つけないような画像で、現実空間ではあり得ない画像を作ってみるとか。","respondent":"伊崎教育長","answer":"こういったものを土台としながら、未来を切り拓く力を持つ児童・生徒の育成を目指してこれまでも進めてきておりますが、これからも、よりいろいろな考え方や視点を持つ人の多様性ということ、そこをきちんと子どもたち一人一人が認識をしながら、また。","voiceIndex":395,"id":"exchange-174"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1542#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":122292,"voices":397}},{"id":"r05-20231019-4","meetingId":"r05-c-settlement","date":"2023年10月19日","dateIso":"2023-10-19","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時０７分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を101件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"せりざわ委員","kind":"質問・要望","question":"品川区議会自民党・無所属の会を代表して、せお麻里副委員長と共に総括質疑を行わせていただきます。私からは、ふるさと納税と品川区の広報戦略についてお伺いします。ふるさと納税の総論として、これまでの品川区での流出額・流入額の推移をご説明いただきたい。そして、これまで取り組んできた区の取組と、これまでやってきた中での課題感というのがあれば、まず教えていただきたいと思います。","respondent":"堀越総務部長","answer":"併せて、ガバメントクラウドファンディングの取組もさらに拡充していきたいということで、寄附の増加に努めていきたいと考えているところです。","voiceIndex":4,"id":"exchange-001"},{"speaker":"せりざわ委員","kind":"提案","question":"課題感は非常にあるということでお話を頂きました。一方で、マーケティングの視点、以前も提案させていただきましたが、例えば女性向け、男性向け、子ども向け、子育て世帯であったり、高齢者、高額納税者であったり外国人向けという視点というのは、まだまだ返礼品に足りていないと思いますので、そちらについては今後の展開をお聞かせいただきたいと思います。","respondent":"堀越総務部長","answer":"今、マーケティングの視点というお話を頂きましたけれども、より広く寄附を集めていくという観点からは難しい面もありますけれども、先ほど申し上げた企業などと様々な連携をする中で、企業のターゲット層といいますか。","voiceIndex":6,"id":"exchange-002"},{"speaker":"せりざわ委員","kind":"提案","question":"それをどんどん増やしていくことが、広く深く返礼品を提供できるということになるかと思いますので、ぜひここは、マーケティングの視点というのは忘れずに進めていただきたいと思います。昨年これも提案させていただきましたが、組織体制のところで、ふるさと納税については今、所管が税務課で、今回の決算特別委員会でもずっと税務課長にお答えいただいていたと思います。","respondent":"久保田企画部長","answer":"区における今後の執行体制についてですけれども、税の流出に歯止めがかからない状況が続いておりますので、私どもとしましても、しっかりと対応できる執行体制について検討していきたいと考えているところです。","voiceIndex":8,"id":"exchange-003"},{"speaker":"せりざわ委員","kind":"提案","question":"こちらのご見解をお聞かせいただきたいと思います。その対策として、先ほどマニアックなニーズの掘り起こしというお話もさせていただいたと思うのですが、例えば民間サービスでよくあるような、家族割やリピート割、紹介者割引みたいな、既に納税した方の横のつながりといった展開を求めていくというのも、１つ、埋没しないための解決策になるのかと思いますが、こちらもご見解をお聞かせください。","respondent":"久保田企画部長","answer":"こうしたことを推進していくためには、全庁的に推進していかなければならないと考えております。執行体制についても、こういった状況に機動的に対応できるような執行体制が必要と考えていますので、私どもとしましても検討していきたいと考えているところです。","voiceIndex":10,"id":"exchange-004"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"家族割等の割引の話については、ふるさと納税は国の制度でありますから、そういったことがそもそもできるのかというのもやはり確認していただきたいと思いますが、仮にできないとすれば、納税者に対して例えば招待チケットみたいなものを送って、ほかのイベントに誘導していくというのも１つ、手だと思っていますので、例えば納税した方のお友達は、しながわ水族館が無料ご招待や割引になるなど。","respondent":"久保田企画部長","answer":"今後は、開始から約８年を迎えるといったところもありますので、一定程度の見直しが必要と考えているところでございまして、品川区の価値やイメージを想起させるようなキャッチコピーも含めまして、新たな取組を検討していきたいと考えているところです。","voiceIndex":12,"id":"exchange-005"},{"speaker":"せりざわ委員","kind":"提案","question":"新たな取組を検討したいというお話を頂きました。その中で、どんどん新しい品川区の色というのを見つけて、もしくは再発掘して広報していただければと思いますが、例えば観光大使についても以前も提案させていただきました。","respondent":"久保田企画部長","answer":"こうした取組につきましても、今後、シティプロモーションを新たに検討していくといった中で、そういった他の広がりを見せて、観光大使等の活用ができるかということについても、引き続き検討していきたいと考えているところです。","voiceIndex":14,"id":"exchange-006"},{"speaker":"せりざわ委員","kind":"質問","question":"様々、前向きにご検討いただいていると思います。今回、品川区長が昨年代わって非常に注目が集まっている、まさに品川区の色を売り出すタイミングになるのかと思いますので、ぜひこのタイミングで品川区の色、もう一度、魅力発掘をしていただいて、新たな品川区の色を出していって、ファンをどんどん増やしていただければと思います。私からの質問は以上で終わります。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-007"},{"speaker":"せお副委員長","kind":"質問","question":"せりざわ委員に続いて、総括質疑をいたします。令和４年度の年度途中である１２月に、濱野区長から森澤区長に代わりました。令和４年度に事業を安定的に執行するために心がけたことは、どのようなことでしょうか。そのようなシティプロモーションをはじめ、今後の事業展開はどのようになっていくのでしょうか。区長、２点、ぜひご答弁いただけたらと思います。","respondent":"森澤区長","answer":"一方、私が就任した直後におきましても、物価高騰への対応は喫緊の課題でありまして、地方創生臨時交付金などの活用により、速やかに補正予算を提案することで、区民や区内企業の皆様方の支援を進めました。","voiceIndex":18,"id":"exchange-008"},{"speaker":"せお副委員長","kind":"質問・要望","question":"区長の思いを理解いたしました。再犯防止推進計画についてお聞きします。令和４年度、社会を明るくする運動において、主にどのような目的で事業を展開され、どのような成果がありましたでしょうか。課題も教えてください。そして、社会を明るくする運動に関連して、今年度、品川区では再犯防止推進委員会が設置され、再犯防止推進計画を策定中であり、保護司会からも計画策定の要望があったと伺っております。","respondent":"川島地域振興部長","answer":"そのため、区では現在、再犯防止推進計画を策定しています。その素案についてパブリックコメントを今実施しており、令和６年１月には、パブリックコメントでの意見を品川区再犯防止推進委員会に報告し、素案を決定し、３月に計画を公表する予定です。","voiceIndex":20,"id":"exchange-009"},{"speaker":"せお副委員長","kind":"質問","question":"そもそも国での再犯防止推進計画は、元衆議院議員の山本譲司さんの著書『獄窓記』、そして『累犯障害者』もきっかけになっていると伺っています。そこでお伺いします。今お話ししたような、出所してから福祉サービスを利用したケースは、今までありましたでしょうか。そして、そのようなケースがあってもなくても、このような取組にどのような課題がありますでしょうか。お聞かせください。","respondent":"今井福祉部長","answer":"ご本人に窓口等で直接お尋ねする性質のものではないと捉えておりまして、現時点ではサービスご利用者の状況は把握してございませんが、過去に窓口で、出所後であることをご本人からお伺いして対応した事例はあります。","voiceIndex":22,"id":"exchange-010"},{"speaker":"せお副委員長","kind":"提案","question":"私は、法務省が業務委託をした南高愛隣会にもお話を伺いました。それは、当事者ご自身でも認知できていない場合が多く、ご自身だけでは解決できないので、支援を提案する中で初めて自覚し、福祉・医療サービスとつながる方もいらっしゃいます」とのことです。そういった官民連携は、再犯防止推進計画が策定されるに当たって、どのように検討されていますでしょうか。情報提供もできるのでしょうか。","respondent":"川島地域振興部長","answer":"再犯防止推進計画の策定においては、事例でお示しいただいた、官民連携まで踏み込んだ具体的な検討というのはしてございませんが、適切な保健医療や福祉サービスにつなげるために重要な視点と認識しています。","voiceIndex":24,"id":"exchange-011"},{"speaker":"せお副委員長","kind":"質問","question":"私が座ってしまったので一問一答になってしまうのですが、最後にすみません。これは、再犯防止に努めるには、若者から高齢者、障害者であっても、福祉が充実していないと成り立たないからです。現在、品川区において準備中である重層的支援体制整備事業もあります。地域福祉計画や重層的支援体制整備事業に再犯防止施策を取り入れることについて見解を伺います。","respondent":"今井福祉部長","answer":"再犯防止施策に関わる当事者や関係者の皆様からのご相談につきましても、重層的支援体制整備の中で、所管の地域活動課だけではなく、庁内および多機関連携の中で対応してまいりたいと考えております。","voiceIndex":26,"id":"exchange-012"},{"speaker":"せお副委員長","kind":"質問","question":"民生費でも質疑がありましたが、児童相談所設置市となることで増える事務について、令和４年度から保育課では人員を増やしているといったご答弁がありました。１６事務増えるわけで、これはかなり大変なことだと思っています。都区財政調整のお話もありますが、東京都の何かしらの補助金を利用する、区の職員が業務に慣れるまで都の職員を派遣してもらうなど、できないのでしょうか。見解を伺います。","respondent":"柏原子ども未来部長","answer":"事務が増えることといったところへの対策についてですけれども、児童相談所の設置市事務について、こちらについては令和３年度から、庁内で検討を計画的・継続的に進めてきておりまして、庁内での意識の統一といったことや、事務の中の精査といったところを行ってきたところです。","voiceIndex":28,"id":"exchange-013"},{"speaker":"せお副委員長","kind":"質問・要望","question":"指導・監督するということは、子どもたちの安心・安全に直接関わります。そこで区立児童相談所では、保護者がどのような状況でも、まず子どもが適切な医療を受けられる権利、そして成長・発達を一番に考えていただき、医療機関に関しては、一時保護に協力していただける病院を増やす努力をしていただきたいのですが、見解を伺います。児童相談所内の一時保護所での対応を伺います。","respondent":"柏原子ども未来部長","answer":"保護所では集団生活となるといったところが基本ではありますけれども、一時保護に至る背景には様々な要因があることから、お一人お一人の支援プログラムを作成して、個別計画を基本に対応するといったことになってあります。","voiceIndex":30,"id":"exchange-014"},{"speaker":"せお副委員長","kind":"質問","question":"どんな状況に生まれても、全ての子どもたちが幸せに自分らしく生きてほしいです。私としては、先ほどの病院へのお願いなどはお手伝いします。この視点における、令和４年度の成果と現在の課題を教えてください。倉庫に関しては、どうしても必要であれば民間からお借りすることも可能です。そのような観点から、スピード感を持って有効活用に取り組むべきと考えますが、区の見解をお聞かせください。","respondent":"久保田企画部長","answer":"今後も公有地の有効活用に向けまして、スピード感を持って検討してまいります。","voiceIndex":32,"id":"exchange-015"},{"speaker":"せお副委員長","kind":"質問・要望","question":"スピーディーな検討を、ぜひお願いしたいと思います。私は、区民のお話を伺っている中でやはり多く頂くのは、障害者の就労に関しての要望です。そのような視点・考え方を区として持っていただきたいのですが、見解を伺います。Ｐａｒｋ－ＰＦＩの導入によって、障害者の清掃業務などの労働機会を現状より減らすことがないようにしていただきたいのですが、こちらも見解を伺います。","respondent":"溝口防災まちづくり部長","answer":"併せまして、せお副委員長ご指摘の社会貢献や地域貢献といったものを併せて進めていくといったことも重要であると認識しています。","voiceIndex":34,"id":"exchange-016"},{"speaker":"せお副委員長","kind":"質問・要望","question":"そのような前向きな見解をお持ちいただきありがたいです。障害者の労働の機会を増やせるように、区としても積極的に考えていただきますよう要望いたします。最後に、所得制限についてお聞きします。補装具、日常生活用具。最後に、障害児の補装具・日常生活用具の給付での所得制限撤廃について、そして今後、障害児の福祉に関する事業での所得制限を段階的に撤廃することについて、それぞれ見解を伺います。","respondent":"今井福祉部長","answer":"障害児の補装具、日常生活用具の給付を含め、障害児に関する事業の所得制限の段階的撤廃につきましては、子どもの支援を進める観点から、それぞれの事業の性質に鑑み、多角的に検討してまいりたいと考えております。","voiceIndex":36,"id":"exchange-017"},{"speaker":"つる委員","kind":"質問・要望","question":"区議会公明党を代表して、若林委員と共に総括質疑を行います。初めに、地域共生社会の実現に向けた包括的支援体制を推進する重層的支援体制整備事業（しあわせ創設プラン）と、孤独・孤立対策についてお尋ねいたします。重層的支援体制整備事業については、２０２０年の第１回定例会より、繰り返し、体制整備を求めてきたことから、２０２５年度の本格稼働に向けた盤石な体制を求めるものです。","respondent":"今井福祉部長","answer":"令和７年度の本格実施に向けまして、鋭意検討を進めております。相談支援の対応につきましては、ケース会議での協議を経て、関係者間協働で相談者への回答を行うなど、成果が出ているところです。","voiceIndex":40,"id":"exchange-018"},{"speaker":"つる委員","kind":"意見","question":"複雑化した課題の一つに挙げられる孤独・孤立対策について、重層的支援体制整備事業の構築と併せて、来年度施行の孤独・孤立対策推進法に基づき、孤独・孤立対策と一体的に推進していく必要があります。そこで、品川区の孤独・孤立の現状と把握状況、区がこれまでに取り組んできた孤独・孤立対策についてお知らせください。","respondent":"今井福祉部長","answer":"私どもは今年度から、孤独・孤立プラットフォーム推進事業にも取り組んでまいりますので、区民の皆様の孤立・孤独を防止する様々な対策について検討を進めていきたいと考えています。","voiceIndex":42,"id":"exchange-019"},{"speaker":"つる委員","kind":"質問","question":"過日の一般質問の答弁では、今年度改定する地域福祉計画に、推進法の成立を受け、重層的支援体制整備と重複する、誰一人取り残さない考え方を位置づける必要があると示され、また、孤独・孤立に悩む幅広い世代に対しての基本的施策の体系化の検討が行われていると認識しています。孤独・孤立対策推進協議会の設置時期、構成メンバー、具体的な役割など、改めてお知らせください。","respondent":"今井福祉部長","answer":"地域協議会参加に当たって、各団体との参加の協議を経て、発足という段取りとなると考えております。設置時期につきましては来年度を予定しているため、構成する委員や役割など具体的な状況につきましては、設置時期です来年度にお示しすることを予定しております。","voiceIndex":44,"id":"exchange-020"},{"speaker":"つる委員","kind":"意見","question":"品川区は、来年度策定の第四期品川区地域福祉計画策定に向けた改定作業を今年度実施しています。そこで、事前アンケートで示された各属性に広がる孤独・孤立対策の強化と、若年層での孤独・孤立感が顕著になった要因の分析、若年層に向けた具体的な孤独・孤立対策をどのように強化していくのか、区のお考えをお知らせください。","respondent":"今井福祉部長","answer":"若年層に向けた具体的な孤独・孤立対策の強化につきましては、この分析を基に各事業あるいは新規対策として、庁内横断的に施策を展開して検討してまいりたいと考えております。","voiceIndex":46,"id":"exchange-021"},{"speaker":"つる委員","kind":"質問・要望","question":"ぜひ、分析に基づいた新たな、今、「新規」とございましたけれども、若年層に向けた具体的な孤独・孤立対策を積極的に検討していただきたいと思います。そこで、今回、同事業に応募した理由、決定を受けての今後の取組、スケジュールなどについてお知らせください。品川区の孤独・孤立対策の区民への周知、意識啓発をどのように行っていくのか、併せてお知らせください。","respondent":"今井福祉部長","answer":"本年５月に成立いたしました孤独・孤立対策推進法を受け、誰一人取り残さないという地域共生社会の実現に向けて、現在、区が取組を進めております重層的支援体制整備事業と一体的に推進していく必要があるとの認識の下、内閣官房に応募し、９月８日付で採択されたところです。","voiceIndex":48,"id":"exchange-022"},{"speaker":"つる委員","kind":"質問・要望","question":"そうした方へのアプローチも含めてお考えいただきたいので、ここについては改めてご答弁いただきたいと思います。そこで、在宅介護支援センターや、地域の身近な行政機関である地域センターに設置している支え愛・ほっとステーションを、幅広い世代の相談機関として拡充していくことが望まれますが、しあわせ創設プランでの位置づけはどうなるのか、現在の相談対応実績と併せてお知らせください。","respondent":"今井福祉部長","answer":"続きまして、在宅介護支援センターや支え愛・ほっとステーションの拡充などにつきましてですが、まず相談件数ですが、直近の令和４年度の在宅介護支援センターの相談対応実績につきましては、区内２０か所で約２万４,０００件、支え愛・ほっとステーションの相談・対応実績は。","voiceIndex":50,"id":"exchange-023"},{"speaker":"つる委員","kind":"質問","question":"そこの周知のところは、本当に必要な人に届くということが大切だという意味合いですので、この事業だけではなく、品川区の施策全てにおいて言えることかもしれませんが、そこをしっかりと、再度、重点的にお願いしたいと思います。ドクターの元には、病気そのものの診察だけでなく、地域福祉に該当する相談も寄せられていると、医師会所属のドクターからも伺っています。","respondent":"今井福祉部長","answer":"加えて現在、委員ご提案の医師会などを通じて、今後は、管轄の支え愛・ほっとステーションに在籍いたします、社会福祉士の資格を持つコーディネーターを紹介するなど、周知を図ることや、相談機関の情報リーフレットの提供などを行い、地域福祉。","voiceIndex":54,"id":"exchange-024"},{"speaker":"つる委員","kind":"質問・要望","question":"孤独・孤立の具体的な予防策の一つとして、ｅスポーツを活用した多世代交流の推進を求めてきました。そこで改めて、孤独・孤立の具体的な予防策の一つとして、ｅスポーツを通じた多世代交流の事業の進捗状況と、同事業の継続・拡大を視野に入れた実施を求めますが、ご所見をお聞かせください。","respondent":"柏原子ども未来部長","answer":"他の児童センターにおいても、機会があれば多世代交流事業を実施していきたいという考えでございまして、今回こうした事業を実施する中で、そういう実績を基に、どういった運用が効果的なのかなど、今後、検証していきながら、次の展開につないでいきたいと思ってあります。","voiceIndex":56,"id":"exchange-025"},{"speaker":"つる委員","kind":"質問","question":"協定について、また引き続き、ぜひ積極的な検討をお願いしたいと思います。そこで、防災区民組織の皆様の防災力強化の支援として、区が作成・所有する地図データを、加工が可能な状態での提供や、民間の地図データを購入した際に活用できるよう、防災資機材整備助成金の対象に地図データを含めるなど、対象の拡大および交付額の増額を検討してはいかがでしょうか。","respondent":"滝澤災害対策担当部長","answer":"市販されている住宅地図などの取得を希望する場合の費用助成は現時点では行っておりませんが、共助を担う組織の地域防災力向上のための支援として、今後はその費用助成についても検討してまいりたいと考えております。","voiceIndex":60,"id":"exchange-026"},{"speaker":"つる委員","kind":"質問・要望","question":"「しながわＭＡＰ」については、かつて区民が活用しやすいということで、その活用を推進させていただいて、品川区に実施いただいたマップで、それを活用いただくということで、いろいろな意味でうれしく思いますが、しっかりとそうした防災対策の強化の視点で、地域の皆様がしっかりと使いやすい資料・データの提供を、これからも検討していただきたいと思います。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-027"},{"speaker":"若林委員","kind":"質問・要望","question":"令和４年度決算の概要などをお聞きいたします。一般会計決算歳入は１,９５９億円余、実質収支は６２億円余の黒字で、昭和５３年度から４５年の黒字。財政の健全化判断比率は４項目とも健全性を表しています。単年度収支について、財政運営の面などから説明を伺います。水と緑や災害時協定など、交流を行っている５つの市町のふるさと納税の活用事業についてもお聞かせいただきたいと思います。","respondent":"遠藤財政課長、久保田企画部長、堀越総務部長","answer":"令和４年度におきましては、要因の一つとなりますが、令和３年度に実施しました新型コロナウイルスワクチン接種等に国からの支出がありましたが。今回の行政評価では、効果的・効率的な行財政運営に向けて、行政活動の効果や成果を、必要性や有効性などの観点から分析し。税務課が担っております担当部署につきましても、税収減への対応に向け、執行体制について検討してまいりたいと考えています。","voiceIndex":66,"id":"exchange-028"},{"speaker":"若林委員","kind":"質問・要望","question":"続きまして、款別審査の中から２つの事業についてお尋ねいたします。対策を進める上で、目的を明確にした再調査が必要と思いますが、いかがでしょうか。認知症では、軽度認知障害に至る前の頭の健康領域・正常値を定期的に観察し、指導などを行うことで、認知機能低下に自ら努力できることから、あたまの元気度チェックの早期導入を求めております。これにつきましても、改めてお考えをお聞きいたします。","respondent":"堀越総務部長、川島地域振興部長、今井福祉部長","answer":"委員ご指摘の通り、この５市町とのさらなる理解や交流を深めること、加えて、品川区との区民、市民、町民同士の相互理解。〔同日後刻に「大崎駅東口ではなく、大井町駅東口にコンテナ型喫煙所の設置の準備を進めている」と答弁訂正あり〕 次に、昨年度実施しました。現在は個別検診で行っておりますもの忘れ検診の分析を行いつつ、あたまの元気度チェックについて、医師会や医療機関と協議の上。","voiceIndex":70,"id":"exchange-029"},{"speaker":"若林委員","kind":"質問・要望","question":"コンテナ型のところでは、答弁の後半、これから大崎駅の東口をやるみたいなご答弁に聞こえましたので、もう一度ご確認いただいて、もし訂正がありましたら改めて答弁をお願いいたします。この夏、公明党として、３５の団体から区政への意見・ご要望をお聞きするとともに、区民との個別対話を行い、８００人以上の方々からお話を伺いました。区営住宅の最低家賃はおよそ２万数千円となっています。","respondent":"川島地域振興部長、阿部健康推進部長、柏原子ども未来部長、中村都市環境部長","answer":"先ほどのコンテナ型喫煙所の私の答弁ですが、誤りでございまして、大崎駅東口ではなく。委員ご指摘のとおり、出産育児一時金が本年４月に、これまでの４２万円から５０万円に引き上げられ。そうした方へ支給した場合の金額といたしましては、約５,４００万円となると見込んです。参考までですが、民間賃貸住宅の家賃と区営住宅の最も低い使用料との差額を補助するという考え方でいきますと。","voiceIndex":74,"id":"exchange-030"},{"speaker":"若林委員","kind":"質問・要望","question":"まさに現実的な数字を確認いたしました。ベーシックサービス提唱者の井手英策・慶応大学教授は、公明党の地方議会局などで講演され、会派でも直接お話を伺いました。さて、以上のような観点から何点かお尋ねいたします。本委員会等でも取り上げてきましたけれども、本年３月、学校教材、学用品と、区立学校以外に通う子どもの給食費の負担軽減策を区長に緊急要望いたしました。","respondent":"米田教育次長、今井福祉部長、阿部品川区保健所長","answer":"今後の支援拡大の考え方についてですが、国立・私立特別支援学校への給食費補助の拡大や、区立学校の教材費等の負担軽減について、検討を行ってまいります。引き続き、補聴器装用による効果検証と併せ、都などの動向も注視しつつ、検討を進めてまいります。既に開始しております今年度の接種では、勧奨を積極的に行うとともに、高齢者の健康を守る観点から、ワクチン接種費用につきましては、今後の都の動きや。","voiceIndex":79,"id":"exchange-031"},{"speaker":"若林委員","kind":"質問・要望","question":"介護職の月６,０００円という報道のご答弁があった際には、会場から、様々な意味でのご感想の声が上がったと思います。私も、様々なそういう声を聞きながら、ご検討いただくですので、区の取組を一重、ぜひお願いしたいと思います。さて、ベーシックサービスの例を基に質疑を進めします。ベーシックなサービスへのご見解、また今後の施策展開のお考えを、最後にお聞きしたいと存じます。","respondent":"久保田企画部長","answer":"一方で、施策を実施するには財源の確保が必要であります。行政評価によるスクラップ・アンド・ビルドを進め、財源を確保し、区民に求められる施策をバランスよく実施することで、区民の幸せ、ウェルビーイングの向上を目指して区政を進めてまいりたいと考えているところです。","voiceIndex":83,"id":"exchange-032"},{"speaker":"若林委員","kind":"意見","question":"ベーシックサービスについては、本格的に今回こういった場で取り入れさせていただきました。勉強すればするほど、ベーシックサービスの実現は大変に、私たちの中では難しいと感じておりますけれども、この理想的な社会に向けて、私どもはまた区民の皆さんとも議論をしながら、また執行部とも議論しながら進めてまいります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":85,"id":"exchange-033"},{"speaker":"松永副委員長","kind":"質問","question":"しながわ未来（無所属・立憲・ネット）を代表し、吉田委員と共に総括質疑を行います。初めに、公契約条例について伺います。そこで、公共事業の現場について、本区ではどのようなモニタリングをされているのでしょうか。建設団体による独自の調査によると、適正な賃金が支払われていないという調査結果が出てきておりますが、そのことについてどうか、併せて伺います。","respondent":"堀越総務部長","answer":"公共事業の労働環境に関するモニタリングなどに関するご質問ですけれども、区では予定価格２,０００万円以上の工事請負および委託請負の契約を対象に、労働環境チェックシートの提出を義務づけておりまして、労働環境の確認を行っているところです。","voiceIndex":88,"id":"exchange-034"},{"speaker":"松永副委員長","kind":"質問","question":"続けて公契約条例について伺いますが、今年の第２回定例会で質問をさせていただいた際に、既に制定されている他自治体の様子を伺っている段階だと認識しております。制定につきましては、以前は検討中との回答を頂いたのですが、他自治体の様子を伺った結果、現在の制定に向けての課題点、進捗状況についてお知らせください。公契約条例について国での検討の動きなどがありましたら、その旨も併せて伺います。","respondent":"堀越総務部長","answer":"この中で、適切な労務費等の確保や、いわゆる賃金が行き渡ることの担保のため、標準労務費の勧告等を検討していると聞いております。公契約条例の検討に当たっては、こうした国の動きについても注視していきながら検討していきたいと考えています。","voiceIndex":90,"id":"exchange-035"},{"speaker":"松永副委員長","kind":"質問","question":"防災対策について伺います。初めに避難所について伺います。避難所の受入体制は約３割と言われ、残りの７割の方は在宅避難を進めていると伺っておりますが、現在、本区で進めている避難所の受入数、そして在宅避難の割合についてお知らせください。ペット同行避難等のマニュアルについて、何か所の避難所で作成されているのでしょうか。現在の状況について併せて伺います。","respondent":"滝澤災害対策担当部長","answer":"今後は品川区地域防災計画の大規模修正に伴い、令和６年度中に全ての区民避難所においてペットの受入れができるよう、避難所連絡会議などの場でご理解を得て、マニュアルを整備してまいります。","voiceIndex":92,"id":"exchange-036"},{"speaker":"松永副委員長","kind":"質問・要望","question":"割合につきましては理解いたしました。次に、品川医師会、荏原医師会との連携について伺います。現在、災害が発生した場合、区内各地区に１か所、学校医療救護所が設置されると伺っております。こちら、防災ハンドブックに掲載されております。併せて、学校医療救護所の設置数が全体的に少ない感じがいたしますので、ぜひ増設していただくよう要望いたしますが、区のお考えについてお知らせください。","respondent":"滝澤災害対策担当部長","answer":"医師会とも連携しながら、災害時の地域医療が回復するまでの間の被災者に対する医療救護の在り方・体制について検討してまいります。","voiceIndex":94,"id":"exchange-037"},{"speaker":"松永副委員長","kind":"質問","question":"「しながわ防災ハンドブック」、「品川区防災地図」につきましては、全戸配布や、転入された方には届出を出された際に配布しているそうですが、なくしてしまった方もおられるそうで、こうした方々に対し、各地域センターや防災訓練、イベント等で配布されていると伺っております。防災訓練は、町会・自治会員だけでなくても参加は可能なのでしょうか。改めて伺います。併せて伺います。","respondent":"滝澤災害対策担当部長","answer":"一方で、訓練の参加者が固定化しているなどの課題も認識しております。このため、誰でも訓練に参加していただけるよう、イベント要素などを加味した防災訓練の在り方を具体化して、より幅広い世代や、障害をお持ちの方などにも、防災訓練にご参加いただけるようにしてまいります。","voiceIndex":96,"id":"exchange-038","title":"町会・自治会支援"},{"speaker":"松永副委員長","kind":"質問","question":"品川歴史館について伺います。いよいよ来年の４月にリニューアルオープン予定の品川歴史館ですが、４月のいつ頃にオープンされる予定でしょうか。品川歴史館近くにあります大森貝塚遺跡庭園とコラボし、例えばキッチンカーを出店し、来館者のおもてなしをするなどの企画等は考えておられるのでしょうか。併せて伺います。","respondent":"廣田文化スポーツ振興部長","answer":"オープンに際しましては、歴史館のみならず大森貝塚遺跡庭園にも回遊して楽しめるような仕組みについて、今、仕組みの構築について検討しています。","voiceIndex":98,"id":"exchange-039"},{"speaker":"松永副委員長","kind":"質問・要望","question":"ぜひご検討していただければと思います。続けて、品川歴史館オープニングセレモニーの来場者についてですが、どのように周知されているのでしょうか。一般の方も参加は可能なのでしょうか。そこで周知方法についてですが、町会・自治会掲示板、またホームページ、そしてコミュニティバスの広告看板等での周知を要望いたしますが、いかがでしょうか。","respondent":"廣田文化スポーツ振興部長","answer":"オープニングのセレモニーにつきましては、参加者や具体的な内容については現在検討を進めているところです。キッチンカーも含めまして、検討していきたいと思ってあります。","voiceIndex":100,"id":"exchange-040","title":"町会・自治会支援"},{"speaker":"松永副委員長","kind":"提案","question":"先ほどお答えいただいた大森貝塚遺跡庭園とのイベント企画についてですが、リニューアルオープンがゴールデンウイーク前ということもあり、ぜひゴールデンウイーク期間中、縄文太鼓や縄文文化に関する公演を、歴史館か遺跡庭園での開催をしていただきたいということなのですけれども、また可能でしたら、縄文太鼓の演奏会を大森貝塚遺跡庭園の中庭で行ったり、歴史探検として鹿嶋神社や来迎院。","respondent":"廣田文化スポーツ振興部長","answer":"現在、オープンに向けて検討していますけれども、たくさんのご提案ですので、オープン当初に全て実施するということは困難かとは思いますが、新しくなった歴史館に、区内外を問わず多くの方に来ていただけるように、今後もいろいろな取組をしていく中で考えていきたいと思います。","voiceIndex":102,"id":"exchange-041"},{"speaker":"松永副委員長","kind":"質問・要望","question":"ぜひ、こうした大きな節目の年ということで、大森貝塚遺跡庭園を多くの方に知っていただくため、大田区とコラボし、大森貝塚を世界に発信できるようなイベントをしていただきたいと考えておりますが、本区の考え、また大森貝塚１５０周年の記念品として、例えば社会福祉協議会と連携し、縄文クッキーを作っていただき、それを記念品としてお渡ししてみてはいかがでしょうか。併せて伺います。","respondent":"廣田文化スポーツ振興部長","answer":"大森貝塚発掘１５０周年記念のご要望を頂いたところですけれども、まだ期間も長くありますので、今後、大田区や大森貝塚保存会の方の動向などを見ながら、品川区としても考えていきたいと思っているところです。","voiceIndex":104,"id":"exchange-042"},{"speaker":"松永副委員長","kind":"質問","question":"ぜひ、大田区も含めた大きなイベントが開催できるよう、ご検討のほどよろしくお願いいたします。そして、そのことを見据え、最後の質問になりますが、大森貝塚遺跡庭園をこれからどのように進めていかれるのか、またアイデアにつきましては、地域の方からのご意見を聞かれるなどして進めてみてはと思うのですが、本区の考えについてお知らせください。","respondent":"溝口防災まちづくり部長","answer":"今後、公園の施設の機能の老朽化といったものの度合いを見ながら、また令和９年には節目を迎えるということもありますので、それを見据えつつ、大規模な改修については検証していく必要があると認識しています。","voiceIndex":106,"id":"exchange-043"},{"speaker":"松永副委員長","kind":"質問・要望","question":"様々多くのご要望をさせていただきましたが、ぜひともご検討いただければと思いまして、私からの質問を終わらせていただきます。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":108,"id":"exchange-044"},{"speaker":"吉田委員","kind":"質問・要望","question":"私からは、品川区の再開発事業の在り方について改めて伺います。先日、都市開発課長からは、個人の財産権に関しては、これまで損をしたというお声は一人も頂いていないという明言を伺いました。その点について、改めて確認させていただきたいと思います。土木費の質疑の際には、区民が利用できる区有施設についてあまりご答弁がなかったと思うのですが、改めてその点について伺います。","respondent":"有江都市整備推進担当部長","answer":"再開発に関する応援をありがとうあります。土木費で答えさせていただきました、個人の権利の件ですけれども、再開発事業が終了した後に、権利についてのご相談というかご意見というのは私も聞いておりませんので、課長が答弁した内容と同じです。","voiceIndex":110,"id":"exchange-045"},{"speaker":"吉田委員","kind":"質問・要望","question":"それで、土木費の際にも、空地や道路などというお答えが来るに相違ないので、ぜひ区民利用できる施設という点で伺いました。それは、例えばいろいろな担当部署が、そういう施設は区民が要望していないということで要望がなかったのか、もしくは、地域の方たちからそういう要望が一切上がってこないという意味なのか、その辺についてお答えいただけたらと思います。","respondent":"有江都市整備推進担当部長","answer":"それらのものをどのような形で再開発において取り入れていくかですけれども、市街地再開発事業における公共施設の整備については、開発予定地域におきましての地域特性や、地域でつくられました協議会・準備組合との協議を踏まえまして。","voiceIndex":112,"id":"exchange-046"},{"speaker":"吉田委員","kind":"質問・要望","question":"最終的には、やはり事業者が判断されるということは、そのとおりかと思います。私が気にしておりますのは、品川区の中で、区としてこの再開発に当たってはこういうものを実現してほしい、こういうものが要望に上がっておりますということを、きちんと伝えているのかどうかということです。","respondent":"有江都市整備推進担当部長","answer":"先ほど申しましたとおり、事例としましては、子育て支援施設、高齢者福祉施設等がありますけれども、例えば我々が把握している範囲でありますと、子育て支援施設では８施設、高齢者福祉施設は２施設、あと、区民や地域の活動に資する施設を７施設ほど。","voiceIndex":114,"id":"exchange-047"},{"speaker":"吉田委員","kind":"質問・要望","question":"それから子育て支援施設も、できましたら、子育て支援といってもいろいろありますので、例えばどういう施設が実現しています、どういう要望が上がってきた結果、協議の結果、こういうものが実現していますというふうに教えていただけたらと思います。この中で、例えば障害者施設などが全然ないのですけれども、それはご要望がないという理解でよろしいでしょうか。その点についてもお答えください。","respondent":"有江都市整備推進担当部長","answer":"個々の細かな調整の経緯というのは非常に、過去の経緯もありますので、この場では詳細はお伝えできないのですけれども、例えば子育て支援施設としては保育園などが設置されております。場所につきましても、この場では詳細は割愛しますけれども。","voiceIndex":116,"id":"exchange-048"},{"speaker":"吉田委員","kind":"質問・要望","question":"ごめんなさい。続けますけれども、障害者や高齢者の施設については、つくりたいけれども、今、場所がないからというのが、度々、委員会の中ではご答弁として挙がっているかと思うのですけれども、要望したのだけれども、そこの事業者の判断で実現しなかったのか、それとも要望していないのかということについては、区の姿勢として私は大変重要ではないかと思うのですけれども、その点について伺います。","respondent":"有江都市整備推進担当部長","answer":"公共施設の設置についてですけれども、基本的には再開発は拠点整備というところで、例えば大崎や大井町といった拠点のところで整備されているというところで、ある程度、場所が決まっているというような状況になっております。","voiceIndex":118,"id":"exchange-049"},{"speaker":"吉田委員","kind":"質問・要望","question":"そうなのです。区の姿勢のほうを伺いたいのです。それで、今、担当の部長だけにお答えいただいていますけれども、例えば子育ての担当や福祉のほうから今までこういう要望を出したというような実績があったらぜひ伺いたいと思いますが、いかがでしょうか。それと、手順も伺いたいのです。こういう再開発の事業が起こっています。話があります。","respondent":"有江都市整備推進担当部長","answer":"そういった中で、そういった意見があれば、それを我々は抽出して組み上げて組合と調整いたしますけれども、いうなれば民間が行う開発ですので、そういったものをどうするかというのは、非常にやはり事業性というものが事業者は重要になってきますので。","voiceIndex":120,"id":"exchange-050"},{"speaker":"吉田委員","kind":"質問","question":"ごめんなさい。理解が悪くてすみません。地域特性でということなのですけれども、地域特性でまず判断するというのは、どういう意味のご判断なのでしょうかというのと、最終的に事業性というのはよく分かります。そのとおりだと思います。その中で、例えば障害者施設や高齢者施設が入ることが、事業的にそれが不利になるというような判断が働いているという理解でよろしいのでしょうか。教えてください。","respondent":"有江都市整備推進担当部長","answer":"拠点における地域特性を我々としては集約しまして、内部的に調整していくというような流れになっていきます。","voiceIndex":122,"id":"exchange-051"},{"speaker":"吉田委員","kind":"質問・要望","question":"よく分からないのです。それで、例えば大崎を今、例に挙げられましたけれども、そこでは全ての施設が十分に整っているから特に要望しないというふうに聞こえてしまったのですけれども、それが間違いだったら、「こう間違っています。こういうふうに要望しています」とお答えいただきたいと思います。それが、再開発の中のこういう制度があるにもかかわらず、なぜ実現しないのだろうか。","respondent":"有江都市整備推進担当部長","answer":"先ほど申しましたように、事業者の判断というのは、やはりどうしても民間事業ですので、最終的な判断というのはあるのですけれども、要は何を受け入れるかどうかというところも踏まえて、様々なケースがありますので、一概にこの施設がよいとか悪いとかという判断は。","voiceIndex":124,"id":"exchange-052"},{"speaker":"吉田委員","kind":"質問・要望","question":"それはやむを得ないことかと考えています。先ほどから繰り返しておりますけれども、区がどこをどういうふうに判断して要望を出したのかということが伺いたいのです。品川区も事後評価は行われていると思いますし、その評価の中で、例えばこういうふうに要望したものが実現したかどうかというのは評価の一つになると思うのですけれども、その辺の事後評価が実施されているかどうかについても併せて伺います。","respondent":"桑村副区長、有江都市整備推進担当部長","answer":"いろいろ検討させていただければと思います。市街地再開発事業を行う場合は、国土交通省に対して、事業の効果や必要性を評価するための指標など、新規事業採択における客観的評価指標を提出しておりまして、事業が適正かというものを含めて、国を含めて対応しています。","voiceIndex":126,"id":"exchange-053"},{"speaker":"吉田委員","kind":"質問・要望","question":"事後評価はやはり、ぜひしていただきたいと思います。中には、事後評価委員会ですか、区民参加でそういう委員会も開かれておりますし、それが公表されているという形です。ぜひ、この点については検討していただきたいと思いますが、改めて見解を伺います。そこが計画的に示されていないということが、そもそも問題なのではないかと思うのですけれども、その点についてもお考えを伺いたいと思います。","respondent":"桑村副区長、有江都市整備推進担当部長","answer":"そういう意味では、そういう大型の開発をするわけですから、そこにお住まい、あるいはオフィス等を構える方にとってもサービスが高くなるし、また地域によってもよくなるというのが再開発の理想ですので、そうやってもらいたいために。事後評価につきまして私からお答えしますけれども、現時点では実施の予定はございませんけれども、他自治体の事例等を研究したいと思います。","voiceIndex":129,"id":"exchange-054"},{"speaker":"吉田委員","kind":"質問・要望","question":"事後評価、まずは研究ということだったのですが、やはり区民がそういうふうに主体的に評価に関わるということが次の理解を生んでいくし、区全体の中でこういう福祉が実現していくのだということの機運を高める形にもなると思います。もし何か見解があったら、後で伺いたいと思います。ぜひ品川区でもそういう視点を持っていただきたいのですが、最後にもう一回、コメントを伺いたいと思います。","respondent":"桑村副区長、有江都市整備推進担当部長","answer":"いろいろご意見を頂きまして。すぐにそれが、さっとできるかというと、なかなかそこまで頭が回らないですけれども、一定のお話になったのはよく理解できますので、十分検討させていただければと思います。繰り返しの答弁になりますけれども、他自治体の事例等を研究してまいりたいと思います。","voiceIndex":132,"id":"exchange-055"},{"speaker":"吉田委員","kind":"質問・要望","question":"いろいろ検討していただいて、みんなが本当に賛成できる再開発を目指していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":135,"id":"exchange-056"},{"speaker":"のだて委員","kind":"質問・要望","question":"私からは、羽田新ルートの中止、現庁舎跡地の検討、しながわ中央公園の存続を求めて質問をします。初めに、９月に実施した区民アンケートについてお聞きします。１５歳以上の区民と小・中学生へのアンケートの回答数、そして回答割合をお聞きします。アンケートにどのような声が寄せられたのか伺います。オープンデータなども活用して、自由記述欄は全文を公開するよう求めます。いかがでしょうか。","respondent":"中村都市環境部長","answer":"自由意見につきましては、現在、集計中です。公開についてですけれども、個人情報に配慮しつつ、どのような方法で公開できるかについてはこれから検討してまいります。","voiceIndex":137,"id":"exchange-057"},{"speaker":"のだて委員","kind":"質問・要望","question":"自由記述欄を、寄せられた区民の声がしっかりと分かるように全文公開することを求めておきたいと思います。先月、９月２５日の建設委員会の陳情審査において、「区は、固定化回避については、品川区上空を飛ばなくなることを国に求めてきたわけではありません」と答弁しました。なぜ品川区の上を飛ばないことを求めないのか伺います。区が国に要望していた固定化回避とは、何を求めていたのか伺います。","respondent":"中村都市環境部長","answer":"固定化回避検討会につきましては、区は区民の影響の軽減に向けまして、現在の新ルートを将来にわたり固定化せずというところで、可能な限り環境影響の軽減につながる方策の検討・実施を国に求めているものです。","voiceIndex":139,"id":"exchange-058"},{"speaker":"のだて委員","kind":"質問・要望","question":"私が求めたのは、なぜ品川区の上を飛ばないのかということも求めましたので、答弁していただければと思います。実際、今、答弁された中でも、結局は品川区を飛ばないことは求めていないということだと思います。区民への影響をなくすことはできません。１年前と比べて、羽田空港の国際便の数は増えているのか伺います。品川区の上空を飛ばないことを国に求めるべきです。区長、いかがでしょうか。","respondent":"中村都市環境部長","answer":"新飛行ルートは国策として、国の責任において実施されているですけれども、区としましては、現在集計中の区民アンケートがありますので、その結果を踏まえながら、区民負担の軽減につながる具体的な解決策といったものを検討するよう、国に働きかけてまいります。","voiceIndex":141,"id":"exchange-059"},{"speaker":"のだて委員","kind":"提案","question":"早期に具体化してほしいということを求めているということですけれども、既に検討して３年が過ぎているという状況で、もはや早くないという状況です。今、この立場に立つことこそ、品川区に求められています。しかし、区民ニーズの実現どころか、区民の財産である区有地が特定企業のもうけのために利用され、７０年にわたり、区民要望のために自由に使えなくなります。いかがでしょうか。","respondent":"多並広町事業担当部長","answer":"区では、現庁舎跡地に係る対話型市場調査を実施しており、今年の９月１５日に調査実施要領を公表し、募集を開始したところであります。１０月５日に募集を締め切り、１０月下旬から１１月上旬に向けてヒアリングを行っていく予定です。","voiceIndex":143,"id":"exchange-060"},{"speaker":"のだて委員","kind":"質問・要望","question":"改めて、この複数社が何社なのか伺いたいと思います。新庁舎でも、検討報告書はほとんどが黒塗りで、非公開、密室で進められてきました。今回も、企業の都合のいいように公開しない、隠蔽するということなのでしょうか。ぜひ今からでも区民には公開するようにしていただきたいと思いますが、なぜ公開できないのか、伺います。事業概要書と事前質問の内容も、どんな内容だったのか伺います。","respondent":"多並広町事業担当部長","answer":"この進め方の手順に当たっては、先ほども少しご説明させていただきました、国のガイドライン等に準拠させていただいておりまして、調査中は各いろいろな事業者の方と対話するために必要な事業をその中で行っていくものであり、それを聞いた上で。","voiceIndex":145,"id":"exchange-061"},{"speaker":"のだて委員","kind":"質問","question":"ぜひ公開して、区民参加を進めていくという姿勢が必要だと私は思います。今回、８月の庁舎跡地等活用検討委員会では、会の役割が今ひとつ薄いのではないかとの意見も出され、また、区はここで施設を絞り込んでいくとは考えていないと、区民ニーズと対話型市場調査のマッチングを行うところだと説明しました。このどこが、区長の言う「区民とともに創るしながわ」なのか、伺います。いかがでしょうか。","respondent":"多並広町事業担当部長","answer":"引き続き、区民と共に検討を進めてまいります。官民連携によるまちづくりは、行政と民間が連携することで、民間のノウハウや創意工夫等を活用する有効な手法であり、区民ニーズの実現と区民負担の軽減の両立を図るべく、引き続き検討を進めてまいります。","voiceIndex":147,"id":"exchange-062"},{"speaker":"のだて委員","kind":"質問・要望","question":"区民の財産が奪われるＰＦＩはやめるよう、改めて求めておきたいと思います。現在もアリーナを造るつもりなのでしょうか、伺います。品川区は福祉施設が足りていません。現庁舎跡地には、特別養護老人ホームや老健施設、障害者総合支援センターなど、福祉施設の整備を求めますが、いかがでしょうか。区が実現を目指す区民ニーズには福祉施設は入っているのでしょうか、伺います。","respondent":"多並広町事業担当部長","answer":"現在、庁舎跡地等活用検討委員会で、区民のニーズの把握に努めているところであり、現時点でアリーナや福祉施設など、具体の施設を想定して検討しているものではございません。","voiceIndex":149,"id":"exchange-063"},{"speaker":"のだて委員","kind":"提案","question":"今検討中ということですけれども、ぜひ、不足している福祉施設は整備していただきたいということを求めておきたいと思います。区は中央公園を大幅に再編する提案もあり得ると説明しました。さきの一般質問で、この公園の存続を求める質問に、区は、「廃止を前提として検討を進めるものではない。現庁舎跡地だけでは企業にメリットが少ないから、しながわ中央公園まで広げたのでしょうか、伺います。","respondent":"多並広町事業担当部長","answer":"検討対象については、あくまで庁舎跡地およびその周辺のまちづくりを一体的に行う観点が必要との考えから設定したものです。現在の公園を活かしつつ、区民ニーズを把握した上で、庁舎周辺の一体的なまちづくりについて検討を進めていく考えです。","voiceIndex":151,"id":"exchange-064"},{"speaker":"のだて委員","kind":"質問・要望","question":"これを見ていただくと、面積がまるで違いますので、機能を残しても、やはり今までどおりにはなりません。ぜひ存続していただきたいと思います。現庁舎跡地の活用は、多くの区民が利用するしながわ中央公園を今のまま残し、不足している福祉施設の整備を含め、情報公開と区民参加で検討するよう求めます。以上で、私の質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":153,"id":"exchange-065"},{"speaker":"安藤委員","kind":"質問","question":"のだて委員に続き、総括質疑を行います。再開発について伺います。もともと品川区では、再開発事業を担当する部課長は都市環境部長と都市開発課長の２人だけでした。再開発を担当する部課長は、現在それぞれ何人いるのか、伺います。都市再開発法に基づく市街地再開発に投入してきた税金額は累計幾らになったのか伺います。その額は２３区の中では何番目になるのか伺います。","respondent":"有江都市整備推進担当部長","answer":"これまでの補助金の額と、順位ですけれども、現時点での２３区内での順位については把握しておりませんけれども、区からの補助金に関しましては、事業が完了したものと、現在事業中の事業が完了するまでの予定額を合わせまして、合計で約１,５３０億円になります。","voiceIndex":155,"id":"exchange-066"},{"speaker":"安藤委員","kind":"質問","question":"それぞれ３倍に増やしてきました。私は款別審査で、武蔵小山で既に建った２棟の超高層開発ビルについての状況について伺いました。改めて、武蔵小山パルム駅前地区・駅前通り地区、それぞれについて伺いますが、事業協力企業名、できた開発ビルの住戸数と店舗数、税金投入額と容積率は何％から何％上乗せしたのか、また従前の地権者数、土地所有者数と借地権者数、商業店舗数も伺いたいと思います。","respondent":"有江都市整備推進担当部長","answer":"従前の権利者数ですけれども、組合設立時におきましては、共有者名義を個々に数えると、土地所有者数が２名、借地権者数が１１３名で、従前店舗数につきましては、詳細について区は把握しておりませんけれども、約１００店舗程度と考えております。","voiceIndex":157,"id":"exchange-067"},{"speaker":"安藤委員","kind":"質問","question":"私は款別審査で、開発終了後にどれだけの地権者が戻ってこられたのかと伺うと、区は、把握はしているが個人情報であり、再開発準備組合が非公表としているので公開しないと、答弁を拒否しました。では伺いますが、２地区について、地権者のうち何％の方が戻ってこられたのか、割合を伺います。割合なら答えられるのではないでしょうか。なぜ公表できないのか、改めて伺いたいと思います。","respondent":"有江都市整備推進担当部長","answer":"パルム駅前地区および駅前通り地区におきましての、戻ってきた地権者の数ですけれども、再開発組合に確認したところ、現在事業中でありまして、個人情報に関する情報につきましては非公表ということで、区としては聞いております。","voiceIndex":159,"id":"exchange-068"},{"speaker":"安藤委員","kind":"質問","question":"割合について伺ったのですが、割合はお答えできないでしょうか。ただの１民間団体ではありません。再開発ビルに入った権利者の数を公開しないという組合の言い分は、私は通用しないと思いますが、いかがでしょうか。なぜ品川区は再開発組合の言いなりになるのか、伺います。地元の住民の方に伺うと、戻ってきた地権者は、両地区とも僅か２名ですとおっしゃるのです。どうでしょうか。伺います。","respondent":"有江都市整備推進担当部長","answer":"地域ごとの課題に対応し、住みやすさ、快適さを向上させて、地域の経済の活性化など、地域全体の発展を目標に進めておりまして、区としては、地域主体で進めているまちづくりについては支援したいと考えています。","voiceIndex":161,"id":"exchange-069"},{"speaker":"安藤委員","kind":"質問・要望","question":"こんな超高層再開発を、品川区はさらに小山三丁目第１地区・第２地区開発で事業認可を狙い、３棟も新たに建てようとしています。中止するよう強く求め、次の質問に移ります。その立場で質問していきたいと思います。経緯や事実を紹介するとともに、区教育委員会の認識を伺います。併せて、区教育委員会がいじめの重大事態だと判断したのはいつになるのか、伺います。","respondent":"米田教育次長","answer":"学校では、被害生徒の訴えの後、直ちにこれをいじめと認知するとともに教育委員会に報告し、警察とも協力しながら、いじめ行為の停止に向け、生徒への指導や調査を行うなどの対応を行ってまいりましたが、いじめを解消することができず。","voiceIndex":163,"id":"exchange-070"},{"speaker":"安藤委員","kind":"質問・要望","question":"このいじめにより、被害生徒は救急搬送を３回、６回意識を失いました。なぜ区教育委員会は、このような事態を把握していたにもかかわらず、いじめの重大事態と捉えることができなかったのか、伺います。２２ページの部分です。伺いたいと思います。なぜ区教育委員会事務局は、これだけの事態に際し、受け身で対応したのか、何が原因だったのか、今後こうした姿勢は変わるのか、伺いたいと思います。","respondent":"米田教育次長","answer":"このいじめにつきまして、教育委員会は、学校からの報告の下、いじめ行為の停止に向けた取組について、学校訪問や関係機関を交えたケース会議にて今後の対策を検討するなど、当時できる対応は行ってまいりました。","voiceIndex":165,"id":"exchange-071"},{"speaker":"安藤委員","kind":"質問","question":"区教育委員会は、「調査が終わったら報告しようと思っていました」というような答弁だったと思います。他の３件の重大事態について、これは法における生命心身財産重大事態なのか、不登校重大事態なのか、伺います。調査結果はいつ頃出るのでしょうか。被害者保護者による申出なのかなど、どのような経緯で重大事態と認定されたのか、伺いたいと思います。区教育委員会の認識を伺いたいと思います。","respondent":"米田教育次長","answer":"品川区いじめ対策委員会で、この案件につきましては現在、調査中の案件となっています。こちらの詳細についての説明につきましては、調査終了時に区長へ報告するほか、ご家族の了承を得た上で、区ホームページへの公表、議会への報告をします。","voiceIndex":167,"id":"exchange-072"},{"speaker":"安藤委員","kind":"質問","question":"最後に、今後の対策の具体化について伺いたいのですが、２０１２年の区内での痛ましいいじめ自殺の事態を受け、様々な体制を取ってきたと思います。対応もできなかった。これまでのいじめ対策の何が悪かったのか、何が足りなかったと考えているのか、伺います。併せまして、報告書の検討事項、提言を受けて、区教育委員会はいじめ解決防止のためにどんな対策を取るのか、伺いたいと思います。","respondent":"米田教育次長","answer":"教育委員会ではこの１０年間、ご紹介のありました痛ましい事件と同種の痛ましいいじめ事案を起こさぬよう、人権尊重を最重要視し、品川区いじめ根絶宣言の策定、各校におけるいじめ根絶宣言の作成と掲示、品川教育の日による学校間の情報共有や、いじめ防止に関する講演会の実施。","voiceIndex":169,"id":"exchange-073"},{"speaker":"安藤委員","kind":"質問","question":"しかし、その体制ですが、１年ごとの任期である会計年度任用職員３名のみなのです。区長部局設置のいじめ相談窓口は、報告書の提言が確保要件とする、いじめ事案を迅速に解決するのに必要なリソース・権限を有する組織になっているのか伺います。会計年度任用職員の体制で、組織としていじめ事案に取り組むノウハウを蓄積するということも書いているのですけれども、これができるのか、伺いたいと思います。","respondent":"堀越総務部長","answer":"つい先月、９月、寝屋川市に職員を派遣し、視察を行ったところでありまして、区での事例を積み重ねることと併せて、他の自治体で発生した事案での対応や取組を絶えず確認し、それらも参考に、組織としていじめ事案に取り組むノウハウを蓄積していきたいと考えております。","voiceIndex":171,"id":"exchange-074"},{"speaker":"安藤委員","kind":"質問","question":"様々、対策が語られました。これが現場の実態なのですけれども、これでどうして、対策を取る、今後は大丈夫だと思えるのでしょうか。私は、この事例を教訓にすべきだと思います。そのためにも、対策委員会、調査委員会、２冊の報告書を全ての教職員に手渡して読んでもらい、全ての学校で話合いを持つよう、区教育委員会はすべきだと思いますけれども、この点について、いかがでしょうか。","respondent":"米田教育次長","answer":"今回、指導報告書２点につきましては、５月と９月に各学校には電子データで配布しています。校長・園長連絡会においても、調査結果の趣旨について説明しております。学校では年３回以上の校内研修会実施を義務づけておりまして、併せて２つの調査報告書の活用も求めております。","voiceIndex":173,"id":"exchange-075"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひ、実際に議論をしていただきたいと思います。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":175,"id":"exchange-076"},{"speaker":"藤原委員","kind":"質問","question":"西大井の駅前の活性化についてお伺いします。私はこの質問をすると、本当にわくわくします。これから西大井がどう変わっていくかという思いで、答弁する方々、西大井を想像して答弁してください。それと、今まで言われているとおり、３,０００人の社員の方々が増える。これも間違いないでしょうか。それと、西大井の近辺の新しい開発の状況というのは、どういうふうになっているでしょうか。教えてください。","respondent":"中村都市環境部長、有江都市整備推進担当部長","answer":"ニコン本社の西大井の移転です。こちらにつきましては、現在、本社家屋を工事中で、建設も順調に進んでいるということを聞いております。当初の計画どおり、令和６年春に竣工、そして夏から稼働という予定ということです。区ではこれらのまちづくりの動向や、先ほどのニコン本社の移転などもあることから、土地の利用状況や交通量などの基礎調査を今年度、実施しておりまして、まちの状況把握に努めております。","voiceIndex":178,"id":"exchange-077"},{"speaker":"藤原委員","kind":"質問・要望","question":"何回も何回も要望しておりますが、もう、早く西口改札口を作っていただきたい。これもぜひ要望していただきたいと考えています。線路があるわけですから、高崎線は通過しないで、ぜひ、とめていただきたいと考えています。西大井駅前広場。ホームドアの設置はどうなっているでしょうか。なので、ぜひ７時半から８時半はスクールゾーンにしていただきたいのですけれども、この辺についてはいかがでしょうか。","respondent":"中村都市環境部長、溝口防災まちづくり部長、川島地域振興部長","answer":"それから可動式ホームドアの実施についてですけれども、こちらは、ＪＲから設置については確約を頂いているところですけれども。これに併せて、西大井駅周辺の、問題になっております駐輪対策といったものに対しても、解決できるように進めていきたいと考えておりますし。今後も西大井の地域特性や特色を活かしまして、駅周辺の活性化に貢献する施設となるように創業支援を進めてまいりたいと考えています。","voiceIndex":181,"id":"exchange-078"},{"speaker":"藤原委員","kind":"質問・要望","question":"今、東側を伺ったのですけれども、次に西側をお伺いしたいと思います。西側というのは、不燃化特区地区が、西大井四丁目、二葉、豊町と、すごく広がっているのですけれども、令和７年で一応終わると思うのですけれども、私は５年延長して令和１２年まで、やはりこの事業は最後までやり遂げなくてはいけないと思っているのですけれども、東京都の要望を含め、その辺はいかがでしょうか。","respondent":"米田教育次長、廣田文化スポーツ振興部長、中村都市環境部長","answer":"ご案内のように、伊藤小学校の校門のところには看板がございまして、伊藤小学校の由来ということで、もともと大井伊藤町という町名に基づいて。このような貴重な史跡につきましては、今現在も観光協会が、まち歩きツアーなどを行うなどして様々な取組を進めているところですけれども。令和７年度までの事業期間として不燃化特区の促進を今行っておりますけれども。","voiceIndex":185,"id":"exchange-079"},{"speaker":"藤原委員","kind":"質問","question":"これからの西大井駅周辺まちづくり、本当に期待しております。でも、定年の年齢が延びたのだから、これからずっとまだまだできるじゃないですか」と。「だって、役職定年があるから、もう答弁できないかもしれない」、「えっ、どういうこと」、「だって、課長補佐になっちゃうんだもん。これについては、しっかり対策をしていかないといけないと思うのですけれども、いかがでしょうか。","respondent":"堀越総務部長","answer":"国でもいろいろな総務省の検討会で、人材確保に向けた検討がついこの間始まったと新聞報道等にもありましたので、それを踏まえつつ、やはり職員の能力を発揮し、やりがい、充実感、生き生きと職務に取り組めるように、研修や、キャリアプランの早め早めの提示など。","voiceIndex":189,"id":"exchange-080"},{"speaker":"藤原委員","kind":"質問・要望","question":"総務部長、いずれでいいですから、今の答弁は「他の自治体も」という答弁でしたけれども、「ほかの自治体は二、三十代が辞めていってしまうけれども、品川区はしっかり維持しています」という区になるといいですね。答弁は大丈夫です。公営掲示板のポスター、今回、４９から６０の方は、高かったから本当に苦労されたと思うのです。ですから、脚立がないとという方もいらっしゃいました。確認します。","respondent":"鈴木選挙管理委員会事務局長","answer":"それから２点目の、国、都道府県、それから区市町村の議員の方々の上下がないですが、これはご指摘の通りでございまして、それぞれご自分の選挙区内にある有権者の方または住民の方のために仕事をされているということで、そこに上下はないと認識しております。","voiceIndex":191,"id":"exchange-081"},{"speaker":"藤原委員","kind":"質問","question":"そうですよね。平等なのに、例えばポスターの枚数は、国会議員、都議会議員は２倍です。事務所の立て看版は３枚出るのですよね。個人演説会の看板も３枚分、公費で出ますよね。私は、そういうところで差がついてはいけないと思うし、こういうことを選挙管理委員会で話すのではないのですか。今、品川区選挙管理委員会は平均月何回ですか。１回の会議は何時間ですか。この辺については、いかがでしょうか。","respondent":"鈴木選挙管理委員会事務局長","answer":"ただし、項目としては、基本的に地方自治体が条例で定めて、公費負担とできるものについては品川区でも全て対応していますので、そのための違いであって、平等性を欠くものではないと認識しています。","voiceIndex":193,"id":"exchange-082"},{"speaker":"藤原委員","kind":"質問・要望","question":"私は要望するしかできないのです。だから、まず部長、お願いは、この複雑さを、役所に電話ができればすぐ対応してくれるというような人材確保をしてほしいというのが１点です。こういうことについていかがでしょうか。対面でできるのですか。それと、これだけが介護予防ですという１点ではないじゃないですか。どんどん要望していっていただきたいと思うのです。その辺については、いかがでしょうか。","respondent":"今井福祉部長、阿部健康推進部長","answer":"これを支えているのも、私ども職員だけではなく、地域づくり推進委員の皆様や、いろいろな事業者に実施していただいている事業もありますので、引き続ききちんと介護予防につきましては、区の職員、そして民間の事業者のお力。実施日数を増やすことにつきましては、現在の事業のスキームが、本来の浴場の開場時間より１時間前倒しで開けていただくというところもありまして、公衆浴場組合や委託先の都合をいろいろ勘案しなければいけませんので。","voiceIndex":195,"id":"exchange-083"},{"speaker":"藤原委員","kind":"質問・要望","question":"企画部にどんどん人材を求めて大丈夫ですよ。今、一生懸命、企画部でやってくださっているのですから。そうですよね。これは最後に時間があったら聞きますが、新井新副区長、私だけではなくて、いろいろな方のいろいろな質問、答弁を聞いて、品川区、２３区は、本当に細かく区民の方と接しているでしょう。そして、なぜ品川区に来てくれたか教えてください。それも伺いたいので、まず３点、お伺いします。","respondent":"新井副区長","answer":"その上でなのですけれども、財政調整も含めてですけれども、私自身、９月２２日にまさに区民の代表である区議会の皆様からご同意いただいて今この場にいるわけですから、言うまでもなく、品川区政のため、あるいは区民のために汗をかいていきたいと強く思っているところです。","voiceIndex":198,"id":"exchange-084"},{"speaker":"藤原委員","kind":"質問・要望","question":"何か、私の質問だったのですけれども、就任の挨拶みたいに。いや、すばらしいですね。それで、新井新副区長、東京都を退職なさるときに小池都知事には挨拶に行かれたのですか。そのノウハウ。東京都の企画というか中心にいた方ですから、いろいろなやり方が分かると思うのです。だから、その辺をぜひ品川区のために使っていただきたいと思うのですけれども、その２点だけもう一回、答弁いただけますか。","respondent":"新井副区長","answer":"都庁を辞めるときに小池知事から何か言葉をもらったかという話は、２人で会った場なので、具体はあれですけれども、温かく送り出していただき、正直、私のほうから品川区に行きたいと申し出て、知事に理解を頂いたという部分があるので、そこは本当に感謝を申し上げたとともに。","voiceIndex":200,"id":"exchange-085"},{"speaker":"藤原委員","kind":"質問","question":"区長の１００の政策の中の８７、８８が私は好きなのです。８７、８８の一つは、区長の退職金を２割カットし、区長の給与を２割カットする。そういう区民とのお約束。だって区長は、１％、２０億円と書いていらっしゃいます。担当部長、いつまでに２０億円にするのですか。そして、１０年ですよね。そして、限りなく２０億円に近づけますという答弁を頂きたいと思っているのですけれども、いかがでしょうか。","respondent":"久保田企画部長","answer":"財源の確保につきましても、１％、２０億円ということを区長も公約で掲げておりますので、我々もそれにできるだけ近づく形で、２０億円、財源を確保するような形で、また、そうした財源を捻出したものにつきましては。","voiceIndex":202,"id":"exchange-086"},{"speaker":"藤原委員","kind":"質問・要望","question":"区長、事務事業評価は、最後の英断は区長だと私は思っております。ぜひ目標を達成するために英断を下していっていただきたいと思いますが、最後にその辺の答弁を頂けますか。","respondent":"森澤区長","answer":"そういったことをしっかりと行っていきたいと思います。そしてまた、先ほど来ご指摘いただいておりますけれども、選挙でも掲げさせていただきました。しっかりと、１％、２０億円ということを実現すべく、区の職員、皆さんと共に一緒に取り組んでいきたいと考えています。","voiceIndex":206,"id":"exchange-087"},{"speaker":"松本委員","kind":"質問・要望","question":"品川区のいじめ対策について伺います。そこで、まず品川区いじめ問題調査委員会の答申で認定されている事実および評価について、教育委員会として真実ではないと考える点、または評価が不当であると考える点があるのか伺います。先ほど教育委員会からの答弁もありましたが、区長部局として、この点、なぜこういう対応になってしまったのか、伺いたいと思います。","respondent":"米田教育次長、堀越総務部長","answer":"最初のお尋ねに、私からお答え申し上げます。調査委員会による報告書は、当時、教育委員会事務局で対応した職員もヒアリングを受け、それに基づき作成されたものです。区長部局としての原因分析についてですが、調査委員会の報告書と同様の認識に立っておりまして、いじめ重大事態に対する理解として、国の重大事態ガイドラインの内容も含めまして、どのような事態がいじめ重大事態に該当するのか。","voiceIndex":209,"id":"exchange-088"},{"speaker":"松本委員","kind":"質問・要望","question":"そこで、なぜ教育委員会が諮問した品川区いじめ対策委員会では、重大事態としての認知・対応の遅れの原因検証が行われていなかったり、教育委員会事務局担当者へのヒアリングが行われなかったのでしょうか、伺います。今後の対策として、いじめ対策委員会の調査においては、諮問文を工夫し、教育委員会事務局担当者へのヒアリングを必須としていただきたいと思いますが、いかがでしょうか。","respondent":"米田教育次長","answer":"教育委員会事務局の担当者は、学校教育委員会がこれまで対応してきた内容について、対策委員会に資料提供等を行っていたため、改めてのヒアリングは実施されておりませんでしたが、今後につきまして、教育委員会事務局の担当者もヒアリングを受けるような形で。","voiceIndex":212,"id":"exchange-089"},{"speaker":"松本委員","kind":"質問","question":"そちらを徹底していただければと思います。その原因はどこにあったのかと考えると、事務局といじめ対策委員、双方にあったのではないかと考えます。この両者の事務局体制の違いが、対策委員会答申と調査委員会答申の内容に差をもたらしたのではないかと考えますが、教育委員会の見解を伺います。同じ係だった場合は、双方の担当職員が同じだったのか、違ったのか、伺います。","respondent":"米田教育次長","answer":"調査委員会の答申についてですけれども、品川区いじめ対策委員会の調査内容の検証および調査結果の評価など、５項目について諮問を受け、調査を行ったものと認識しておりまして、その諮問事項に対する答申の中で、対策委員会等へのご指摘も頂いたものと受け止めてあります。","voiceIndex":214,"id":"exchange-090"},{"speaker":"松本委員","kind":"提案","question":"これはまた別途、提案させていただきたいと思いますが、本件では少なくとも、中立性の観点から、品川区いじめ対策委員会規則を改正し、品川区いじめ対策委員会の庶務を教育総合支援センターから教育委員会庶務課や指導課に移すべきではないかと考えますが、見解を伺います。弁護士といっても専門は様々です。行っていないとするならば、今後は推薦依頼を行うべきと考えますが、いかがでしょうか。","respondent":"米田教育次長","answer":"今後、委員に欠員が生じた際などの推薦の依頼について、弁護士会等ということでのご提案を頂きましたけれども、様々な手法を凝らすことが必要と考えていますので、それも１つの案として検討させていただければと思います。","voiceIndex":216,"id":"exchange-091"},{"speaker":"松本委員","kind":"質問・要望","question":"対応が遅れた結果、責任者が退任・退職してしまった事案では、給料・報酬の自主返納を求める事例もあります。伺います。そこでお伺いしますが、いじめに関する報告は、学校から教育委員会にどのような手段で行われていたのでしょうか。今後は、今回問題になっているような、重大事態に当たるかどうかの相談も含めて、メール等、証拠が残るような手段によって行われるべきと考えますが、見解を伺います。","respondent":"米田教育次長","answer":"このように考えてあります。それから、いじめに関する報告なのですけれども、学校は毎月、定時および、また状況によってはその都度、いじめ実態調査報告書の書類にいじめの事実や対応を記録し、教育委員会に提出しております。","voiceIndex":218,"id":"exchange-092"},{"speaker":"松本委員","kind":"質問・要望","question":"処分の点ですが、再発防止に努めるというご発言でしたが、処分はしないということでよろしいのか、改めて伺います。なければ、そうしたおそれがある、可能性がある段階でも、学校側から教育委員会に対して、「こういう可能性が、該当するおそれがあるんですよ」というふうなチェックリストをチェックして、連絡していただく、相談していただくという体制を要望いたしますが、いかがでしょうか。","respondent":"米田教育次長","answer":"それから調査報告書については、例えばいじめの重大事態に相当するかどうかを判断できるようなチェック項目というのですか、微細にいろいろチェックをつけていただく欄がありますので、そういったものを活用して今やっておるところではありますけれども。","voiceIndex":220,"id":"exchange-093"},{"speaker":"松本委員","kind":"質問・要望","question":"より具体的な事例を挙げながら、重大事態はこういう事態だと事例を示しながら基準をつくっていただきたいと思いますが、この点について伺うとともに、現状、今どのように基準を設けていらっしゃるのか、伺いたいと思います。それに加えて、今回の答申では、効果検証・効果測定についても述べられています。テストを行うのであれば、これを区議会に公開していただきたいと思いますが、見解を伺います。","respondent":"米田教育次長","answer":"こういった形を踏まえた効果検証といいますか、今回は振り返りを行っているわけですが、今後、いじめの認知件数、認知率などの具体的な数値の公表や、また次年度に向けていじめ予防プログラムの実施などの検討も進めてまいりますので、その内容と併せて効果検証等についても。","voiceIndex":222,"id":"exchange-094"},{"speaker":"松本委員","kind":"質問・要望","question":"分かっていると思っても、実際には分かっていなかった、認定できなかったという可能性もあります。テストのような形で、こういう事案の場合はどうですかというふうに検証していただきたいと思いますが、いかがでしょうか。防犯カメラを、今回昇降口に、まだ恐らく全部の学校に設置できていないと思いますが、これは来年度の予算でしっかり予算要望を出していただきたいと思いますが、いかがでしょうか。","respondent":"米田教育次長、堀越総務部長","answer":"いじめに関していえば、個々の事案等を勘案しまして、必要に応じて設置等の対応を行っていければと考えているものです。これらを踏まえているものでございまして、これらの考え方により、区として総合的に効果的にしっかりと教育委員会と連携して対応してまいりたいと、このように考えてあります。","voiceIndex":224,"id":"exchange-095"},{"speaker":"西村委員","kind":"質問・要望","question":"品川区議会自民党・無所属の会は、令和４年度品川区一般会計、国民健康保険事業会計、後期高齢者医療特別会計、介護保険特別会計、災害復旧特別会計、全ての歳入歳出決算を認定いたします。本決算特別委員会において、我が会派の委員より、区民の皆様や各種団体などから頂きました声をまとめた上、令和５年度の品川区予算事務事業に反映され、実現されることを期待し、意見、要望、政策提言をいたしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":229,"id":"exchange-096"},{"speaker":"若林委員","kind":"質問・要望","question":"品川区議会公明党の意見表明を行います。令和４年度品川区一般会計は、歳入総額１,９５９億円余で執行率９３.１％、実質収支は６２億円余の黒字、財政健全化判断比率も良好と認められました。本決算特別委員会を通じ、会派からの意見・要望を真摯に受け止められ、今後の区政運営および来年度予算に反映されるよう求め、意見表明といたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":231,"id":"exchange-097"},{"speaker":"松永副委員長","kind":"提案","question":"令和４年度の一般会計は、歳入総額約１,９５９億円、歳出総額約１,８９３億円、執行率が９３.１％となり、普通会計の実質収支も約６２億円を超える黒字となっており、財政健全化判断比率においても適正であり、健全財政を維持していることを確認しました。今後も区民生活の福祉向上に向け、施策を確実に実行していただくよう求めます。以上で、しながわ未来の意見表明といたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":233,"id":"exchange-098"},{"speaker":"鈴木委員","kind":"質問・要望","question":"区は、ＪＲ東海に対して説明会開催を求め、区民への説明責任を果たさせるべきです。そして、トラブル続き、問題だらけのリニア新幹線は、本掘進に入る前の今こそ、中止の決断を求めていただきたい。年度ごとのＣＯ２削減目標とその具体化を明確に示し、ＰＤＣＡサイクルでの検証を求めます。後期高齢者医療は、令和４年１０月から実施の２割負担を、元に戻すよう国に求めること。１８歳まで無料化を求めます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":235,"id":"exchange-099"},{"speaker":"須貝委員","kind":"提案","question":"令和４年度の一般会計、国民健康保険事業会計と後期高齢者医療・介護保険・災害復旧の特別会計の各決算を、品川改革連合は認定いたします。羽田新飛行ルートの変更を国に働き続けていただきたい。先ほど藤原委員が提案した選挙管理委員の給与は、時給に換算すると １０万円にもなり高額なので、他の自治体のように日当３万円の出会手当にするべきです。以上、品川改革連合の意見表明を終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":237,"id":"exchange-100"},{"speaker":"せらく委員","kind":"提案","question":"本年度の形式収支は約６５億円の黒字となりました。今回の決算特別委員会において、弊会派の各委員の質疑の中で指摘・提案した点について検討され、次年度の予算や今後の施策・事業に反映していただくよう要望するとともに、区が遂行する政策等については評価・検証・改善を徹底していただき、区民サービスの向上が図られることを求め、品川区議会日本維新の会の意見表明といたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":239,"id":"exchange-101"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1544#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":111302,"voices":245}},{"id":"r05-20231023-10","meetingId":"r05-cm10","date":"2023年10月23日","dateIso":"2023-10-23","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時０２分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5518#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":10459,"voices":39}},{"id":"r05-20231107-6","meetingId":"r05-cm11","date":"2023年11月7日","dateIso":"2023-11-07","committee":"区民委員会","time":"午後 １時００分～午後 １時２６分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を10件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"しながわシティランの検討状況","agenda":"しながわシティランの検討状況","exchanges":[{"speaker":"えのした委員","kind":"確認","question":"もう１点、（４）プレ大会・記念イベント、私も今年、マラソン大会に参加させていただきましたが、このプレ大会と一緒に記念イベントをやるのか、それとも別で開催されるのか、そちらだけ確認を。","respondent":"三井スポーツ推進課長","answer":"（４）プレ大会・記念イベントですが、記念イベントについては、できればプレ大会とは別にできないかということで、今検討を進めているところになります。","voiceIndex":8,"id":"exchange-001"},{"speaker":"あくつ委員","kind":"質問","question":"旧東海道を結構大胆に走るコースなのだなということで、かなりの困難も予想される中で、いや、でも旧東海道の魅力を感じてもらえるというところでは、本当に思い切られたなということで、非常に期待したいなと思います。その辺りを教えてください。","respondent":"三井スポーツ推進課長","answer":"募集時期についてはまだ検討中で、いつからというのははっきり決まっておりませんが、大体来年度に入ってから、一応当初の想定で、第１回実行委員会で案としてお示ししたのは、来年９月頃から大体１１月までということで、それはただ本当に案の案という形で。","voiceIndex":12,"id":"exchange-002"},{"speaker":"横山委員","kind":"確認","question":"ご説明ありがとうございました。幾つか伺っていくのですけれども、まず別紙１なのですが、主催がしながわシティラン実行委員会、主管が品川区陸上競技協会ということで、役割分担の違いを教えていただけたらと思いました。１１の参加料なのですけれども、この参加料を算出した根拠というか、この辺りを確認させてください。そこからお願いします。","respondent":"三井スポーツ推進課長","answer":"参加料もまだ精査中でして、この金額で決まったというわけではないので、今後、他自治体なども参考にしながら、これから検討していくことになっております。","voiceIndex":15,"id":"exchange-003"},{"speaker":"横山委員","kind":"質問・要望","question":"今回初めて実施するので、なかなか難しい部分かと思うのですけれども、群集マネージャーみたいな方からご意見をお伺いしたりですとか、人の自然な流れといったところで、大きなエリアの中でどういった形で、２,５００人の参加者がいらっしゃって、応援の方がどれくらいなどという、何となくの想定というのも、群集マネジメントに詳しい方というのはいろいろ知見等もあるかと思いますので。","respondent":"三井スポーツ推進課長","answer":"具体的に群集マネジメントという言葉で特に検討しているところはないのですが、実際にコンサル等が入りまして、２,５００人がしながわ区民公園スタートで旧東海道を走っていくというルートは、狭いルートにもなるので、そこの誘導等はしっかり考えていきたいと考えております。","voiceIndex":17,"id":"exchange-004"},{"speaker":"横山委員","kind":"質問・要望","question":"例えば花火大会ですとか、大きなイベントの際に、群集マネジメントの動線を事前に考えているか、いないかというところで、大きな事故につながる可能性をすごく軽減できるかと思いますので、ぜひ引き続き検討を進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-005"},{"speaker":"山本委員","kind":"質問","question":"私からも１点質問させてください。協賛企業の募集というところなのですけれども、これは今後進めていかれると思うのですが、品川区内だったり、区外だったり、スポーツ関連だったり、いろいろあると思うのですが、どのような企業にどのような募集、声掛けをされていく予定でしょうか。","respondent":"三井スポーツ推進課長","answer":"協賛企業の募集について、これから協賛を募るためのメニュー案等を今検討しているところでして、それについて、基本的には区内の企業等を考えております。","voiceIndex":21,"id":"exchange-006"},{"speaker":"山本委員","kind":"意見","question":"地元品川区でのシティランということで、品川区の企業の皆さんにできるだけ幅広く協賛いただくのがよいかなと私も考えております。現物でのサポート等、いろいろな協賛の仕方があると思いますので、そういったところにも工夫など、ご検討いただければと思いました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":23,"id":"exchange-007"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"別紙１の１１、ファミリーランのところに「ペア」と記載されているのですけれども、これは何人までとか、ペアというのは、親と子だけれども、お子さんが２人いる場合とか、そういうときはペアというこの表現はどうなのかなと思い、伺いたいと思います。","respondent":"三井スポーツ推進課長","answer":"こちらもこれから詳細を詰めていく中で変更はあるかもしれませんが、現時点でペアとしているのは親と子で、２人で出て、例えば下の子も一緒に出たいというのは、同伴は可能にしようかというような検討も含めてしているところで、ペアで実際にゼッケンを着けて走るのは。","voiceIndex":25,"id":"exchange-008"},{"speaker":"せらく委員","kind":"質問","question":"ロゴマークの公募について伺いたいのですけれども、今月下旬から公募を始めるということで、要件などが決まってきているのではないかと思うのですが、このロゴマークは今回限りのマークになる予定でしょうか。今後ずっと使うのかということを聞きたいのと、あと、公募の周知方法もお聞かせいただければと思います。","respondent":"三井スポーツ推進課長","answer":"今回公募する公式ロゴマークについては、今後ずっと使うものを公募するようなことをイメージしておりまして、１回だけで終了というよりは、しながわシティランで今後も使う公式ロゴマークということで公募する予定で進めております。","voiceIndex":28,"id":"exchange-009"},{"speaker":"せらく委員","kind":"質問・要望","question":"１点だけ、コース案について、しながわ区民公園がスタートということで、今、予定として大人の方の１０ｋｍの定員が２,５００人で、スタート地点の待機方法なども考慮されているのか。まだコース案なのでこれからだと思うのですけれども、そういったところもスムーズな動線を確保していただきたいと思います。これは意見というか、要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":30,"id":"exchange-010"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2972#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":8542,"voices":36}}]);
